import { Permission, RoleDefinition, UserRole } from '../types';

const STORAGE_KEY_ROLES = 'manara_sis_roles';

const DEFAULT_ROLES: RoleDefinition[] = [
  {
    id: UserRole.ADMIN,
    name: 'المسؤول العام',
    description: 'صلاحيات كاملة للتحكم في كافة جوانب النظام.',
    isSystem: true,
    permissions: Object.values(Permission)
  },
  {
    id: UserRole.REGISTRAR,
    name: 'مسجل الكلية',
    description: 'إدارة الطلاب، الدرجات، والمقررات الأكاديمية.',
    isSystem: true,
    permissions: [
      Permission.STUDENTS_VIEW,
      Permission.STUDENTS_EDIT,
      Permission.GRADES_VIEW,
      Permission.GRADES_EDIT,
      Permission.ACADEMICS_MANAGE,
      Permission.REQUESTS_MANAGE,
      Permission.REPORTS_VIEW
    ]
  },
  {
    id: UserRole.FINANCE,
    name: 'الإدارة المالية',
    description: 'إدارة الرسوم، المدفوعات، والتقارير المالية.',
    isSystem: true,
    permissions: [
      Permission.FINANCE_VIEW,
      Permission.FINANCE_EDIT,
      Permission.REPORTS_VIEW
    ]
  },
  {
    id: UserRole.FACULTY,
    name: 'عضو هيئة تدريس',
    description: 'الاطلاع على الجداول، الطلاب، ورصد الحضور.',
    isSystem: true,
    permissions: [
      Permission.STUDENTS_VIEW,
      Permission.GRADES_VIEW,
      Permission.ATTENDANCE_MANAGE,
      Permission.REPORTS_VIEW
    ]
  }
];

export const getRoles = (): RoleDefinition[] => {
  const data = localStorage.getItem(STORAGE_KEY_ROLES);
  if (!data) {
    localStorage.setItem(STORAGE_KEY_ROLES, JSON.stringify(DEFAULT_ROLES));
    return DEFAULT_ROLES;
  }
  return JSON.parse(data);
};

export const getRoleById = (id: string): RoleDefinition | undefined => {
  return getRoles().find(r => r.id === id);
};

export const saveRole = (role: RoleDefinition): void => {
  const roles = getRoles();
  const index = roles.findIndex(r => r.id === role.id);
  if (index >= 0) {
    roles[index] = role;
  } else {
    roles.push(role);
  }
  localStorage.setItem(STORAGE_KEY_ROLES, JSON.stringify(roles));
};

export const deleteRole = (id: string): void => {
  const roles = getRoles();
  const role = roles.find(r => r.id === id);
  if (role?.isSystem) return; // Cannot delete system roles

  const filtered = roles.filter(r => r.id !== id);
  localStorage.setItem(STORAGE_KEY_ROLES, JSON.stringify(filtered));
};

export const getPermissionLabel = (p: Permission): string => {
  const labels: Record<Permission, string> = {
    [Permission.STUDENTS_VIEW]: 'عرض بيانات الطلاب',
    [Permission.STUDENTS_EDIT]: 'إضافة وتعديل الطلاب',
    [Permission.STUDENTS_DELETE]: 'حذف الطلاب',
    [Permission.GRADES_VIEW]: 'عرض كشف الدرجات',
    [Permission.GRADES_EDIT]: 'رصد وتعديل الدرجات',
    [Permission.ACADEMICS_MANAGE]: 'إدارة المقررات الدراسية',
    [Permission.FINANCE_VIEW]: 'عرض البيانات المالية',
    [Permission.FINANCE_EDIT]: 'إدارة الرسوم والمدفوعات',
    [Permission.FACULTY_MANAGE]: 'إدارة شؤون أعضاء التدريس',
    [Permission.ATTENDANCE_MANAGE]: 'رصد الحضور والغياب',
    [Permission.REQUESTS_MANAGE]: 'إدارة الطلبات والخدمات',
    [Permission.REPORTS_VIEW]: 'عرض التقارير والإحصائيات',
    [Permission.SETTINGS_MANAGE]: 'إدارة إعدادات النظام',
    [Permission.ROLES_MANAGE]: 'إدارة الأدوار والصلاحيات'
  };
  return labels[p] || p;
};

import { AuthUser, UserRole, Permission } from '../types';
import { getRoleById } from './rbacService';

const STORAGE_KEY_SESSION = 'manara_session_user';

// Mock Users for Simulation
const MOCK_USERS: AuthUser[] = [
    { id: '1', username: 'admin', name: 'المسؤول العام', role: UserRole.ADMIN },
    { id: '2', username: 'registrar', name: 'موظف التسجيل', role: UserRole.REGISTRAR },
    { id: '3', username: 'finance', name: 'الموظف المالي', role: UserRole.FINANCE },
    { id: '4', username: 'faculty', name: 'عضو هيئة تدريس', role: UserRole.FACULTY },
];

export const login = async (username: string, password: string): Promise<AuthUser> => {
    // Simulate API delay
    await new Promise(resolve => setTimeout(resolve, 600));

    // Simple password check (In real app, hash checking)
    // For this demo, password is same as username
    if (password === username) {
        const user = MOCK_USERS.find(u => u.username === username);
        if (user) {
            localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(user));
            return user;
        }
    }
    throw new Error('بيانات الدخول غير صحيحة');
};

export const logout = () => {
    localStorage.removeItem(STORAGE_KEY_SESSION);
};

export const getCurrentUser = (): AuthUser | null => {
    const data = localStorage.getItem(STORAGE_KEY_SESSION);
    if (data) {
        try {
            return JSON.parse(data);
        } catch (e) {
            return null;
        }
    }
    return null;
};

// New Permission Logic: Checks if user's role has the required permission
export const hasPermission = (user: AuthUser | null, required: Permission | Permission[]): boolean => {
    if (!user) return false;

    const roleDef = getRoleById(user.role);
    if (!roleDef) return false;

    // Super Admin override (redundant if roleDef is correct, but safe)
    if (user.role === UserRole.ADMIN) return true;

    const permissions = Array.isArray(required) ? required : [required];
    return permissions.every(p => roleDef.permissions.includes(p));
};

// Tab Access Mapping based on permissions
export const getAccessibleTabs = (user: AuthUser | null): string[] => {
    if (!user) return ['dashboard', 'regulations'];

    const tabs: { id: string, perms: Permission[] }[] = [
        { id: 'dashboard', perms: [] },
        { id: 'students', perms: [Permission.STUDENTS_VIEW] },
        { id: 'academics', perms: [Permission.ACADEMICS_MANAGE] },
        { id: 'schedule', perms: [Permission.ACADEMICS_MANAGE] },
        { id: 'exams', perms: [Permission.ACADEMICS_MANAGE] },
        { id: 'faculty', perms: [Permission.FACULTY_MANAGE] },
        { id: 'attendance', perms: [Permission.ATTENDANCE_MANAGE] },
        { id: 'financials', perms: [Permission.FINANCE_VIEW] },
        { id: 'requests', perms: [Permission.REQUESTS_MANAGE] },
        { id: 'reports', perms: [Permission.REPORTS_VIEW] },
        { id: 'graduates', perms: [Permission.STUDENTS_VIEW] },
        { id: 'roles', perms: [Permission.ROLES_MANAGE] },
        { id: 'regulations', perms: [] },
        { id: 'settings', perms: [Permission.SETTINGS_MANAGE] },
    ];

    return tabs
        .filter(tab => tab.perms.length === 0 || hasPermission(user, tab.perms))
        .map(tab => tab.id);
};

import React, { useState, useEffect } from 'react';
import { getRoles, saveRole, deleteRole, getPermissionLabel } from '../services/rbacService';
import { Permission, RoleDefinition, UserRole } from '../types';
import { Shield, Plus, Trash2, Edit2, CheckCircle, Info, Save, X, Settings } from 'lucide-react';
import { notifySuccess, notifyError, notifyInfo } from '../services/notificationService';
import { logAction } from '../services/auditService';

const RolesManagement: React.FC = () => {
  const [roles, setRoles] = useState<RoleDefinition[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);
  const [currentRole, setCurrentRole] = useState<RoleDefinition>({
    id: '',
    name: '',
    description: '',
    permissions: []
  });

  useEffect(() => {
    setRoles(getRoles());
  }, []);

  const handleTogglePermission = (p: Permission) => {
    setCurrentRole(prev => {
      const exists = prev.permissions.includes(p);
      if (exists) {
        return { ...prev, permissions: prev.permissions.filter(perm => perm !== p) };
      } else {
        return { ...prev, permissions: [...prev.permissions, p] };
      }
    });
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentRole.name) return;

    const roleToSave = {
      ...currentRole,
      id: currentRole.id || `custom_${Date.now()}`
    };

    saveRole(roleToSave);
    setRoles(getRoles());
    notifySuccess(isEditMode ? 'تم تحديث الدور بنجاح' : 'تم إنشاء الدور الجديد');
    logAction('إدارة الصلاحيات', `تم ${isEditMode ? 'تحديث' : 'إنشاء'} الدور: ${roleToSave.name}`, 'warning');
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => {
    const role = roles.find(r => r.id === id);
    if (role?.isSystem) {
        notifyError('لا يمكن حذف أدوار النظام الأساسية');
        return;
    }
    if (confirm('هل أنت متأكد من حذف هذا الدور؟ قد يؤثر ذلك على المستخدمين المرتبطين به.')) {
      deleteRole(id);
      setRoles(getRoles());
      notifyInfo('تم حذف الدور');
    }
  };

  return (
    <div className="p-8">
      <div className="mb-8 flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <Shield className="text-blue-600" />
            إدارة الأدوار والصلاحيات (RBAC)
          </h2>
          <p className="text-slate-500 mt-1">تخصيص مستويات الوصول والتحكم في مهام المستخدمين</p>
        </div>
        <button 
          onClick={() => {
            setIsEditMode(false);
            setCurrentRole({ id: '', name: '', description: '', permissions: [] });
            setIsModalOpen(true);
          }}
          className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700 shadow-sm transition-all active:scale-95"
        >
          <Plus size={20} />
          <span>إنشاء دور جديد</span>
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
        {roles.map(role => (
          <div key={role.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow flex flex-col">
            <div className={`h-1.5 ${role.isSystem ? 'bg-slate-800' : 'bg-blue-500'}`}></div>
            <div className="p-6 flex-1">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <h3 className="font-bold text-lg text-slate-800 flex items-center gap-2">
                    {role.name}
                    {role.isSystem && (
                      <span className="text-[10px] bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded border border-slate-200">نظام</span>
                    )}
                  </h3>
                  <p className="text-sm text-slate-500 mt-1 leading-relaxed">{role.description}</p>
                </div>
                <div className="bg-blue-50 text-blue-600 p-2 rounded-lg">
                  <Shield size={20} />
                </div>
              </div>

              <div className="space-y-2 mt-4">
                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">الصلاحيات الممنوحة ({role.permissions.length})</p>
                <div className="flex flex-wrap gap-1.5">
                  {role.permissions.slice(0, 5).map(p => (
                    <span key={p} className="bg-slate-50 text-slate-600 px-2 py-0.5 rounded text-[10px] border border-slate-100">
                      {getPermissionLabel(p)}
                    </span>
                  ))}
                  {role.permissions.length > 5 && (
                    <span className="text-[10px] text-slate-400 font-medium">+{role.permissions.length - 5} أخرى...</span>
                  )}
                  {role.permissions.length === 0 && <span className="text-xs text-slate-400 italic">لا توجد صلاحيات</span>}
                </div>
              </div>
            </div>

            <div className="p-4 bg-slate-50 border-t border-slate-100 flex justify-end gap-2">
              <button 
                onClick={() => {
                  setCurrentRole(role);
                  setIsEditMode(true);
                  setIsModalOpen(true);
                }}
                className="p-2 text-blue-600 hover:bg-blue-100 rounded-lg transition-colors"
              >
                <Edit2 size={18} />
              </button>
              {!role.isSystem && (
                <button 
                  onClick={() => handleDelete(role.id)}
                  className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                >
                  <Trash2 size={18} />
                </button>
              )}
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="bg-slate-900 text-white p-4 flex justify-between items-center">
              <h3 className="text-lg font-bold flex items-center gap-2">
                <Settings size={20} />
                {isEditMode ? 'تعديل الدور' : 'إنشاء دور جديد'}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-white">
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleSave} className="flex-1 flex flex-col overflow-hidden">
              <div className="p-6 flex-1 overflow-y-auto custom-scrollbar space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-bold text-slate-700 mb-2">اسم الدور</label>
                    <input 
                      required
                      type="text"
                      className="w-full border border-slate-300 rounded-xl px-4 py-2.5 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                      placeholder="مثلاً: مشرف مالي جونيور"
                      value={currentRole.name}
                      onChange={e => setCurrentRole({...currentRole, name: e.target.value})}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-slate-700 mb-2">الوصف</label>
                    <input 
                      type="text"
                      className="w-full border border-slate-300 rounded-xl px-4 py-2.5 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                      placeholder="وصف مختصر للمهام"
                      value={currentRole.description}
                      onChange={e => setCurrentRole({...currentRole, description: e.target.value})}
                    />
                  </div>
                </div>

                <div>
                  <div className="flex justify-between items-center mb-4">
                    <label className="text-sm font-bold text-slate-700">تخصيص الصلاحيات</label>
                    <span className="text-xs text-slate-400">تم اختيار {currentRole.permissions.length} من {Object.values(Permission).length}</span>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    {Object.values(Permission).map(p => {
                      const isSelected = currentRole.permissions.includes(p);
                      return (
                        <div 
                          key={p} 
                          onClick={() => handleTogglePermission(p)}
                          className={`flex items-center justify-between p-3 rounded-xl border transition-all cursor-pointer select-none ${
                            isSelected ? 'bg-blue-50 border-blue-200 ring-1 ring-blue-500/10' : 'bg-white border-slate-200 hover:border-slate-300'
                          }`}
                        >
                          <span className={`text-sm ${isSelected ? 'font-bold text-blue-700' : 'text-slate-600'}`}>
                            {getPermissionLabel(p)}
                          </span>
                          <div className={`w-5 h-5 rounded flex items-center justify-center transition-colors ${isSelected ? 'bg-blue-600 text-white' : 'border border-slate-300'}`}>
                            {isSelected && <CheckCircle size={14} />}
                          </div>
                        </div>
                      )
                    })}
                  </div>
                </div>

                <div className="bg-amber-50 border border-amber-200 p-4 rounded-xl flex gap-3 text-amber-800 text-xs">
                  <Info className="shrink-0" size={18} />
                  <p className="leading-relaxed">
                    تنبيه: الصلاحيات التي تمنحها لهذا الدور ستمكن المستخدمين المرتبطين به من الوصول لبيانات حساسة أو تعديلها. يرجى التوخي الدقة.
                  </p>
                </div>
              </div>

              <div className="p-4 bg-slate-50 border-t border-slate-200 flex justify-end gap-3">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-6 py-2 text-slate-600 hover:bg-slate-100 rounded-xl font-medium">إلغاء</button>
                <button 
                  type="submit" 
                  className="px-10 py-2.5 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 flex items-center gap-2 active:scale-95 transition-all"
                >
                  <Save size={20} />
                  حفظ الدور
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default RolesManagement;

import React, { useEffect, useState } from 'react';
import { LayoutDashboard, Users, BookOpen, GraduationCap, Settings, FileText, TrendingUp, Wallet, FileQuestion, Briefcase, UserCheck, Calendar, Clock, Shield } from 'lucide-react';
import { getStudents } from '../services/storageService';
import { StudentStatus, AuthUser, UserRole, Permission } from '../types';
import { getAccessibleTabs, hasPermission } from '../services/authService';

interface SidebarProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  currentUser: AuthUser;
}

const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, currentUser }) => {
  const [warningCount, setWarningCount] = useState(0);

  // Update badge count periodically or on render
  useEffect(() => {
    // Only fetch academic warning counts if user has permission to manage students
    if (hasPermission(currentUser, Permission.STUDENTS_VIEW)) {
        const fetchCounts = () => {
            const students = getStudents();
            const count = students.filter(s => s.warningsCount > 0 || s.status === StudentStatus.WARNING).length;
            setWarningCount(count);
        };

        fetchCounts();
        const interval = setInterval(fetchCounts, 5000);
        return () => clearInterval(interval);
    } else {
        setWarningCount(0);
    }
  }, [currentUser]);

  const allMenuItems = [
