import React, { useState, useEffect, useRef } from 'react';
import { getStudents, deleteStudent, saveStudent, checkNationalIdExists, bulkSaveStudents } from '../services/storageService';
import { Student, StudentStatus, ProgramType, UserRole, Permission } from '../types';
import { Search, Filter, Eye, Trash2, Plus, AlertCircle, X, Save, UserPlus, Edit2, SlidersHorizontal, Download, Upload, Image as ImageIcon, FileSpreadsheet } from 'lucide-react';
import StudentDetails from './StudentDetails';
import { notifySuccess, notifyError, notifyInfo } from '../services/notificationService';
import { logAction } from '../services/auditService';
import { getCurrentUser, hasPermission } from '../services/authService';

const StudentsList: React.FC = () => {
  const [students, setStudents] = useState<Student[]>([]);
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const currentUser = getCurrentUser();

  // Permissions
  const canEdit = hasPermission(currentUser, Permission.STUDENTS_EDIT);
  const canDelete = hasPermission(currentUser, Permission.STUDENTS_DELETE);

  // Search & Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [filters, setFilters] = useState({
      program: 'all',
      status: 'all',
      department: '',
      minGpa: '',
      maxGpa: '',
      year: ''
  });

  // Add/Edit Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);
  const [currentStudent, setCurrentStudent] = useState<Partial<Student>>({
    program: ProgramType.UNDERGRADUATE,
    department: '',
    name: '',
    nationalId: '',
    enrollmentYear: new Date().getFullYear(),
  });
  const [nationalIdError, setNationalIdError] = useState('');

  // Bulk Import State
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const refreshStudents = () => {
    setStudents(getStudents());
  };

  useEffect(() => {
    refreshStudents();
  }, []);

  // --- Filtering Logic ---

  const filteredStudents = students.filter(student => {
    // Basic Search
    const matchesSearch = 
        student.name.includes(searchTerm) || 
        student.id.includes(searchTerm) || 
        student.nationalId.includes(searchTerm);

    // Advanced Filters
    const matchesProgram = filters.program === 'all' || student.program === filters.program;
    const matchesStatus = filters.status === 'all' || student.status === filters.status;
    const matchesDept = !filters.department || student.department.includes(filters.department);
    const matchesYear = !filters.year || student.enrollmentYear.toString() === filters.year;

    // GPA Range
    const minG = filters.minGpa ? parseFloat(filters.minGpa) : 0;
    const maxG = filters.maxGpa ? parseFloat(filters.maxGpa) : 100;
    const matchesGpa = student.gpa >= minG && student.gpa <= maxG;

    // Special Risk Filter
    const matchesRisk = filters.status !== 'risk' || (student.warningsCount > 0 || student.status === StudentStatus.WARNING);

    return matchesSearch && matchesProgram && (filters.status === 'risk' ? matchesRisk : matchesStatus) && matchesDept && matchesYear && matchesGpa;
  });

  // --- Actions ---

  const handleDelete = (id: string) => {
    if (!canDelete) return;
    if (confirm('هل أنت متأكد من حذف هذا الطالب؟')) {
      deleteStudent(id);
      refreshStudents();
      logAction('حذف طالب', `تم حذف الطالب رقم ${id}`, 'danger');
      notifyInfo('تم حذف سجل الطالب');
    }
  };

  const handleOpenAdd = () => {
      setIsEditMode(false);
      setNationalIdError('');
      setCurrentStudent({
        program: ProgramType.UNDERGRADUATE,
        department: '',
        name: '',
        nationalId: '',
        enrollmentYear: new Date().getFullYear(),
        status: StudentStatus.ACTIVE
      });
      setIsModalOpen(true);
  };

  const handleOpenEdit = (student: Student) => {
      setIsEditMode(true);
      setNationalIdError('');
      setCurrentStudent({ ...student });
      setIsModalOpen(true);
  };

  const handleSaveStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentStudent.name || !currentStudent.nationalId || !currentStudent.department) return;

    // Validation
    if (checkNationalIdExists(currentStudent.nationalId, currentStudent.id)) {
        setNationalIdError('الرقم الوطني مسجل لطالب آخر بالفعل.');
        return;
    }

    let studentToSave: Student;

    if (isEditMode && currentStudent.id) {
        const original = students.find(s => s.id === currentStudent.id);
        studentToSave = {
            ...original!, 
            name: currentStudent.name!,
            nationalId: currentStudent.nationalId!,
            department: currentStudent.department!,
            program: currentStudent.program as ProgramType,
            enrollmentYear: currentStudent.enrollmentYear || original!.enrollmentYear,
            advisorName: currentStudent.advisorName
        };
        logAction('تعديل طالب', `تحديث بيانات الطالب ${studentToSave.name}`, 'info');
    } else {
        studentToSave = {
            id: `STU${new Date().getFullYear()}${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`,
            name: currentStudent.name!,
            nationalId: currentStudent.nationalId!,
            program: currentStudent.program as ProgramType,
            department: currentStudent.department!,
            enrollmentYear: currentStudent.enrollmentYear || new Date().getFullYear(),
            status: StudentStatus.ACTIVE,
            gpa: 0,
            warningsCount: 0,
            grades: [],
            advisorName: currentStudent.program === ProgramType.POSTGRADUATE ? 'لم يعين' : undefined
        };
        logAction('إضافة طالب', `تسجيل طالب جديد: ${studentToSave.name}`, 'info');
    }

    saveStudent(studentToSave);
    refreshStudents();
    setIsModalOpen(false);
    notifySuccess(isEditMode ? 'تم حفظ التعديلات' : 'تم تسجيل الطالب بنجاح');
  };

  const handleExportCSV = () => {
    if (filteredStudents.length === 0) {
        notifyError('لا توجد بيانات للتصدير');
        return;
    }

    const headers = ['المعرف', 'الاسم', 'الرقم الوطني', 'القسم', 'البرنامج', 'المعدل', 'الحالة', 'سنة القيد'];
    const csvContent = [
        headers.join(','),
        ...filteredStudents.map(s => 
            `${s.id},"${s.name}",${s.nationalId},"${s.department}",${s.program},${s.gpa},${s.status},${s.enrollmentYear}`
        )
    ].join('\n');

    const blob = new Blob([new Uint8Array([0xEF, 0xBB, 0xBF]), csvContent], { type: 'text/csv;charset=utf-8;' }); // BOM for Arabic Excel
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `Students_Export_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    notifySuccess('تم تحميل ملف CSV');
  };

  const handleBulkImport = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (event) => {
          const text = event.target?.result as string;
          // Simple CSV parsing (Assuming Format: Name,NationalID,Department,Program,Year)
          // Skip header row
          const rows = text.split('\n').slice(1);
          const newStudents: Student[] = [];

          rows.forEach(row => {
              const cols = row.split(',').map(c => c.trim().replace(/^"|"$/g, ''));
              if (cols.length >= 4) {
                  // Basic validation
                  if (checkNationalIdExists(cols[1])) return; // Skip duplicates

                  newStudents.push({
                      id: `STU${new Date().getFullYear()}${Math.floor(Math.random() * 100000).toString().padStart(4, '0')}`,
                      name: cols[0],
                      nationalId: cols[1],
                      department: cols[2],
                      program: cols[3].includes('عليا') ? ProgramType.POSTGRADUATE : ProgramType.UNDERGRADUATE,
                      enrollmentYear: parseInt(cols[4]) || new Date().getFullYear(),
                      status: StudentStatus.ACTIVE,
                      gpa: 0,
                      warningsCount: 0,
                      grades: []
                  });
              }
          });

          if (newStudents.length > 0) {
              bulkSaveStudents(newStudents);
              refreshStudents();
              notifySuccess(`تم استيراد ${newStudents.length} طالب بنجاح`);
              logAction('استيراد جماعي', `تم استيراد ${newStudents.length} طالب من ملف CSV`, 'warning');
          } else {
              notifyError('لم يتم استيراد أي بيانات. تأكد من تنسيق الملف وعدم وجود تكرار.');
          }
          setIsImportModalOpen(false);
      };
      reader.readAsText(file);
      e.target.value = ''; // Reset
  };

  return (
    <div className="p-8 relative">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">إدارة شؤون الطلاب</h2>
          <p className="text-slate-500">سجل القيد، البحث المتقدم، وإدارة الملفات</p>
        </div>
        {canEdit && (
            <div className="flex gap-2">
                <button 
                    onClick={() => setIsImportModalOpen(true)}
                    className="bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-slate-50 transition-colors shadow-sm"
                >
                <Upload size={18} />
                <span>استيراد</span>
                </button>
                <button 
                    onClick={handleExportCSV}
                    className="bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-slate-50 transition-colors shadow-sm"
                >
                <Download size={18} />
                <span>تصدير</span>
                </button>
                <button 
                    onClick={handleOpenAdd}
                    className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700 transition-colors shadow-sm"
                >
                <Plus size={20} />
                <span>تسجيل طالب</span>
                </button>
            </div>
        )}
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        {/* Search & Filter Bar */}
        <div className="p-4 border-b border-slate-100 bg-slate-50">
            <div className="flex flex-col gap-4">
                <div className="flex flex-col md:flex-row gap-4">
                    <div className="relative flex-1">
                        <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                        <input
                        type="text"
                        placeholder="بحث سريع (الاسم، الرقم الدراسي، الرقم الوطني)..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full pr-10 pl-4 py-2.5 rounded-lg border border-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                        />
                    </div>
                    <button 
                        onClick={() => setShowFilters(!showFilters)}
                        className={`px-4 py-2 rounded-lg border flex items-center gap-2 transition-colors ${showFilters ? 'bg-blue-50 border-blue-300 text-blue-700' : 'bg-white border-slate-300 text-slate-600'}`}
                    >
                        <SlidersHorizontal size={18} />
                        تصفية متقدمة
                    </button>
                </div>

                {/* Collapsible Filters Panel */}
                {showFilters && (
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 pt-2 animate-in slide-in-from-top-2 duration-200">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">البرنامج</label>
                            <select 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                                value={filters.program} onChange={(e) => setFilters({...filters, program: e.target.value})}
                            >
                                <option value="all">الكل</option>
                                <option value={ProgramType.UNDERGRADUATE}>{ProgramType.UNDERGRADUATE}</option>
                                <option value={ProgramType.POSTGRADUATE}>{ProgramType.POSTGRADUATE}</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">الحالة الأكاديمية</label>
                            <select 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                                value={filters.status} onChange={(e) => setFilters({...filters, status: e.target.value})}
                            >
                                <option value="all">الكل</option>
                                <option value="risk">⚠ متعثرين / إنذار</option>
                                <option value={StudentStatus.ACTIVE}>{StudentStatus.ACTIVE}</option>
                                <option value={StudentStatus.GRADUATED}>{StudentStatus.GRADUATED}</option>
                                <option value={StudentStatus.SUSPENDED}>{StudentStatus.SUSPENDED}</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">القسم</label>
                            <input 
                                type="text" 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                                placeholder="مثلاً: حاسوب"
                                value={filters.department} onChange={(e) => setFilters({...filters, department: e.target.value})}
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">نطاق المعدل (%)</label>
                            <div className="flex gap-2 items-center">
                                <input 
                                    type="number" placeholder="من" className="w-full border border-slate-300 rounded-lg px-2 py-2 text-sm text-center"
                                    value={filters.minGpa} onChange={(e) => setFilters({...filters, minGpa: e.target.value})}
                                />
                                <span className="text-slate-400">-</span>
                                <input 
                                    type="number" placeholder="إلى" className="w-full border border-slate-300 rounded-lg px-2 py-2 text-sm text-center"
                                    value={filters.maxGpa} onChange={(e) => setFilters({...filters, maxGpa: e.target.value})}
                                />
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-right">
            <thead className="bg-slate-50 text-slate-600 text-sm">
              <tr>
                <th className="px-6 py-4 font-semibold">الطالب</th>
                <th className="px-6 py-4 font-semibold">التخصص</th>
                <th className="px-6 py-4 font-semibold">البرنامج</th>
                <th className="px-6 py-4 font-semibold">المعدل</th>
                <th className="px-6 py-4 font-semibold">الحالة</th>
                <th className="px-6 py-4 font-semibold">إجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStudents.length > 0 ? (
                filteredStudents.map((student) => (
                  <tr key={student.id} className="hover:bg-slate-50 transition-colors group">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-full bg-slate-200 flex items-center justify-center font-bold text-slate-600">
                          {student.name.charAt(0)}
                        </div>
                        <div>
                          <p className="font-bold text-slate-800">{student.name}</p>
                          <p className="text-xs text-slate-500 font-mono">{student.id}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-slate-600">
                        {student.department}
                        <span className="block text-xs text-slate-400">دفعة {student.enrollmentYear}</span>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-1 rounded text-xs font-medium ${
                        student.program === ProgramType.POSTGRADUATE ? 'bg-purple-100 text-purple-700' : 'bg-blue-100 text-blue-700'
                      }`}>
                        {student.program}
                      </span>
                    </td>
                    <td className="px-6 py-4 font-bold text-slate-700">{student.gpa}%</td>
                    <td className="px-6 py-4">
                      {student.warningsCount > 0 && (
                        <div className="flex items-center gap-1 text-red-600 text-xs mb-1">
                          <AlertCircle size={12} />
                          <span>{student.warningsCount} إنذار</span>
                        </div>
                      )}
                      <span className={`inline-block px-2 py-1 rounded-full text-xs font-bold ${
                        student.status === StudentStatus.ACTIVE ? 'bg-green-100 text-green-700' : 
                        student.status === StudentStatus.WARNING ? 'bg-red-100 text-red-700' : 'bg-gray-100 text-gray-700'
                      }`}>
                        {student.status}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button 
                            onClick={() => setSelectedStudent(student)}
                            className="p-2 hover:bg-blue-50 text-blue-600 rounded-lg tooltip"
                            title="عرض الملف"
                        >
                          <Eye size={18} />
                        </button>
                        {canEdit && (
                            <>
                                <button 
                                    onClick={() => handleOpenEdit(student)}
                                    className="p-2 hover:bg-yellow-50 text-yellow-600 rounded-lg tooltip"
                                    title="تعديل البيانات"
                                >
                                <Edit2 size={18} />
                                </button>
                                {canDelete && (
                                    <button 
                                        onClick={() => handleDelete(student.id)}
                                        className="p-2 hover:bg-red-50 text-red-600 rounded-lg tooltip"
                                        title="حذف الطالب"
                                    >
                                    <Trash2 size={18} />
                                    </button>
                                )}
                            </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={6} className="px-6 py-12 text-center text-slate-400 bg-slate-50/50">
                    <Filter size={48} className="mx-auto mb-4 opacity-50"/>
                    <p className="font-medium">لا يوجد طلاب مطابقين لمعايير البحث</p>
                    <button onClick={() => {setSearchTerm(''); setFilters({program: 'all', status: 'all', department: '', minGpa: '', maxGpa: '', year: ''});}} className="text-blue-600 text-sm mt-2 hover:underline">
                        إعادة تعيين المرشحات
                    </button>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Detail View */}
      {selectedStudent && (
        <StudentDetails 
            student={selectedStudent} 
            onClose={() => setSelectedStudent(null)} 
            onUpdate={(updated) => {
                saveStudent(updated);
                refreshStudents();
                setSelectedStudent(updated);
            }}
        />
      )}

      {/* Bulk Import Modal */}
      {isImportModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
             <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in duration-200">
                <div className="bg-slate-900 text-white p-4 flex justify-between items-center">
                    <h3 className="text-lg font-bold flex items-center gap-2">
                        <FileSpreadsheet size={20} />
                        استيراد جماعي (CSV)
                    </h3>
                    <button onClick={() => setIsImportModalOpen(false)} className="text-slate-400 hover:text-white">
                        <X size={20} />
                    </button>
                </div>
                <div className="p-6 text-center space-y-6">
                    <div className="bg-blue-50 border border-blue-100 rounded-lg p-4 text-sm text-blue-800 text-right">
                        <p className="font-bold mb-2">تعليمات الملف:</p>
                        <ul className="list-disc list-inside space-y-1">
                            <li>يجب أن يكون الملف بصيغة <strong>CSV (UTF-8)</strong>.</li>
                            <li>الترتيب المطلوب للأعمدة: <br/><code className="bg-blue-100 px-1 rounded dir-ltr">Name, NationalID, Department, Program, Year</code></li>
                            <li>تأكد من عدم وجود أرقام وطنية مكررة.</li>
                        </ul>
                    </div>

                    <div className="border-2 border-dashed border-slate-300 rounded-xl p-8 hover:bg-slate-50 transition-colors cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                        <Upload size={48} className="mx-auto text-slate-400 mb-4" />
                        <p className="font-bold text-slate-700">اضغط لرفع ملف CSV</p>
                        <p className="text-sm text-slate-500">أو اسحب الملف هنا</p>
                        <input 
                            type="file" 
                            ref={fileInputRef} 
                            accept=".csv" 
                            className="hidden" 
                            onChange={handleBulkImport}
                        />
                    </div>
                </div>
             </div>
          </div>
      )}

      {/* Add/Edit Student Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
                <div className="bg-slate-900 text-white p-4 flex justify-between items-center">
                    <h3 className="text-lg font-bold flex items-center gap-2">
                        {isEditMode ? <Edit2 size={20}/> : <UserPlus size={20} />}
                        {isEditMode ? 'تعديل بيانات طالب' : 'تسجيل طالب جديد'}
                    </h3>
                    <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-white">
                        <X size={20} />
                    </button>
                </div>
                <form onSubmit={handleSaveStudent} className="p-6">
                    <div className="flex gap-6">
                        {/* Profile Pic Placeholder */}
                        <div className="w-1/3 flex flex-col items-center gap-2">
                            <div className="w-32 h-32 bg-slate-100 rounded-full border-2 border-slate-200 flex items-center justify-center relative overflow-hidden group">
                                <ImageIcon size={40} className="text-slate-300" />
                                <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer">
                                    <span className="text-white text-xs font-bold">تغيير الصورة</span>
                                </div>
                            </div>
                            <p className="text-xs text-slate-400 text-center">انقر لرفع صورة شخصية (اختياري)</p>
                        </div>

                        <div className="w-2/3 space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">الاسم الرباعي <span className="text-red-500">*</span></label>
                                <input 
                                    required
                                    type="text" 
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                                    value={currentStudent.name}
                                    onChange={(e) => setCurrentStudent({...currentStudent, name: e.target.value})}
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">الرقم الوطني <span className="text-red-500">*</span></label>
                                <input 
                                    required
                                    type="text" 
                                    pattern="\d{12}"
                                    title="يجب أن يتكون الرقم الوطني من 12 خانة"
                                    className={`w-full border rounded-lg px-3 py-2 focus:ring-2 focus:outline-none ${nationalIdError ? 'border-red-500 focus:ring-red-500' : 'border-slate-300 focus:ring-blue-500'}`}
                                    value={currentStudent.nationalId}
                                    onChange={(e) => {
                                        setNationalIdError('');
                                        setCurrentStudent({...currentStudent, nationalId: e.target.value});
                                    }}
                                />
                                {nationalIdError && <p className="text-xs text-red-500 mt-1">{nationalIdError}</p>}
                            </div>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4 mt-4 border-t pt-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">البرنامج الدراسي</label>
                            <select 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                                value={currentStudent.program}
                                onChange={(e) => setCurrentStudent({...currentStudent, program: e.target.value as ProgramType})}
                            >
                                <option value={ProgramType.UNDERGRADUATE}>{ProgramType.UNDERGRADUATE}</option>
                                <option value={ProgramType.POSTGRADUATE}>{ProgramType.POSTGRADUATE}</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">القسم العلمي</label>
                            <input 
                                required
                                type="text" 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                                value={currentStudent.department}
                                onChange={(e) => setCurrentStudent({...currentStudent, department: e.target.value})}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">سنة القيد</label>
                            <input 
                                required
                                type="number"
                                min="2000"
                                max={new Date().getFullYear()}
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                                value={currentStudent.enrollmentYear}
                                onChange={(e) => setCurrentStudent({...currentStudent, enrollmentYear: parseInt(e.target.value)})}
                            />
                        </div>
                        {currentStudent.program === ProgramType.POSTGRADUATE && (
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">المشرف الأكاديمي</label>
                                <input 
                                    type="text"
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                                    value={currentStudent.advisorName || ''}
                                    onChange={(e) => setCurrentStudent({...currentStudent, advisorName: e.target.value})}
                                    placeholder="اختياري"
                                />
                            </div>
                        )}
                    </div>

                    <div className="pt-6 flex justify-end gap-3 border-t mt-6">
                        <button 
                            type="button" 
                            onClick={() => setIsModalOpen(false)}
                            className="px-4 py-2 text-slate-600 hover:bg-slate-50 rounded-lg font-medium"
                        >
                            إلغاء
                        </button>
                        <button 
                            type="submit" 
                            className="px-6 py-2 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-700 flex items-center gap-2"
                        >
                            <Save size={18} />
                            {isEditMode ? 'حفظ التعديلات' : 'تسجيل الطالب'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </div>
  );
};

export default StudentsList;

import React, { useState, useEffect } from 'react';
import { BookOpen, Search, Info, Plus, Trash2, Save, X, Edit2, BarChart2, Users, FileSpreadsheet } from 'lucide-react';
