import { calculateWeightedGPA, evaluateAcademicStatus } from '../services/gradingService';
import { Course, Student, Permission } from '../types';
import { logAction } from '../services/auditService';
import { notifySuccess, notifyError, notifyInfo } from '../services/notificationService';
import { getCurrentUser, hasPermission } from '../services/authService';

const Academics: React.FC = () => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [students, setStudents] = useState<Student[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const currentUser = getCurrentUser();

  // Specific Permissions
  const canManageAcademics = hasPermission(currentUser, Permission.ACADEMICS_MANAGE);
  const canEditGrades = hasPermission(currentUser, Permission.GRADES_EDIT);

  // Modal State for Course Add/Edit
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);

  // Modal State for Batch Grading
  const [isBatchGradeOpen, setIsBatchGradeOpen] = useState(false);
  const [selectedCourseForGrading, setSelectedCourseForGrading] = useState<Course | null>(null);
  const [batchGrades, setBatchGrades] = useState<Record<string, number>>({});
  const [currentSemester, setCurrentSemester] = useState('');

  // Form State
  const [currentCourse, setCurrentCourse] = useState<Partial<Course>>({
    name: '',
    code: '',
    credits: 3,
    semester: 1
  });

  useEffect(() => {
    refreshData();
    const settings = getSystemSettings();
    setCurrentSemester(settings.currentSemester);
  }, []);

  const refreshData = () => {
    setCourses(getCourses());
    setStudents(getStudents());
  };

  const handleOpenAdd = () => {
      setIsEditMode(false);
      setCurrentCourse({ name: '', code: '', credits: 3, semester: 1 });
      setIsModalOpen(true);
  };

  const handleOpenEdit = (course: Course) => {
      setIsEditMode(true);
      setCurrentCourse({ ...course });
      setIsModalOpen(true);
  };

  const handleOpenBatchGrading = (course: Course) => {
      setSelectedCourseForGrading(course);

      // Initialize batch grades with existing grades if any
      const initialGrades: Record<string, number> = {};
      students.forEach(s => {
          const existingGrade = s.grades.find(g => g.courseId === course.id);
          if (existingGrade) {
              initialGrades[s.id] = existingGrade.score;
          }
      });
      setBatchGrades(initialGrades);
      setIsBatchGradeOpen(true);
  };

  const handleSaveBatchGrades = () => {
      if (!selectedCourseForGrading) return;

      let updatedCount = 0;

      students.forEach(student => {
          const newScore = batchGrades[student.id];

          // Only process if there is a valid score
          if (newScore !== undefined && newScore !== null && !isNaN(newScore)) {
              // Check if grade changed or is new
              const existingGradeIndex = student.grades.findIndex(g => g.courseId === selectedCourseForGrading.id);
              const existingGrade = student.grades[existingGradeIndex];

              if (existingGrade && existingGrade.score === newScore) return; // No change

              let updatedGrades = [...student.grades];

              if (existingGradeIndex >= 0) {
                  // Update existing
                  updatedGrades[existingGradeIndex] = {
                      ...existingGrade,
                      score: newScore,
                      semester: currentSemester
                  };
              } else {
                  // Add new
                  updatedGrades.push({
                      courseId: selectedCourseForGrading.id,
                      courseName: selectedCourseForGrading.name,
                      score: newScore,
                      semester: currentSemester
                  });
              }

              // Recalculate Logic using Service
              const newGpa = calculateWeightedGPA(updatedGrades, courses);
              const statusResult = evaluateAcademicStatus(newGpa, student.program, student.status, student.warningsCount);

              const updatedStudent = {
                  ...student,
                  grades: updatedGrades,
                  gpa: newGpa,
                  status: statusResult.status,
                  warningsCount: statusResult.warningsCount
              };

              saveStudent(updatedStudent);
              updatedCount++;
          }
      });

      if (updatedCount > 0) {
          logAction(
              'رصد درجات جماعي',
              `تم تحديث درجات ${updatedCount} طالب في المقرر ${selectedCourseForGrading.name}`,
              'info'
          );
          notifySuccess(`تم تحديث سجلات ${updatedCount} طالب بنجاح.`);
          refreshData();
      } else {
          notifyInfo("لم يتم إجراء أي تغييرات.");
      }
      setIsBatchGradeOpen(false);
  };

  const handleSaveCourse = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentCourse.name || !currentCourse.code) return;

    const course: Course = {
        id: currentCourse.id || currentCourse.code!, // Use existing ID or code as ID
        code: currentCourse.code!,
        name: currentCourse.name!,
        credits: Number(currentCourse.credits),
        semester: Number(currentCourse.semester)
    };

    saveCourse(course);
    logAction(
        isEditMode ? 'تعديل مقرر' : 'إضافة مقرر',
        `تم ${isEditMode ? 'تعديل' : 'إضافة'} المقرر ${course.name} (${course.code})`,
        'info'
    );
    notifySuccess(isEditMode ? 'تم تعديل المقرر بنجاح' : 'تم إضافة المقرر بنجاح');
    refreshData();
    setIsModalOpen(false);
  };

  const handleDeleteCourse = (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذا المقرر؟ سيؤثر هذا على السجلات التاريخية.')) {
        const course = courses.find(c => c.id === id);
        deleteCourse(id);
        logAction('حذف مقرر', `تم حذف المقرر ${course?.name} (${course?.code})`, 'danger');
        notifyInfo('تم حذف المقرر');
        refreshData();
    }
  };

  const filteredCourses = courses.filter(c => 
    c.name.includes(searchTerm) || c.code.includes(searchTerm)
  );

  // Calculate Course Stats
  const getCourseStats = (courseId: string) => {
      let count = 0;
      let totalScore = 0;
      let passCount = 0;

      students.forEach(student => {
          const grade = student.grades.find(g => g.courseId === courseId);
          if (grade) {
              count++;
              totalScore += grade.score;
              // Check passing grade based on student program logic roughly
              const passingScore = student.program === 'جامعي' ? 50 : 65; 
              if (grade.score >= passingScore) passCount++;
          }
      });

      return {
          count,
          avg: count > 0 ? (totalScore / count).toFixed(1) : '-',
          passRate: count > 0 ? Math.round((passCount / count) * 100) : 0
      };
  };

  return (
    <div className="p-8">
      <div className="mb-8 flex justify-between items-end">
        <div>
            <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <BookOpen className="text-blue-600" />
            الدليل الأكاديمي للمقررات
            </h2>
            <p className="text-slate-500 mt-2">إدارة المواد الدراسية وشروط النجاح حسب اللائحة 501</p>
        </div>
        {canManageAcademics && (
            <button 
                onClick={handleOpenAdd}
                className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700 transition-colors shadow-sm"
            >
                <Plus size={20} />
                <span>إضافة مقرر جديد</span>
            </button>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
        <div className="bg-blue-50 border border-blue-200 p-6 rounded-xl">
          <h3 className="font-bold text-blue-900 mb-2">الدراسات الجامعية</h3>
          <p className="text-sm text-blue-800 leading-relaxed">
            درجة النجاح المعتمدة للمقررات الدراسية هي <strong>50%</strong>.
            يتم احتساب المعدل الفصلي والتراكمي بناءً على الوحدات المنجزة.
          </p>
        </div>
        <div className="bg-purple-50 border border-purple-200 p-6 rounded-xl">
          <h3 className="font-bold text-purple-900 mb-2">الدراسات العليا</h3>
          <p className="text-sm text-purple-800 leading-relaxed">
            درجة النجاح المعتمدة للمقررات هي <strong>65%</strong>.
            أي درجة أقل من ذلك تعتبر رسوباً وتستوجب إعادة المقرر.
          </p>
        </div>
        <div className="bg-white border border-slate-200 p-6 rounded-xl shadow-sm flex flex-col justify-center items-center text-center">
            <span className="text-4xl font-bold text-slate-800 mb-1">{courses.length}</span>
            <span className="text-slate-500 text-sm">مقرر دراسي مسجل</span>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200">
        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <h3 className="font-bold text-slate-700">دليل المقررات وتحليل الأداء</h3>
          <div className="relative w-64">
            <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input 
              type="text" 
              placeholder="بحث عن مقرر..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pr-9 pl-4 py-2 text-sm rounded-lg border border-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
        </div>

        <table className="w-full text-right">
          <thead className="bg-slate-50 text-slate-500 text-sm border-b border-slate-200">
            <tr>
              <th className="px-6 py-3 font-medium">المقرر</th>
              <th className="px-6 py-3 font-medium">الوحدات</th>
              <th className="px-6 py-3 font-medium">الفصل</th>
              <th className="px-6 py-3 font-medium">النجاح</th>
              <th className="px-6 py-3 font-medium">إحصائيات</th>
              <th className="px-6 py-3 font-medium">إجراءات</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredCourses.map((course) => {
              const isPostgrad = course.code.toUpperCase().includes('5') || course.code.toUpperCase().includes('6') || course.code.length > 5; 
              const stats = getCourseStats(course.id);

              return (
                <tr key={course.id} className="hover:bg-slate-50 group">
                  <td className="px-6 py-4">
                      <div className="font-medium text-slate-800">{course.name}</div>
                      <div className="text-xs text-slate-500 font-mono">{course.code}</div>
                  </td>
                  <td className="px-6 py-4 text-slate-600">{course.credits}</td>
                  <td className="px-6 py-4 text-slate-600">{course.semester}</td>
                  <td className="px-6 py-4">
                    <span className={`inline-flex items-center gap-1 px-2 py-1 rounded text-xs font-bold ${isPostgrad ? 'bg-purple-100 text-purple-700' : 'bg-blue-100 text-blue-700'}`}>
                        {isPostgrad ? '65%' : '50%'}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                      <div className="flex items-center gap-4 text-xs">
                          <div className="flex items-center gap-1 text-slate-600" title="عدد الطلاب المسجلين">
                              <Users size={14} />
                              {stats.count}
                          </div>
                          {stats.count > 0 && (
                            <div className="flex items-center gap-1 text-slate-600" title="متوسط الدرجات">
                                <BarChart2 size={14} />
                                %{stats.avg}
                            </div>
                          )}
                      </div>
                      {stats.count > 0 && (
                          <div className="w-full bg-gray-100 h-1.5 rounded-full mt-2 overflow-hidden" title={`نسبة النجاح: ${stats.passRate}%`}>
                              <div 
                                className={`h-full ${stats.passRate >= 75 ? 'bg-green-500' : stats.passRate >= 50 ? 'bg-yellow-500' : 'bg-red-500'}`} 
                                style={{width: `${stats.passRate}%`}}
                              ></div>
                          </div>
                      )}
                  </td>
                  <td className="px-6 py-4">
                      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        {canEditGrades && (
                            <button 
                                onClick={() => handleOpenBatchGrading(course)}
                                className="p-2 text-green-600 hover:bg-green-50 rounded-lg tooltip"
                                title="رصد درجات جماعي"
                            >
                                <FileSpreadsheet size={16} />
                            </button>
                        )}
                        {canManageAcademics && (
                            <>
                                <button 
                                    onClick={() => handleOpenEdit(course)}
                                    className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg tooltip"
                                    title="تعديل"
                                >
                                    <Edit2 size={16} />
                                </button>
                                <button 
                                    onClick={() => handleDeleteCourse(course.id)}
                                    className="p-2 text-red-400 hover:bg-red-50 hover:text-red-600 rounded-lg tooltip"
                                    title="حذف المقرر"
                                >
                                    <Trash2 size={16} />
                                </button>
                            </>
                        )}
                      </div>
                  </td>
                </tr>
              )
            })}
             {filteredCourses.length === 0 && (
                <tr>
                    <td colSpan={6} className="text-center py-8 text-slate-400">لا توجد مقررات مطابقة</td>
                </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Add/Edit Course Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden animate-in fade-in zoom-in duration-200">
                <div className="bg-slate-900 text-white p-4 flex justify-between items-center">
                    <h3 className="text-lg font-bold flex items-center gap-2">
                        <BookOpen size={20} />
                        {isEditMode ? 'تعديل بيانات مقرر' : 'إضافة مقرر دراسي'}
                    </h3>
                    <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-white">
                        <X size={20} />
                    </button>
                </div>
                <form onSubmit={handleSaveCourse} className="p-6 space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">رمز المقرر (Code)</label>
                        <input 
                            required
                            type="text" 
                            disabled={isEditMode} // Disable editing ID/Code in edit mode to prevent breaking links
                            className={`w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none dir-ltr font-mono ${isEditMode ? 'bg-gray-100 text-gray-500 cursor-not-allowed' : ''}`}
                            value={currentCourse.code}
                            onChange={(e) => setCurrentCourse({...currentCourse, code: e.target.value.toUpperCase()})}
                            placeholder="e.g., CS101"
                        />
                        {isEditMode && <p className="text-xs text-slate-400 mt-1">لا يمكن تعديل الرمز لارتباطه بسجلات الدرجات.</p>}
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">اسم المقرر</label>
                        <input 
                            required
                            type="text" 
                            className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                            value={currentCourse.name}
                            onChange={(e) => setCurrentCourse({...currentCourse, name: e.target.value})}
                        />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">عدد الوحدات</label>
                            <input 
                                required
                                type="number" 
                                min="1"
                                max="10"
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                                value={currentCourse.credits}
                                onChange={(e) => setCurrentCourse({...currentCourse, credits: parseInt(e.target.value)})}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">الفصل الدراسي</label>
                            <input 
                                required
                                type="number" 
                                min="1"
                                max="12"
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                                value={currentCourse.semester}
                                onChange={(e) => setCurrentCourse({...currentCourse, semester: parseInt(e.target.value)})}
                            />
                        </div>
                    </div>
                    <div className="pt-4 flex justify-end gap-3">
                        <button 
                            type="button" 
                            onClick={() => setIsModalOpen(false)}
                            className="px-4 py-2 text-slate-600 hover:bg-slate-50 rounded-lg font-medium"
                        >
                            إلغاء
                        </button>
                        <button 
                            type="submit" 
                            className="px-6 py-2 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-700 flex items-center gap-2"
                        >
                            <Save size={18} />
                            حفظ
                        </button>
                    </div>
                </form>
            </div>
        </div>
      )}

      {/* Batch Grade Entry Modal */}
      {isBatchGradeOpen && selectedCourseForGrading && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in duration-200">
                  <div className="bg-slate-900 text-white p-4 flex justify-between items-center">
                      <div>
                          <h3 className="text-lg font-bold flex items-center gap-2">
                              <FileSpreadsheet size={20} />
                              رصد درجات جماعي
                          </h3>
                          <p className="text-xs text-slate-400 mt-1">
                              {selectedCourseForGrading.name} ({selectedCourseForGrading.code}) - الفصل الحالي: {currentSemester}
                          </p>
                      </div>
                      <div className="flex gap-2">
                        <button 
                            onClick={handleSaveBatchGrades}
                            className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2"
                        >
                            <Save size={16} /> حفظ ورصد
                        </button>
                        <button onClick={() => setIsBatchGradeOpen(false)} className="text-slate-400 hover:text-white p-2">
                            <X size={20} />
                        </button>
                      </div>
                  </div>

                  <div className="flex-1 overflow-auto bg-slate-50 p-6">
                      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                          <table className="w-full text-right">
                              <thead className="bg-slate-100 text-slate-600 text-sm font-medium border-b border-slate-200">
                                  <tr>
                                      <th className="px-6 py-4">اسم الطالب</th>
                                      <th className="px-6 py-4">الرقم الدراسي</th>
                                      <th className="px-6 py-4">التخصص</th>
                                      <th className="px-6 py-4">الدرجة الحالية</th>
                                      <th className="px-6 py-4 w-32">الدرجة الجديدة</th>
                                  </tr>
                              </thead>
                              <tbody className="divide-y divide-slate-100">
                                  {students.map(student => {
                                      const currentGrade = student.grades.find(g => g.courseId === selectedCourseForGrading.id);
                                      return (
                                          <tr key={student.id} className="hover:bg-blue-50">
                                              <td className="px-6 py-3 font-medium text-slate-800">{student.name}</td>
                                              <td className="px-6 py-3 font-mono text-xs text-slate-500">{student.id}</td>
                                              <td className="px-6 py-3 text-sm text-slate-600">{student.department}</td>
                                              <td className="px-6 py-3">
                                                  {currentGrade ? (
                                                      <span className={`font-bold ${currentGrade.score >= 50 ? 'text-green-600' : 'text-red-600'}`}>
                                                          {currentGrade.score}%
                                                      </span>
                                                  ) : (
                                                      <span className="text-slate-400 text-sm">-</span>
                                                  )}
                                              </td>
                                              <td className="px-6 py-3">
                                                  <input 
                                                      type="number" 
                                                      min="0"
                                                      max="100"
                                                      className="w-full border border-slate-300 rounded px-2 py-1 focus:ring-2 focus:ring-blue-500 focus:outline-none text-center font-bold text-slate-800"
                                                      placeholder="-"
                                                      value={batchGrades[student.id] || ''}
                                                      onChange={(e) => {
                                                          const val = parseFloat(e.target.value);
                                                          setBatchGrades(prev => ({
                                                              ...prev,
                                                              [student.id]: isNaN(val) ? undefined : val
                                                          } as any));
                                                      }}
                                                  />
                                              </td>
                                          </tr>
                                      );
                                  })}
                              </tbody>
                          </table>
                      </div>
                  </div>
                  <div className="bg-slate-50 p-4 border-t border-slate-200 text-xs text-slate-500 flex items-center gap-2">
                      <Info size={14} />
                      سيتم إعادة حساب المعدل التراكمي (GPA) وحالة الطالب تلقائياً عند الحفظ.
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Academics;

import React, { useState, useEffect } from 'react';
import { getCourses } from '../services/storageService';
import { getInstructors } from '../services/facultyService';
import { getSchedule, saveClassSession, deleteClassSession, checkScheduleConflict, getDayLabel } from '../services/scheduleService';
import { ClassSession, Course, Instructor, DayOfWeek, Permission } from '../types';
import { Calendar, Plus, Trash2, Clock, MapPin, AlertCircle, Save, X, User } from 'lucide-react';
import { notifySuccess, notifyError } from '../services/notificationService';
import { logAction } from '../services/auditService';
import { getCurrentUser, hasPermission } from '../services/authService';

const Schedule: React.FC = () => {
    const [schedule, setSchedule] = useState<ClassSession[]>([]);
    const [courses, setCourses] = useState<Course[]>([]);
    const [instructors, setInstructors] = useState<Instructor[]>([]);
    const currentUser = getCurrentUser();
    const canManageAcademics = hasPermission(currentUser, Permission.ACADEMICS_MANAGE);

    const [showModal, setShowModal] = useState(false);
    const [currentSession, setCurrentSession] = useState<Partial<ClassSession>>({
        day: 'SUNDAY',
        startTime: '08:00',
        endTime: '10:00',
        room: ''
    });

    useEffect(() => {
        refreshData();
    }, []);

    const refreshData = () => {
        setSchedule(getSchedule());
        setCourses(getCourses());
        setInstructors(getInstructors());
    };

    const handleSave = (e: React.FormEvent) => {
        e.preventDefault();

        if (!currentSession.courseId || !currentSession.instructorId || !currentSession.room) {
            notifyError('الرجاء تعبئة كافة الحقول المطلوبة');
            return;
        }

        const course = courses.find(c => c.id === currentSession.courseId);
        const instructor = instructors.find(i => i.id === currentSession.instructorId);

        const newSession: ClassSession = {
            id: currentSession.id || `SES-${Date.now()}`,
            courseId: currentSession.courseId,
            courseName: course?.name || '',
            instructorId: currentSession.instructorId,
            instructorName: instructor?.name || '',
            day: currentSession.day as DayOfWeek,
            startTime: currentSession.startTime!,
            endTime: currentSession.endTime!,
            room: currentSession.room
        };

        // Conflict Check
        const conflict = checkScheduleConflict(newSession, currentSession.id);
        if (conflict.hasConflict) {
            notifyError(conflict.message || 'يوجد تعارض في الجدول');
            return;
        }

        saveClassSession(newSession);
        logAction('تحديث الجدول', `تم إضافة/تعديل موعد للمقرر ${newSession.courseName}`, 'info');
        notifySuccess('تم حفظ الموعد بنجاح');
        setShowModal(false);
        refreshData();
