import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';
import { logAction } from '../services/auditService';
import { notifySuccess, notifyError, notifyInfo } from '../services/notificationService';
import { getCurrentUser, hasPermission } from '../services/authService';

interface StudentDetailsProps {
  student: Student;
  onClose: () => void;
  onUpdate?: (student: Student) => void;
}

const StudentDetails: React.FC<StudentDetailsProps> = ({ student, onClose, onUpdate }) => {
  const [activeTab, setActiveTab] = useState<'info' | 'grades' | 'advisor'>('info');
  const [chatQuery, setChatQuery] = useState('');
  const [chatHistory, setChatHistory] = useState<{role: 'user' | 'model', text: string}[]>([]);
  const [loading, setLoading] = useState(false);
  const currentUser = getCurrentUser();

  // Dynamic Data State
  const [availableCourses, setAvailableCourses] = useState<Course[]>([]);
  const [defaultSemester, setDefaultSemester] = useState('خريف 2024');
  const [financialBalance, setFinancialBalance] = useState(0); 
  const [attendanceStats, setAttendanceStats] = useState({ total: 0, absenceRate: 0 });

  // Add Grade State
  const [showGradeModal, setShowGradeModal] = useState(false);
  const [newGrade, setNewGrade] = useState({ courseId: '', score: '', semester: '' });

  // Edit Status State
  const [isEditingStatus, setIsEditingStatus] = useState(false);

  // Transcript Modal State
  const [showTranscript, setShowTranscript] = useState(false);

  // Permissions
  const canEditGrades = hasPermission(currentUser, Permission.GRADES_EDIT);
  const canEditStatus = hasPermission(currentUser, Permission.STUDENTS_EDIT);
  const canUseAdvisor = hasPermission(currentUser, Permission.ACADEMICS_MANAGE);

  useEffect(() => {
      setAvailableCourses(getCourses());
      const settings = getSystemSettings();
      setDefaultSemester(settings.currentSemester);
      setNewGrade(prev => ({ ...prev, semester: settings.currentSemester }));

      // Calculate Financial Balance & Attendance
      setFinancialBalance(calculateBalance(student.id));
      setAttendanceStats(getStudentAttendanceStats(student.id));
  }, []);

  const handleAdvisorSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatQuery.trim()) return;

    const userMsg = chatQuery;
    setChatQuery('');
    setChatHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setLoading(true);

    try {
      const response = await analyzeStudentStatus(student, userMsg);
      setChatHistory(prev => [...prev, { role: 'model', text: response }]);
    } catch (err) {
      setChatHistory(prev => [...prev, { role: 'model', text: "حدث خطأ غير متوقع." }]);
    } finally {
      setLoading(false);
    }
  };

  const handleGeneratePlan = async () => {
      setLoading(true);
      setChatHistory(prev => [...prev, {role: 'user', text: 'أريد خطة دراسية لتحسين المعدل.'}]);
      setActiveTab('advisor');
      const plan = await generateStudyPlan(student);
      setChatHistory(prev => [...prev, {role: 'model', text: plan}]);
      setLoading(false);
  };

  const handleAddGrade = (e: React.FormEvent) => {
    e.preventDefault();
    if (!onUpdate || !newGrade.courseId || !newGrade.score) return;

    const course = availableCourses.find(c => c.id === newGrade.courseId);
    if (!course) return;

    const scoreNum = parseFloat(newGrade.score);
    if (isNaN(scoreNum) || scoreNum < 0 || scoreNum > 100) {
        notifyError("الرجاء إدخال درجة صحيحة بين 0 و 100");
        return;
    }

    // Determine if we are adding a new grade or modifying an existing one
    const existingGradeIndex = student.grades.findIndex(g => g.courseId === newGrade.courseId);
    const existingGrade = existingGradeIndex >= 0 ? student.grades[existingGradeIndex] : null;
    const oldScore = existingGrade ? existingGrade.score : null;

    let updatedGrades = [...student.grades];
    if (existingGradeIndex >= 0) {
        // Modify existing grade
        updatedGrades[existingGradeIndex] = {
            ...existingGrade,
            score: scoreNum,
            semester: newGrade.semester
        };
    } else {
        // Add new grade entry
        updatedGrades.push({
            courseId: course.id,
            courseName: course.name,
            score: scoreNum,
            semester: newGrade.semester
        });
    }

    // Recalculate GPA using Service
    const newGpa = calculateWeightedGPA(updatedGrades, availableCourses);

    // Update Status using Service
    const statusResult = evaluateAcademicStatus(newGpa, student.program, student.status, student.warningsCount);

    const updatedStudent = {
        ...student,
        grades: updatedGrades,
        gpa: newGpa,
        status: statusResult.status,
        warningsCount: statusResult.warningsCount
    };

    onUpdate(updatedStudent);

    // Log Audit with detailed change information
    const isNew = oldScore === null;
    logAction(
        isNew ? 'إضافة درجة' : 'تعديل درجة',
        `الطالب: ${student.name} | المقرر: ${course.name} | الدرجة: ${isNew ? 'جديد' : oldScore} -> ${scoreNum}`,
        isNew ? 'info' : 'warning',
        currentUser?.name
    );

    notifySuccess(isNew ? 'تم رصد الدرجة بنجاح' : 'تم تعديل الدرجة بنجاح');

    setShowGradeModal(false);
    setNewGrade({ courseId: '', score: '', semester: defaultSemester });
  };

  const handleStatusChange = (newStatus: StudentStatus) => {
      if (!onUpdate) return;

      const oldStatus = student.status;
      onUpdate({ ...student, status: newStatus });

      logAction(
          'تغيير حالة طالب',
          `تم تغيير حالة الطالب ${student.name} من ${oldStatus} إلى ${newStatus}`,
          'warning',
          currentUser?.name
      );
      notifyInfo(`تم تحديث حالة الطالب إلى ${newStatus}`);

      setIsEditingStatus(false);
  };

  const statusColor = {
    [StudentStatus.ACTIVE]: 'bg-green-100 text-green-700',
    [StudentStatus.WARNING]: 'bg-red-100 text-red-700',
    [StudentStatus.SUSPENDED]: 'bg-gray-100 text-gray-700',
    [StudentStatus.GRADUATED]: 'bg-blue-100 text-blue-700',
    [StudentStatus.WITHDRAWN]: 'bg-yellow-100 text-yellow-700',
  };

  const passingScore = student.program === ProgramType.POSTGRADUATE ? 65 : 50;

  const getGradeLabel = (gpa: number, program: ProgramType) => {
    if (program === ProgramType.POSTGRADUATE) {
      if (gpa >= 85) return { label: 'ممتاز', color: 'text-green-600' };
      if (gpa >= 75) return { label: 'جيد جداً', color: 'text-blue-600' };
      if (gpa >= 65) return { label: 'جيد', color: 'text-yellow-600' };
      return { label: 'راسب', color: 'text-red-600' };
    } else {
      if (gpa >= 85) return { label: 'ممتاز', color: 'text-green-600' };
      if (gpa >= 75) return { label: 'جيد جداً', color: 'text-blue-600' };
      if (gpa >= 65) return { label: 'جيد', color: 'text-blue-500' };
      if (gpa >= 50) return { label: 'مقبول', color: 'text-yellow-600' };
      return { label: 'ضعيف', color: 'text-red-600' };
    }
  };

  const gradeInfo = getGradeLabel(student.gpa, student.program);
  const isHonorStudent = student.gpa >= 85;

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
      <div className="bg-white w-full max-w-5xl rounded-2xl shadow-2xl h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in duration-200">

        {/* Header */}
        <div className="bg-slate-900 text-white p-6 flex justify-between items-start">
          <div className="flex gap-4">
            <div className="w-16 h-16 bg-slate-700 rounded-full flex items-center justify-center border-2 border-blue-500 shadow-lg relative">
              <span className="text-2xl font-bold">{student.name.charAt(0)}</span>
              {student.warningsCount >= 3 && (
                  <div className="absolute -top-1 -right-1 bg-red-500 rounded-full p-1 border border-white animate-pulse" title="مهدد بالفصل">
                      <AlertTriangle size={12} className="text-white"/>
                  </div>
              )}
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-2xl font-bold">{student.name}</h2>
                {isHonorStudent && (
                    <span className="bg-yellow-400 text-yellow-900 text-[10px] font-bold px-2 py-0.5 rounded-full flex items-center gap-1 shadow-sm">
                        <Medal size={12} />
                        طالب متميز
                    </span>
                )}
              </div>
              <div className="flex items-center gap-3 mt-1 text-slate-300">
                <span className="flex items-center gap-1 bg-slate-800 px-2 py-0.5 rounded-md text-xs"><User size={12}/> {student.id}</span>
                <span className="text-slate-600">|</span>
                <span>{student.department}</span>
                <span className="text-slate-600">|</span>

                {canEditStatus ? (
                    isEditingStatus ? (
                        <select 
                            className="text-slate-900 text-xs rounded px-1 py-0.5"
                            value={student.status}
                            onChange={(e) => handleStatusChange(e.target.value as StudentStatus)}
                            onBlur={() => setIsEditingStatus(false)}
                            autoFocus
                        >
                            {Object.values(StudentStatus).map(s => (
                                <option key={s} value={s}>{s}</option>
                            ))}
                        </select>
                    ) : (
                        <button 
                            onClick={() => setIsEditingStatus(true)}
                            className={`flex items-center gap-1 px-2 py-0.5 rounded text-xs font-bold ${statusColor[student.status]} bg-opacity-20 hover:bg-opacity-30 transition-all`}
                            title="انقر لتعديل الحالة"
                        >
                            {student.status}
                            <Edit2 size={10} className="opacity-50"/>
                        </button>
                    )
                ) : (
                    <span className={`flex items-center gap-1 px-2 py-0.5 rounded text-xs font-bold ${statusColor[student.status]} bg-opacity-20`}>
                        {student.status}
                    </span>
                )}
              </div>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-slate-800 rounded-full transition-colors">
            <X size={24} />
          </button>
        </div>

        {/* Tabs */}
        <div className="border-b border-gray-200 px-6 pt-4 flex gap-6 bg-slate-50">
          <button 
            onClick={() => setActiveTab('info')}
            className={`pb-4 px-2 text-sm font-medium border-b-2 transition-colors ${activeTab === 'info' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
          >
            البيانات الأساسية
          </button>
          <button 
            onClick={() => setActiveTab('grades')}
            className={`pb-4 px-2 text-sm font-medium border-b-2 transition-colors ${activeTab === 'grades' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
          >
            كشف الدرجات
          </button>
          <button 
            onClick={() => setActiveTab('advisor')}
            className={`pb-4 px-2 text-sm font-medium border-b-2 transition-colors ${activeTab === 'advisor' ? 'border-purple-600 text-purple-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
          >
            <span className="flex items-center gap-2">
                <MessageSquare size={16} />
                المرشد الذكي
            </span>
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 bg-gray-50 relative">

          {activeTab === 'info' && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-6">
                 {/* Alert Card for Regulation 501 violations */}
                 {student.warningsCount >= 3 && (
                     <div className="bg-red-50 border border-red-200 rounded-xl p-4 flex items-start gap-3">
                         <AlertTriangle className="text-red-600 shrink-0" />
                         <div>
                             <h4 className="font-bold text-red-800">تنبيه هام حسب اللائحة 501</h4>
                             <p className="text-sm text-red-700 mt-1">تجاوز الطالب الحد الأقصى من الإنذارات (3 إنذارات). يجب مراجعة وضعه القانوني للفصل من الدراسة.</p>
                         </div>
                     </div>
                 )}

                 {/* Financial Hold Alert */}
                 {financialBalance > 0 && (
                     <div className="bg-orange-50 border border-orange-200 rounded-xl p-4 flex items-start gap-3">
                         <Wallet className="text-orange-600 shrink-0" />
                         <div>
                             <h4 className="font-bold text-orange-800">تنبيه مالي (إيقاف تسجيل)</h4>
                             <p className="text-sm text-orange-700 mt-1">
                                 يوجد على الطالب مستحقات مالية بقيمة <strong>{financialBalance} د.ل</strong>. 
                                 لا يمكن إصدار الشهادات أو تسجيل مواد جديدة حتى التسوية.
                             </p>
                         </div>
                     </div>
                 )}

                 {/* Attendance Alert */}
                 {attendanceStats.absenceRate >= 25 && (
                     <div className="bg-red-50 border border-red-200 rounded-xl p-4 flex items-start gap-3">
                         <UserCheck className="text-red-600 shrink-0" />
                         <div>
                             <h4 className="font-bold text-red-800">حرمان من الامتحانات (غياب)</h4>
                             <p className="text-sm text-red-700 mt-1">
                                 تجاوزت نسبة غياب الطالب <strong>{attendanceStats.absenceRate}%</strong>. 
                                 وفقاً للوائح، يحرم الطالب من دخول الامتحانات النهائية.
                             </p>
                         </div>
                     </div>
                 )}

                 <div className="bg-white p-6 rounded-xl shadow-sm border">
                    <h3 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
                        <Book size={20} className="text-blue-500"/>
                        معلومات أكاديمية
                    </h3>
                    <div className="space-y-4">
                    <div className="flex justify-between border-b border-gray-100 pb-2">
                        <span className="text-gray-500">الرقم الوطني</span>
                        <span className="font-medium font-mono text-gray-800">{student.nationalId}</span>
                    </div>
                    <div className="flex justify-between border-b border-gray-100 pb-2">
                        <span className="text-gray-500">سنة القيد</span>
                        <span className="font-medium text-gray-800">{student.enrollmentYear}</span>
                    </div>
                    <div className="flex justify-between border-b border-gray-100 pb-2">
                        <span className="text-gray-500">المرحلة الدراسية</span>
                        <span className="font-medium text-gray-800">{student.program}</span>
                    </div>
                    <div className="flex justify-between border-b border-gray-100 pb-2">
                        <span className="text-gray-500">عدد الإنذارات</span>
                        <div className="flex items-center gap-2">
                            {Array.from({length: 3}).map((_, i) => (
                                <div key={i} className={`w-2 h-2 rounded-full ${i < student.warningsCount ? 'bg-red-500' : 'bg-gray-200'}`}></div>
                            ))}
                            <span className={`font-bold text-sm ${student.warningsCount > 0 ? 'text-red-600' : 'text-green-600'}`}>
                                {student.warningsCount}
                            </span>
                        </div>
                    </div>
                    <div className="flex justify-between border-b border-gray-100 pb-2">
                        <span className="text-gray-500">نسبة الغياب العامة</span>
                        <span className={`font-bold ${attendanceStats.absenceRate > 20 ? 'text-red-600' : 'text-green-600'}`}>
                            {attendanceStats.absenceRate}%
                        </span>
                    </div>
                    {student.program === ProgramType.POSTGRADUATE && (
                        <>
                            <div className="flex justify-between border-b border-gray-100 pb-2">
                                <span className="text-gray-500">المشرف الأكاديمي</span>
                                <span className="font-medium text-gray-800">{student.advisorName || 'لم يعين'}</span>
                            </div>
                            <div className="flex flex-col gap-1 border-b border-gray-100 pb-2">
                                <span className="text-gray-500">عنوان الرسالة</span>
                                <span className="font-medium text-sm leading-relaxed text-gray-800">{student.thesisTitle || 'قيد الإعداد'}</span>
                            </div>
                        </>
                    )}
                    </div>
                 </div>
              </div>

              <div className="bg-white p-6 rounded-xl shadow-sm border flex flex-col justify-center items-center text-center">
                 <div className="w-48 h-48 rounded-full border-8 border-gray-50 flex items-center justify-center relative mb-4">
                    <svg className="w-full h-full transform -rotate-90 absolute top-0 left-0">
                        <circle cx="96" cy="96" r="80" stroke="currentColor" strokeWidth="12" fill="transparent" className="text-gray-100" />
                        <circle 
                            cx="96" 
                            cy="96" 
                            r="80" 
                            stroke="currentColor" 
                            strokeWidth="12" 
                            fill="transparent" 
                            className={student.gpa >= passingScore ? "text-blue-500" : "text-red-500"} 
                            strokeDasharray={502} 
                            strokeDashoffset={502 - (502 * student.gpa) / 100} 
                            strokeLinecap="round"
                        />
                    </svg>
                    <div className="flex flex-col items-center">
                        <span className="text-4xl font-bold text-gray-800 font-mono tracking-tighter">{student.gpa}%</span>
                        <span className={`text-lg font-bold mt-1 ${gradeInfo.color}`}>{gradeInfo.label}</span>
                    </div>
                 </div>

                 <div className="bg-blue-50 text-blue-800 px-4 py-2 rounded-lg text-sm mb-6 max-w-xs">
                     {student.program === ProgramType.UNDERGRADUATE 
                        ? 'نظام النجاح: 50% للمقرر' 
                        : 'نظام النجاح: 65% للمقرر (دراسات عليا)'}
                 </div>

                 <div className="flex gap-3 w-full px-8">
                     {canUseAdvisor && (
                        <button onClick={handleGeneratePlan} className="flex-1 bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors shadow-sm shadow-blue-200">
                            طلب خطة تحسين
                        </button>
                     )}
                     <button 
                        onClick={() => setShowTranscript(true)}
                        className="flex-1 bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-lg text-sm font-medium hover:bg-slate-50 transition-colors"
                     >
                        كشف الدرجات
                     </button>
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'grades' && (
            <div className="space-y-6">
                <div className="flex justify-between items-center">
                    <h3 className="text-lg font-bold text-gray-800">الأداء الأكاديمي</h3>
                    {canEditGrades && (
                        <button 
                            onClick={() => setShowGradeModal(true)}
                            className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-blue-700 flex items-center gap-2"
                        >
                            <Plus size={16} />
                            رصد درجة
                        </button>
                    )}
                </div>

                <div className="bg-white p-6 rounded-xl shadow-sm border h-80">
                    <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
                        <Info size={18} className="text-slate-400"/>
                        تحليل الأداء الفصلي
                    </h3>
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={student.grades}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                            <XAxis dataKey="courseName" tick={{fontFamily: 'Cairo', fontSize: 12}} />
                            <YAxis domain={[0, 100]} />
                            <Tooltip 
                                cursor={{fill: '#f1f5f9'}} 
                                contentStyle={{fontFamily: 'Cairo', textAlign: 'right', borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} 
                            />
                            <ReferenceLine y={passingScore} stroke="#ef4444" strokeDasharray="3 3" label={{ position: 'top', value: 'حد النجاح', fill: '#ef4444', fontSize: 12 }} />
                            <Bar dataKey="score" fill="#3b82f6" radius={[4, 4, 0, 0]} name="الدرجة" barSize={40} />
                        </BarChart>
                    </ResponsiveContainer>
                </div>

                <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
                    <div className="p-4 border-b bg-gray-50 flex justify-between items-center">
                        <h3 className="font-bold text-gray-800">سجل الدرجات</h3>
                        <span className="text-xs text-gray-500 bg-white px-2 py-1 rounded border">إجمالي المواد: {student.grades.length}</span>
                    </div>
                    <table className="w-full text-right">
                        <thead className="bg-gray-50 text-gray-500 text-sm">
                            <tr>
                                <th className="px-6 py-3 font-medium">المادة</th>
                                <th className="px-6 py-3 font-medium">رمز المقرر</th>
                                <th className="px-6 py-3 font-medium">الوحدات</th>
                                <th className="px-6 py-3 font-medium">الفصل الدراسي</th>
                                <th className="px-6 py-3 font-medium">الدرجة</th>
                                <th className="px-6 py-3 font-medium">الحالة</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {student.grades.map((g, i) => {
                                const course = availableCourses.find(c => c.id === g.courseId);
                                const credits = course ? course.credits : '-';
                                return (
                                <tr key={i} className="hover:bg-gray-50">
                                    <td className="px-6 py-4 font-medium text-gray-800">{g.courseName}</td>
                                    <td className="px-6 py-4 text-gray-500 text-sm font-mono">{g.courseId}</td>
                                    <td className="px-6 py-4 text-gray-500 text-sm">{credits}</td>
                                    <td className="px-6 py-4 text-gray-600 text-sm">{g.semester}</td>
                                    <td className="px-6 py-4">
                                        <span className={`font-bold ${g.score >= 85 ? 'text-green-600' : 'text-gray-800'}`}>
                                            {g.score}%
                                        </span>
                                    </td>
                                    <td className="px-6 py-4">
                                        {g.score >= passingScore ? (
                                            <span className="inline-flex items-center gap-1 bg-green-50 text-green-700 px-2 py-1 rounded-md text-xs font-medium border border-green-100">
                                                <CheckCircle size={12} /> ناجح
                                            </span>
                                        ) : (
                                            <span className="inline-flex items-center gap-1 bg-red-50 text-red-700 px-2 py-1 rounded-md text-xs font-medium border border-red-100">
                                                <AlertTriangle size={12} /> راسب
                                            </span>
                                        )}
                                    </td>
                                </tr>
                            )})}
                        </tbody>
                    </table>
                </div>
            </div>
          )}

          {activeTab === 'advisor' && (
            <div className="flex flex-col h-full bg-white rounded-xl shadow-sm border overflow-hidden">
                {canUseAdvisor ? (
                    <>
                        <div className="flex-1 overflow-y-auto p-4 space-y-4">
                            <div className="bg-purple-50 p-4 rounded-xl text-sm text-purple-800 border border-purple-100 flex gap-3">
                                <div className="bg-purple-100 p-2 rounded-lg h-fit">
                                    <MessageSquare className="text-purple-600" size={20}/>
                                </div>
                                <div>
                                    <p className="font-bold mb-1">المساعد الأكاديمي الذكي (Gemini)</p>
                                    <p className="leading-relaxed">مرحباً! أنا مبرمج للإجابة بناءً على <span className="font-bold">اللائحة 501</span> للتعليم العالي في ليبيا.
                                    يمكنك سؤالي عن:</p>
                                    <ul className="list-disc list-inside mt-2 space-y-1 opacity-80">
                                        <li>وضع الطالب الأكاديمي بالنسبة للإنذارات</li>
                                        <li>شروط التسجيل والإيقاف</li>
                                        <li>حساب المعدلات والتقديرات</li>
                                    </ul>
