                                    <ChevronLeft size={14} className="text-green-500" />
                                    {rec}
                                </li>
                            ))}
                        </ul>
                    </div>
                </div>
            </div>
          )}

          {activeTab === 'docs' && (
              <div className="bg-white rounded-xl border shadow-sm p-8 flex flex-col items-center justify-center text-center">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4 text-slate-300">
