                  <button className="mt-6 bg-slate-800 text-white px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2">
                      <Plus size={18} /> رفع مستند جديد
                  </button>
                  <div className="w-full mt-8 grid grid-cols-2 gap-4">
                      <div className="p-4 border rounded-xl flex items-center gap-3 bg-slate-50 cursor-pointer hover:bg-slate-100">
                          <FileText className="text-blue-500" />
                          <div className="text-right">
                              <p className="text-xs font-bold">شهادة الثانوية العامة</p>
                              <p className="text-[10px] text-slate-400">PDF - 2.4 MB</p>
                          </div>
                      </div>
                      <div className="p-4 border rounded-xl flex items-center gap-3 bg-slate-50 cursor-pointer hover:bg-slate-100">
                          <FileText className="text-red-500" />
                          <div className="text-right">
                              <p className="text-xs font-bold">صورة جواز السفر</p>
                              <p className="text-[10px] text-slate-400">JPG - 1.1 MB</p>
                          </div>
                      </div>
                  </div>
              </div>
          )}
        </div>

        {/* Nested Grade Modal */}
        {showGradeModal && (
            <div className="absolute inset-0 bg-black/20 z-[60] flex items-center justify-center p-4">
                <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden">
                    <div className="bg-slate-900 text-white p-4 flex justify-between items-center">
                        <h4 className="font-bold">رصد درجة جديدة</h4>
                        <button onClick={() => setShowGradeModal(false)}><X size={20}/></button>
                    </div>
                    <form onSubmit={handleAddGrade} className="p-6 space-y-4">
                        <div>
                            <label className="block text-xs font-bold mb-1 text-slate-500">المقرر</label>
                            <select required className="w-full border rounded-lg p-2 text-sm" value={newGrade.courseId} onChange={e => setNewGrade({...newGrade, courseId: e.target.value})}>
                                <option value="">اختر المقرر...</option>
                                {availableCourses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold mb-1 text-slate-500">الدرجة (0-100)</label>
                                <input required type="number" className="w-full border rounded-lg p-2 text-sm font-mono" value={newGrade.score} onChange={e => setNewGrade({...newGrade, score: e.target.value})} />
                            </div>
                            <div>
                                <label className="block text-xs font-bold mb-1 text-slate-500">الفصل</label>
                                <input required type="text" className="w-full border rounded-lg p-2 text-sm" value={newGrade.semester} onChange={e => setNewGrade({...newGrade, semester: e.target.value})} />
                            </div>
                        </div>
                        <button type="submit" className="w-full bg-blue-600 text-white py-2 rounded-lg font-bold">حفظ الدرجة</button>
                    </form>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

