import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import StudentsList from './components/StudentsList';
import Academics from './components/Academics';
import Graduates from './components/Graduates';
import Reports from './components/Reports';
import Settings from './components/Settings';
import Financials from './components/Financials';
import ServiceRequests from './components/ServiceRequests';
import Faculty from './components/Faculty';
import Attendance from './components/Attendance';
import Schedule from './components/Schedule';
import ExamSchedule from './components/ExamSchedule';
import RolesManagement from './components/RolesManagement';
import Login from './components/Login';
import ToastContainer from './components/ToastContainer';
import { Book, FileText, Download, Lock } from 'lucide-react';
import { LIBYAN_REGULATION_501_SUMMARY } from './constants';
import { AuthUser } from './types';
import { getCurrentUser, logout, getAccessibleTabs } from './services/authService';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<AuthUser | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');

  useEffect(() => {
    const user = getCurrentUser();
    if (user) {
        setCurrentUser(user);
    }
  }, []);

  const handleLogin = (user: AuthUser) => {
      setCurrentUser(user);
      setActiveTab('dashboard');
  };

  const handleLogout = () => {
      logout();
      setCurrentUser(null);
  };

  const renderContent = () => {
    if (currentUser) {
        const allowedTabs = getAccessibleTabs(currentUser);
        if (!allowedTabs.includes(activeTab)) {
            return (
                <div className="flex flex-col items-center justify-center h-[80vh] text-slate-400">
                    <div className="bg-red-50 p-6 rounded-full mb-4">
                        <Lock size={48} className="text-red-500" />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-800 mb-2">الدخول غير مصرح به</h2>
                    <p>ليس لديك الصلاحيات الكافية للوصول إلى هذه الصفحة.</p>
                </div>
            );
        }
    }

    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'students': return <StudentsList />;
      case 'academics': return <Academics />;
      case 'schedule': return <Schedule />;
      case 'exams': return <ExamSchedule />;
      case 'faculty': return <Faculty />;
      case 'attendance': return <Attendance />;
      case 'financials': return <Financials />;
      case 'requests': return <ServiceRequests />;
      case 'reports': return <Reports />;
      case 'graduates': return <Graduates />;
      case 'roles': return <RolesManagement />;
      case 'settings': return <Settings />;
      case 'regulations':
        return (
          <div className="p-8 max-w-4xl mx-auto">
            <div className="mb-8">
              <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                <FileText className="text-blue-600" />
                لائحة التعليم العالي 501
              </h2>
            </div>
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
              <div className="bg-slate-50 p-4 border-b flex justify-between items-center">
                <span className="font-bold text-slate-700">نصوص اللائحة</span>
                <button className="text-blue-600 text-sm hover:underline flex items-center gap-1">
                  <Download size={16} /> تحميل PDF
                </button>
              </div>
              <div className="p-8">
                <div className="prose prose-slate max-w-none font-sans whitespace-pre-line leading-loose text-slate-700">
                  {LIBYAN_REGULATION_501_SUMMARY}
                </div>
              </div>
            </div>
          </div>
        );
      default:
        return <div className="p-8 text-center text-slate-400">قيد التطوير</div>;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="flex flex-row min-h-screen bg-slate-50 font-sans" dir="rtl">
        <ToastContainer />
        <div className="flex flex-col w-64 bg-slate-900 text-white shadow-xl print:hidden h-screen sticky top-0">
             <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} currentUser={currentUser} />
             <div className="p-4 border-t border-slate-700 mt-auto">
                <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 text-slate-300 hover:text-red-400 hover:bg-slate-800 rounded-lg transition-colors">
                    <span className="font-medium">تسجيل الخروج</span>
                </button>
             </div>
        </div>
        <main className="flex-1 overflow-x-hidden overflow-y-auto h-screen print:overflow-visible print:h-auto">
            {renderContent()}
        </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { getStudents, getCourses, getSystemSettings, saveStudent } from '../services/storageService';
import { Student, Course, StudentEnrollment } from '../types';
import { Search, Plus, Trash2, ClipboardCheck, BookOpen, AlertCircle, Save } from 'lucide-react';
import { notifySuccess, notifyError } from '../services/notificationService';
import { logAction } from '../services/auditService';
import { getCurrentUser } from '../services/authService';

const Registration: React.FC = () => {
    const [students, setStudents] = useState<Student[]>([]);
    const [courses, setCourses] = useState<Course[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
    const settings = getSystemSettings();
    const currentUser = getCurrentUser();

    useEffect(() => {
        setStudents(getStudents());
        setCourses(getCourses());
    }, []);

    const handleRegisterCourse = (courseId: string) => {
        if (!selectedStudent) return;

        const alreadyRegistered = selectedStudent.enrollments?.some(e => e.courseId === courseId && e.semester === settings.currentSemester);
        if (alreadyRegistered) {
            notifyError('الطالب مسجل بالفعل في هذا المقرر لهذا الفصل');
            return;
        }

        const newEnrollment: StudentEnrollment = {
            courseId,
            semester: settings.currentSemester,
            status: 'REGISTERED'
        };

        const updatedStudent = {
            ...selectedStudent,
            enrollments: [...(selectedStudent.enrollments || []), newEnrollment]
        };

        saveStudent(updatedStudent);
        setSelectedStudent(updatedStudent);
        setStudents(getStudents());
        notifySuccess('تم تسجيل المقرر بنجاح');
        logAction('تسجيل مقرر', `تم تسجيل ${courseId} للطالب ${selectedStudent.name}`, 'info', currentUser?.name);
    };

    const handleRemoveEnrollment = (courseId: string) => {
        if (!selectedStudent) return;

        const updatedEnrollments = selectedStudent.enrollments?.filter(e => !(e.courseId === courseId && e.semester === settings.currentSemester));

        const updatedStudent = {
            ...selectedStudent,
            enrollments: updatedEnrollments
        };

        saveStudent(updatedStudent);
        setSelectedStudent(updatedStudent);
        setStudents(getStudents());
        notifySuccess('تم حذف التسجيل');
    };

    const filteredStudents = students.filter(s => 
        s.name.includes(searchTerm) || s.id.includes(searchTerm)
    );

    return (
        <div className="p-8 h-screen flex flex-col">
            <div className="mb-8">
                <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                    <ClipboardCheck className="text-blue-600" />
                    تنزيل المواد (التسجيل الفصلي)
                </h2>
                <p className="text-slate-500 mt-1">إدارة تسجيل الطلاب في المقررات للفصل الحالي: {settings.currentSemester}</p>
            </div>

            <div className="flex gap-6 flex-1 overflow-hidden">
                <div className="w-1/3 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col">
                    <div className="p-4 border-b border-slate-200">
                        <div className="relative">
                            <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                            <input 
                                type="text" 
                                placeholder="بحث عن طالب..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full pr-10 pl-4 py-2 rounded-lg border border-slate-300 focus:ring-2 focus:ring-blue-500 outline-none"
                            />
                        </div>
                    </div>
                    <div className="flex-1 overflow-auto">
                        {filteredStudents.map(s => (
                            <div 
                                key={s.id}
                                onClick={() => setSelectedStudent(s)}
                                className={`p-4 border-b cursor-pointer transition-colors ${selectedStudent?.id === s.id ? 'bg-blue-50' : 'hover:bg-slate-50'}`}
                            >
                                <p className="font-bold text-slate-800">{s.name}</p>
                                <p className="text-xs text-slate-500 font-mono">{s.id} | {s.department}</p>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="w-2/3 flex flex-col gap-6 overflow-hidden">
                    {selectedStudent ? (
                        <>
                            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                                <div className="flex justify-between items-center mb-4">
                                    <h3 className="font-bold text-lg text-slate-800">المقررات المسجلة حالياً</h3>
                                    <span className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs font-bold">
                                        {selectedStudent.enrollments?.filter(e => e.semester === settings.currentSemester).length || 0} مواد
