import { ClassSession, DayOfWeek, ExamSession } from '../types';

const STORAGE_KEY_SCHEDULE = 'manara_sis_schedule';
const STORAGE_KEY_EXAMS = 'manara_sis_exams';

// --- Weekly Lectures ---

export const getSchedule = (): ClassSession[] => {
    const data = localStorage.getItem(STORAGE_KEY_SCHEDULE);
    return data ? JSON.parse(data) : [];
};

export const saveClassSession = (session: ClassSession): void => {
    const schedule = getSchedule();
    const index = schedule.findIndex(s => s.id === session.id);
    if (index >= 0) {
        schedule[index] = session;
    } else {
        schedule.push(session);
    }
    localStorage.setItem(STORAGE_KEY_SCHEDULE, JSON.stringify(schedule));
};

export const deleteClassSession = (id: string): void => {
    const schedule = getSchedule().filter(s => s.id !== id);
    localStorage.setItem(STORAGE_KEY_SCHEDULE, JSON.stringify(schedule));
};

// --- Exam Schedule ---

export const getExams = (): ExamSession[] => {
    const data = localStorage.getItem(STORAGE_KEY_EXAMS);
    return data ? JSON.parse(data) : [];
};

export const saveExam = (exam: ExamSession): void => {
    const exams = getExams();
    const index = exams.findIndex(e => e.id === exam.id);
    if (index >= 0) {
        exams[index] = exam;
    } else {
        exams.push(exam);
    }
    localStorage.setItem(STORAGE_KEY_EXAMS, JSON.stringify(exams));
};

export const deleteExam = (id: string): void => {
    const exams = getExams().filter(e => e.id !== id);
    localStorage.setItem(STORAGE_KEY_EXAMS, JSON.stringify(exams));
};

// --- Conflict Detection Logic ---

interface ConflictResult {
    hasConflict: boolean;
    message?: string;
    conflictingType?: 'ROOM' | 'COURSE' | 'INVIGILATOR';
}

const toMinutes = (time: string) => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
};

export const checkScheduleConflict = (newSession: ClassSession, excludeId?: string): ConflictResult => {
    const schedule = getSchedule().filter(s => s.id !== excludeId);
    const newStart = toMinutes(newSession.startTime);
    const newEnd = toMinutes(newSession.endTime);

    for (const existing of schedule) {
        if (existing.day !== newSession.day) continue;
        const existStart = toMinutes(existing.startTime);
        const existEnd = toMinutes(existing.endTime);
        const isOverlapping = (newStart < existEnd) && (newEnd > existStart);

        if (isOverlapping) {
            if (existing.room === newSession.room) {
                return { hasConflict: true, message: `تعارض في القاعة: ${newSession.room} محجوزة لمقرر ${existing.courseName}.` };
            }
            if (existing.instructorId === newSession.instructorId) {
                return { hasConflict: true, message: `الدكتور ${newSession.instructorName} لديه محاضرة أخرى في هذا الوقت.` };
            }
        }
    }
    return { hasConflict: false };
};

export const checkExamConflict = (newExam: ExamSession, excludeId?: string): ConflictResult => {
    const exams = getExams().filter(e => e.id !== excludeId);
    const newStart = toMinutes(newExam.startTime);
    const newEnd = newStart + newExam.durationMinutes;

    for (const existing of exams) {
        if (existing.date !== newExam.date) continue;

        const existStart = toMinutes(existing.startTime);
        const existEnd = existStart + existing.durationMinutes;
        const isOverlapping = (newStart < existEnd) && (newEnd > existStart);

        if (isOverlapping) {
            // 1. Room Conflict
            if (existing.room === newExam.room) {
                return { 
                    hasConflict: true, 
                    conflictingType: 'ROOM',
                    message: `تعارض قاعات: القاعة (${newExam.room}) مشغولة بامتحان مقرر "${existing.courseName}".` 
                };
            }

            // 2. Course Conflict
            if (existing.courseId === newExam.courseId) {
                 return { 
                    hasConflict: true, 
                    conflictingType: 'COURSE',
                    message: `يوجد امتحان مجدول لهذا المقرر ("${existing.courseName}") في هذا الوقت.` 
                };
            }

            // 3. Invigilator Conflict
            const overlapInvigilators = newExam.invigilators.filter(id => existing.invigilators.includes(id));
            if (overlapInvigilators.length > 0) {
                return {
                    hasConflict: true,
                    conflictingType: 'INVIGILATOR',
                    message: `تعارض مراقبين: يوجد مراقب أو أكثر لديهم مهام في امتحان مقرر "${existing.courseName}" في نفس الوقت.`
                };
            }
        }
    }
    return { hasConflict: false };
};

export const getDayLabel = (day: DayOfWeek): string => {
    const map: Record<DayOfWeek, string> = {
        'SATURDAY': 'السبت', 'SUNDAY': 'الأحد', 'MONDAY': 'الاثنين', 
        'TUESDAY': 'الثلاثاء', 'WEDNESDAY': 'الأربعاء', 'THURSDAY': 'الخميس'
    };
    return map[day];
};

export const getInstructorSchedule = (instructorId: string): ClassSession[] => {
    return getSchedule().filter(s => s.instructorId === instructorId);
};

import React, { useState, useEffect } from 'react';
import { getCourses } from '../services/storageService';
import { getInstructors } from '../services/facultyService';
import { getExams, saveExam, deleteExam, checkExamConflict } from '../services/scheduleService';
import { ExamSession, Course, Instructor, Permission } from '../types';
import { Calendar, Plus, Trash2, Clock, MapPin, AlertCircle, Save, X, Printer, FileText, Search, UserCheck } from 'lucide-react';
import { notifySuccess, notifyError, notifyWarning } from '../services/notificationService';
import { logAction } from '../services/auditService';
import { getCurrentUser, hasPermission } from '../services/authService';

const ExamSchedule: React.FC = () => {
    const [exams, setExams] = useState<ExamSession[]>([]);
    const [courses, setCourses] = useState<Course[]>([]);
    const [instructors, setInstructors] = useState<Instructor[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const currentUser = getCurrentUser();
    const canManageAcademics = hasPermission(currentUser, Permission.ACADEMICS_MANAGE);

    const [showModal, setShowModal] = useState(false);
    const [currentExam, setCurrentExam] = useState<Partial<ExamSession>>({
        date: new Date().toISOString().split('T')[0],
        startTime: '09:00',
        durationMinutes: 120,
        room: '',
        invigilators: []
    });

    useEffect(() => {
        refreshData();
    }, []);

    const refreshData = () => {
        setExams(getExams());
        setCourses(getCourses());
        setInstructors(getInstructors());
    };

    const handleSave = (e: React.FormEvent) => {
        e.preventDefault();

        if (!currentExam.courseId || !currentExam.room || !currentExam.date) {
            notifyError('الرجاء تعبئة كافة الحقول المطلوبة');
            return;
        }

        const course = courses.find(c => c.id === currentExam.courseId);

        const newExam: ExamSession = {
            id: currentExam.id || `EXAM-${Date.now()}`,
            courseId: currentExam.courseId,
            courseName: course?.name || '',
            date: currentExam.date,
            startTime: currentExam.startTime || '09:00',
            durationMinutes: Number(currentExam.durationMinutes) || 120,
            room: currentExam.room,
            invigilators: currentExam.invigilators || []
        };

        const conflict = checkExamConflict(newExam, currentExam.id);
        if (conflict.hasConflict) {
            notifyError(conflict.message || 'يوجد تعارض في الجدول');
            return;
        }

        saveExam(newExam);
        logAction('جدول الامتحانات', `تم ${currentExam.id ? 'تعديل' : 'جدولة'} امتحان مقرر "${newExam.courseName}"`, 'info', currentUser?.name);
        notifySuccess('تم حفظ موعد الامتحان بنجاح');
        setShowModal(false);
        refreshData();
        resetForm();
    };

    const resetForm = () => {
        setCurrentExam({ 
            date: new Date().toISOString().split('T')[0], 
            startTime: '09:00', 
            durationMinutes: 120, 
            room: '', 
            invigilators: [] 
        });
    };

    const handleDelete = (id: string) => {
        if (!canManageAcademics) return;
        if (confirm('هل أنت متأكد من حذف هذا الامتحان؟')) {
            const exam = exams.find(e => e.id === id);
            deleteExam(id);
            logAction('حذف امتحان', `تم حذف امتحان مقرر "${exam?.courseName}"`, 'danger', currentUser?.name);
            refreshData();
            notifySuccess('تم حذف الموعد');
        }
    };

    const filteredExams = exams.filter(e => 
        e.courseName.includes(searchTerm) || 
        e.courseId.includes(searchTerm) || 
        e.room.includes(searchTerm)
    ).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const groupedExams: Record<string, ExamSession[]> = {};
    filteredExams.forEach(exam => {
        if (!groupedExams[exam.date]) groupedExams[exam.date] = [];
        groupedExams[exam.date].push(exam);
    });

    return (
        <div className="p-8">
            <div className="mb-8 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 no-print">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                        <FileText className="text-blue-600" />
                        جدول الامتحانات النهائية
                    </h2>
                    <p className="text-slate-500 mt-1">تنسيق المواعيد الرسمية وتوزيع اللجان والمراقبين</p>
                </div>
                <div className="flex gap-3 w-full md:w-auto">
                    <div className="relative flex-1 md:w-64">
                        <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input 
                            type="text" 
                            placeholder="بحث عن مقرر أو قاعة..."
                            className="w-full pr-10 pl-4 py-2 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                        />
                    </div>
                    <button 
                        onClick={() => window.print()}
                        className="bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-xl flex items-center gap-2 hover:bg-slate-50 transition-all shadow-sm"
                    >
                        <Printer size={18} />
                        <span>طباعة</span>
                    </button>
                    {canManageAcademics && (
                        <button 
                            onClick={() => { resetForm(); setShowModal(true); }}
                            className="bg-blue-600 text-white px-5 py-2 rounded-xl flex items-center gap-2 hover:bg-blue-700 transition-all shadow-lg shadow-blue-200"
