const Communications: React.FC = () => {
    const [students, setStudents] = useState<Student[]>([]);
    const [targetType, setTargetType] = useState<'UNPAID' | 'UNREGISTERED' | 'ALL'>('UNPAID');
    const [template, setTemplate] = useState<'TUITION' | 'REGISTRATION' | 'CUSTOM'>('TUITION');
    const [customTitle, setCustomTitle] = useState('');
    const [customMessage, setCustomMessage] = useState('');
    const [sending, setSending] = useState(false);

    const settings = getSystemSettings();
    const currentUser = getCurrentUser();

    useEffect(() => {
        setStudents(getStudents());
    }, []);

    const getTargetStudents = () => {
        return students.filter(s => {
            if (targetType === 'UNPAID') return calculateBalance(s.id) > 0;
            if (targetType === 'UNREGISTERED') {
                const isEnrolled = s.enrollments?.some(e => e.semester === settings.currentSemester);
                return !isEnrolled;
            }
            return true;
        });
    };

    const targetStudents = getTargetStudents();

    const handleSendBroadcast = async () => {
        if (targetStudents.length === 0) {
            notifyError('لا يوجد طلاب مستهدفين لهذا التنبيه');
            return;
        }

        if (template === 'CUSTOM' && (!customTitle || !customMessage)) {
            notifyError('يرجى كتابة عنوان ورسالة التنبيه');
            return;
        }

        setSending(true);

        const title = template === 'TUITION' ? 'تذكير بسداد الرسوم الدراسية' :
                      template === 'REGISTRATION' ? 'تذكير بموعد تنزيل المواد' : customTitle;

        const message = template === 'TUITION' ? `نود تذكيركم بضرورة سداد الرسوم المتأخرة لتجنب إيقاف القيد. الفصل: ${settings.currentSemester}` :
                        template === 'REGISTRATION' ? `يرجى التوجه لموقع الجامعة لإتمام عملية تنزيل المواد قبل انتهاء المهلة المحددة للفصل: ${settings.currentSemester}` : customMessage;

        // Simulate network delay
        await new Promise(resolve => setTimeout(resolve, 1500));

        targetStudents.forEach(s => {
            const notification: StudentNotification = {
                id: `NTF-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
                title,
                message,
                date: new Date().toISOString(),
                type: 'REMINDER',
                channel: 'PORTAL'
            };

            const updatedStudent = {
                ...s,
                notifications: [notification, ...(s.notifications || [])]
            };
            saveStudent(updatedStudent);
        });

        logAction('إرسال تعميم', `تم إرسال تنبيه "${title}" إلى ${targetStudents.length} طالب`, 'info', currentUser?.name);
        notifySuccess(`تم إرسال ${targetStudents.length} تنبيه بنجاح`);

        setSending(false);
        if (template === 'CUSTOM') {
            setCustomTitle('');
            setCustomMessage('');
        }
    };

    return (
        <div className="p-8 max-w-5xl mx-auto">
            <div className="mb-8">
                <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                    <Bell className="text-blue-600" />
                    مركز التنبيهات والتعميمات
                </h2>
                <p className="text-slate-500 mt-1">إرسال تذكيرات آلية للطلاب بناءً على حالتهم المالية والأكاديمية</p>
            </div>

