};

export default Communications;

import React, { useState, useEffect } from 'react';
import { Student, StudentStatus, ProgramType, Course, Permission, StudentNotification } from '../types';
import { X, AlertTriangle, CheckCircle, ShieldAlert, Book, User, Info, Plus, Printer, Edit2, Medal, Wallet, FileText, UserCheck, Lock, ChevronLeft, FileUp, Bell, Clock } from 'lucide-react';
import { evaluateAcademicStanding, StandingReport } from '../services/advisorService';
import { getCourses, getSystemSettings } from '../services/storageService';
import { calculateWeightedGPA, evaluateAcademicStatus } from '../services/gradingService';
import { calculateBalance } from '../services/financeService'; 
import { getStudentAttendanceStats } from '../services/facultyService';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';
import { logAction } from '../services/auditService';
import { notifySuccess, notifyError, notifyInfo } from '../services/notificationService';
import { getCurrentUser, hasPermission } from '../services/authService';

interface StudentDetailsProps {
  student: Student;
  onClose: () => void;
  onUpdate?: (student: Student) => void;
}

const StudentDetails: React.FC<StudentDetailsProps> = ({ student, onClose, onUpdate }) => {
  const [activeTab, setActiveTab] = useState<'info' | 'grades' | 'advisor' | 'docs' | 'notifications'>('info');
  const [standingReport, setStandingReport] = useState<StandingReport | null>(null);
  const currentUser = getCurrentUser();

  const [availableCourses, setAvailableCourses] = useState<Course[]>([]);
  const [defaultSemester, setDefaultSemester] = useState('خريف 2024');
  const [financialBalance, setFinancialBalance] = useState(0); 
  const [attendanceStats, setAttendanceStats] = useState({ total: 0, absenceRate: 0 });

  const [showGradeModal, setShowGradeModal] = useState(false);
  const [newGrade, setNewGrade] = useState({ courseId: '', score: '', semester: '' });
  const [isEditingStatus, setIsEditingStatus] = useState(false);
  const [showTranscript, setShowTranscript] = useState(false);

  // Permissions
  const canEditGrades = hasPermission(currentUser, Permission.GRADES_EDIT);
  const canEditStatus = hasPermission(currentUser, Permission.STUDENTS_EDIT);

  useEffect(() => {
      setAvailableCourses(getCourses());
      const settings = getSystemSettings();
      setDefaultSemester(settings.currentSemester);
      setNewGrade(prev => ({ ...prev, semester: settings.currentSemester }));
      setFinancialBalance(calculateBalance(student.id));
      setAttendanceStats(getStudentAttendanceStats(student.id));
      setStandingReport(evaluateAcademicStanding(student));
  }, [student]);

  const handleAddGrade = (e: React.FormEvent) => {
    e.preventDefault();
    if (!onUpdate || !newGrade.courseId || !newGrade.score) return;

    const course = availableCourses.find(c => c.id === newGrade.courseId);
    if (!course) return;

    const scoreNum = parseFloat(newGrade.score);
    if (isNaN(scoreNum) || scoreNum < 0 || scoreNum > 100) {
        notifyError("الرجاء إدخال درجة صحيحة بين 0 و 100");
        return;
    }

    const existingGradeIndex = student.grades.findIndex(g => g.courseId === newGrade.courseId);
    const existingGrade = existingGradeIndex >= 0 ? student.grades[existingGradeIndex] : null;
    const oldScore = existingGrade ? existingGrade.score : null;

    let updatedGrades = [...student.grades];
    if (existingGradeIndex >= 0) {
        updatedGrades[existingGradeIndex] = { ...existingGrade, score: scoreNum, semester: newGrade.semester };
    } else {
        updatedGrades.push({ courseId: course.id, courseName: course.name, score: scoreNum, semester: newGrade.semester });
    }

    const newGpa = calculateWeightedGPA(updatedGrades, availableCourses);
    const statusResult = evaluateAcademicStatus(newGpa, student.program, student.status, student.warningsCount);

    const updatedStudent = {
        ...student,
        grades: updatedGrades,
        gpa: newGpa,
        status: statusResult.status,
        warningsCount: statusResult.warningsCount
    };

    onUpdate(updatedStudent);

    const isNew = oldScore === null;
    logAction(
        isNew ? 'إضافة درجة' : 'تعديل درجة',
        `الطالب: ${student.name} | المقرر: ${course.name} | الدرجة: ${isNew ? 'جديد' : oldScore} -> ${scoreNum}`,
        isNew ? 'info' : 'warning',
        currentUser?.name
    );

    notifySuccess(isNew ? 'تم رصد الدرجة بنجاح' : 'تم تعديل الدرجة بنجاح');
    setShowGradeModal(false);
    setNewGrade({ courseId: '', score: '', semester: defaultSemester });
  };

  const handleStatusChange = (newStatus: StudentStatus) => {
      if (!onUpdate) return;
      const oldStatus = student.status;
      onUpdate({ ...student, status: newStatus });
      logAction('تغيير حالة طالب', `من ${oldStatus} إلى ${newStatus}`, 'warning', currentUser?.name);
      notifyInfo(`تم تحديث الحالة إلى ${newStatus}`);
      setIsEditingStatus(false);
  };

  const statusColor = {
    [StudentStatus.ACTIVE]: 'bg-green-100 text-green-700',
    [StudentStatus.WARNING]: 'bg-red-100 text-red-700',
    [StudentStatus.SUSPENDED]: 'bg-gray-100 text-gray-700',
    [StudentStatus.GRADUATED]: 'bg-blue-100 text-blue-700',
    [StudentStatus.WITHDRAWN]: 'bg-yellow-100 text-yellow-700',
  };

  const passingScore = student.program === ProgramType.POSTGRADUATE ? 65 : 50;

  const getGradeLabel = (gpa: number, program: ProgramType) => {
    if (gpa >= 85) return { label: 'ممتاز', color: 'text-green-600' };
    if (gpa >= 75) return { label: 'جيد جداً', color: 'text-blue-600' };
    if (gpa >= 65) return { label: 'جيد', color: 'text-yellow-600' };
    return gpa >= passingScore ? { label: 'مقبول', color: 'text-slate-600' } : { label: 'ضعيف/راسب', color: 'text-red-600' };
  };

  const gradeInfo = getGradeLabel(student.gpa, student.program);

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
      <div className="bg-white w-full max-w-5xl rounded-2xl shadow-2xl h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in duration-200">

        {/* Header */}
        <div className="bg-slate-900 text-white p-6 flex justify-between items-start">
          <div className="flex gap-4">
            <div className="w-16 h-16 bg-slate-700 rounded-full flex items-center justify-center border-2 border-blue-500 shadow-lg relative">
              <span className="text-2xl font-bold">{student.name.charAt(0)}</span>
              {student.warningsCount >= 3 && (
                  <div className="absolute -top-1 -right-1 bg-red-500 rounded-full p-1 border border-white animate-pulse">
                      <AlertTriangle size={12} className="text-white"/>
                  </div>
              )}
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-2xl font-bold">{student.name}</h2>
                {student.gpa >= 85 && (
                    <span className="bg-yellow-400 text-yellow-900 text-[10px] font-bold px-2 py-0.5 rounded-full flex items-center gap-1">
                        <Medal size={12} /> متميز
                    </span>
                )}
              </div>
              <div className="flex items-center gap-3 mt-1 text-slate-300">
                <span className="bg-slate-800 px-2 py-0.5 rounded-md text-xs">{student.id}</span>
                <span className="text-slate-600">|</span>
                <span>{student.department}</span>
                <span className="text-slate-600">|</span>
                <button 
                    disabled={!canEditStatus}
                    onClick={() => canEditStatus && setIsEditingStatus(true)}
                    className={`flex items-center gap-1 px-2 py-0.5 rounded text-xs font-bold ${statusColor[student.status]} bg-opacity-20`}
                >
                    {student.status}
                    {canEditStatus && <Edit2 size={10} className="ms-1 opacity-50"/>}
                </button>
              </div>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-slate-800 rounded-full">
            <X size={24} />
          </button>
        </div>

        {/* Tabs */}
        <div className="border-b border-gray-200 px-6 pt-4 flex gap-6 bg-slate-50 overflow-x-auto no-scrollbar">
          <button onClick={() => setActiveTab('info')} className={`pb-4 px-2 text-sm font-medium border-b-2 ${activeTab === 'info' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-500'}`}>البيانات الأساسية</button>
          <button onClick={() => setActiveTab('grades')} className={`pb-4 px-2 text-sm font-medium border-b-2 ${activeTab === 'grades' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-500'}`}>كشف الدرجات</button>
          <button onClick={() => setActiveTab('advisor')} className={`pb-4 px-2 text-sm font-medium border-b-2 ${activeTab === 'advisor' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-500'}`}>الوضعية القانونية (501)</button>
          <button onClick={() => setActiveTab('notifications')} className={`pb-4 px-2 text-sm font-medium border-b-2 ${activeTab === 'notifications' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-500'}`}>التنبيهات {student.notifications && student.notifications.length > 0 && <span className="ms-1 bg-red-100 text-red-600 px-1.5 py-0.5 rounded-full text-[10px]">{student.notifications.length}</span>}</button>
          <button onClick={() => setActiveTab('docs')} className={`pb-4 px-2 text-sm font-medium border-b-2 ${activeTab === 'docs' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-500'}`}>الأرشيف والمستندات</button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 bg-gray-50">

          {activeTab === 'info' && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-6">
                 {student.warningsCount >= 3 && (
                     <div className="bg-red-50 border border-red-200 rounded-xl p-4 flex items-start gap-3">
                         <ShieldAlert className="text-red-600 shrink-0" />
                         <div>
                             <h4 className="font-bold text-red-800">حالة فصل أكاديمي</h4>
                             <p className="text-sm text-red-700">تجاوز الطالب الحد الأقصى للإنذارات (المادة 46). يجب عرض الملف على اللجنة المختصة.</p>
                         </div>
                     </div>
                 )}

                 <div className="bg-white p-6 rounded-xl shadow-sm border">
                    <h3 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2"><Book size={20} className="text-blue-500"/> معلومات القيد</h3>
                    <div className="space-y-4 text-sm">
                        <div className="flex justify-between border-b pb-2"><span>الرقم الوطني</span><span className="font-mono">{student.nationalId}</span></div>
                        <div className="flex justify-between border-b pb-2"><span>سنة القبول</span><span>{student.enrollmentYear}</span></div>
                        <div className="flex justify-between border-b pb-2"><span>البرنامج</span><span>{student.program}</span></div>
                        <div className="flex justify-between border-b pb-2"><span>الإنذارات الأكاديمية</span><span className="font-bold text-red-600">{student.warningsCount}</span></div>
                        <div className="flex justify-between"><span>نسبة الغياب</span><span className={attendanceStats.absenceRate > 20 ? 'text-red-600 font-bold' : ''}>{attendanceStats.absenceRate}%</span></div>
                    </div>
                 </div>
              </div>

              <div className="bg-white p-6 rounded-xl shadow-sm border flex flex-col items-center justify-center">
                 <div className="w-40 h-40 rounded-full border-8 border-gray-100 flex items-center justify-center relative mb-4">
                    <svg className="w-full h-full transform -rotate-90 absolute top-0 left-0">
                        <circle cx="80" cy="80" r="70" stroke="currentColor" strokeWidth="10" fill="transparent" className="text-gray-100" />
                        <circle cx="80" cy="80" r="70" stroke="currentColor" strokeWidth="10" fill="transparent" className={student.gpa >= passingScore ? "text-blue-500" : "text-red-500"} strokeDasharray={440} strokeDashoffset={440 - (440 * student.gpa) / 100} strokeLinecap="round" />
                    </svg>
                    <div className="flex flex-col items-center">
                        <span className="text-3xl font-bold text-gray-800">%{student.gpa}</span>
                        <span className={`text-xs font-bold ${gradeInfo.color}`}>{gradeInfo.label}</span>
                    </div>
                 </div>
                 <div className="flex gap-2 w-full mt-4">
                     <button onClick={() => setShowTranscript(true)} className="flex-1 bg-blue-600 text-white py-2 rounded-lg text-sm font-bold shadow-sm">إصدار إفادة</button>
                     <button className="flex-1 bg-white border py-2 rounded-lg text-sm font-bold">السجل المالي</button>
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'grades' && (
            <div className="space-y-6">
                <div className="flex justify-between items-center">
                    <h3 className="font-bold text-gray-800">كشف الدرجات التفصيلي</h3>
                    {canEditGrades && (
                        <button onClick={() => setShowGradeModal(true)} className="bg-blue-600 text-white px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1"><Plus size={14}/> رصد درجة</button>
                    )}
                </div>
                <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
                    <table className="w-full text-right text-sm">
                        <thead className="bg-gray-50 text-gray-500 font-medium">
                            <tr>
                                <th className="px-6 py-3">المقرر</th>
                                <th className="px-6 py-3">الفصل</th>
                                <th className="px-6 py-3">الدرجة</th>
                                <th className="px-6 py-3">النتيجة</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y">
                            {student.grades.map((g, i) => (
                                <tr key={i} className="hover:bg-slate-50">
                                    <td className="px-6 py-4">
                                        <div className="font-bold text-slate-800">{g.courseName}</div>
                                        <div className="text-[10px] text-slate-400 font-mono">{g.courseId}</div>
                                    </td>
                                    <td className="px-6 py-4 text-slate-600">{g.semester}</td>
                                    <td className="px-6 py-4 font-mono font-bold">{g.score}%</td>
                                    <td className="px-6 py-4">
                                        <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${g.score >= passingScore ? 'bg-green-50 text-green-700 border border-green-100' : 'bg-red-50 text-red-700 border border-red-100'}`}>
                                            {g.score >= passingScore ? 'ناجح' : 'راسب'}
                                        </span>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
          )}

          {activeTab === 'advisor' && standingReport && (
            <div className="space-y-6 animate-in fade-in duration-300">
                <div className={`p-6 rounded-2xl border flex items-start gap-4 ${
                    standingReport.standing === 'CRITICAL' ? 'bg-red-50 border-red-200' :
                    standingReport.standing === 'WARNING' ? 'bg-amber-50 border-amber-200' :
                    'bg-blue-50 border-blue-200'
                }`}>
                    <div className={`p-3 rounded-xl ${
                        standingReport.standing === 'CRITICAL' ? 'bg-red-100 text-red-600' :
                        standingReport.standing === 'WARNING' ? 'bg-amber-100 text-amber-600' :
                        'bg-blue-100 text-blue-600'
                    }`}>
                        <ShieldAlert size={32} />
                    </div>
                    <div>
                        <h3 className="font-bold text-lg mb-1">التقرير الأكاديمي طبقاً للائحة 501</h3>
                        <p className="text-slate-700">{standingReport.message}</p>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="bg-white p-6 rounded-xl border shadow-sm">
                        <h4 className="font-bold text-slate-800 mb-4 flex items-center gap-2 text-sm border-b pb-2">
                            <Info size={16} className="text-blue-500" /> مراجع قانونية (لائحة 501)
                        </h4>
                        <ul className="space-y-3">
                            {standingReport.regulations.map((reg, idx) => (
                                <li key={idx} className="text-xs text-slate-600 leading-relaxed flex gap-2">
                                    <span className="w-1.5 h-1.5 rounded-full bg-blue-300 mt-1.5 shrink-0"></span>
                                    {reg}
                                </li>
                            ))}
                        </ul>
                    </div>

                    <div className="bg-white p-6 rounded-xl border shadow-sm">
                        <h4 className="font-bold text-slate-800 mb-4 flex items-center gap-2 text-sm border-b pb-2">
                            <CheckCircle size={16} className="text-green-500" /> خطة التوصيات المقترحة
                        </h4>
                        <ul className="space-y-3">
                            {standingReport.recommendations.map((rec, idx) => (
                                <li key={idx} className="text-xs text-slate-700 font-medium flex gap-2 items-center">
                                    <ChevronLeft size={14} className="text-green-500" />
                                    {rec}
                                </li>
                            ))}
                        </ul>
                    </div>
                </div>
            </div>
          )}

          {activeTab === 'notifications' && (
              <div className="space-y-4">
