const STORAGE_KEY_COURSES = 'manara_sis_courses';
const STORAGE_KEY_SETTINGS = 'manara_sis_settings';
const STORAGE_KEY_BUILDINGS = 'manara_sis_buildings';
const STORAGE_KEY_ROOMS = 'manara_sis_rooms';

