// Fix: Removed notifyWarning from imports as it is not exported by notificationService and not used in this file.
import React, { useState, useEffect } from 'react';
import { getCourses, getInstructors, getRooms } from '../services/storageService';
import { getExams, saveExam, deleteExam, checkExamConflict } from '../services/scheduleService';
import { ExamSession, Course, Instructor, Permission, Room } from '../types';
import { Calendar, Plus, Trash2, Clock, MapPin, AlertCircle, Save, X, Printer, FileText, Search, UserCheck } from 'lucide-react';
import { notifySuccess, notifyError } from '../services/notificationService';
import { logAction } from '../services/auditService';
import { getCurrentUser, hasPermission } from '../services/authService';

const ExamSchedule: React.FC = () => {
    const [exams, setExams] = useState<ExamSession[]>([]);
    const [courses, setCourses] = useState<Course[]>([]);
    const [instructors, setInstructors] = useState<Instructor[]>([]);
    const [rooms, setRooms] = useState<Room[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const currentUser = getCurrentUser();
    const canManageAcademics = hasPermission(currentUser, Permission.ACADEMICS_MANAGE);

    const [showModal, setShowModal] = useState(false);
    const [currentExam, setCurrentExam] = useState<Partial<ExamSession>>({
        date: new Date().toISOString().split('T')[0],
        startTime: '09:00',
        durationMinutes: 120,
        room: '',
        invigilators: []
    });

    useEffect(() => {
        refreshData();
    }, []);

    const refreshData = () => {
        setExams(getExams());
        setCourses(getCourses());
        setInstructors(getInstructors());
        setRooms(getRooms());
    };

    const handleSave = (e: React.FormEvent) => {
        e.preventDefault();

        if (!currentExam.courseId || !currentExam.room || !currentExam.date) {
            notifyError('الرجاء تعبئة كافة الحقول المطلوبة');
            return;
        }

        const course = courses.find(c => c.id === currentExam.courseId);

        const newExam: ExamSession = {
            id: currentExam.id || `EXAM-${Date.now()}`,
            courseId: currentExam.courseId,
            courseName: course?.name || '',
            date: currentExam.date,
            startTime: currentExam.startTime || '09:00',
            durationMinutes: Number(currentExam.durationMinutes) || 120,
            room: currentExam.room,
            invigilators: currentExam.invigilators || []
        };

        const conflict = checkExamConflict(newExam, currentExam.id);
        if (conflict.hasConflict) {
            notifyError(conflict.message || 'يوجد تعارض في الجدول');
            return;
        }

        saveExam(newExam);
        logAction('جدول الامتحانات', `تم ${currentExam.id ? 'تعديل' : 'جدولة'} امتحان مقرر "${newExam.courseName}"`, 'info', currentUser?.name);
        notifySuccess('تم حفظ موعد الامتحان بنجاح');
        setShowModal(false);
        refreshData();
        resetForm();
    };

    const resetForm = () => {
        setCurrentExam({ 
            date: new Date().toISOString().split('T')[0], 
            startTime: '09:00', 
            durationMinutes: 120, 
            room: '', 
            invigilators: [] 
        });
    };

    const handleDelete = (id: string) => {
        if (!canManageAcademics) return;
        if (confirm('هل أنت متأكد من حذف هذا الامتحان؟')) {
            const exam = exams.find(e => e.id === id);
            deleteExam(id);
            logAction('حذف امتحان', `تم حذف امتحان مقرر "${exam?.courseName}"`, 'danger', currentUser?.name);
            refreshData();
            notifySuccess('تم حذف الموعد');
        }
    };

    const filteredExams = exams.filter(e => 
        e.courseName.includes(searchTerm) || 
        e.courseId.includes(searchTerm) || 
        e.room.includes(searchTerm)
    ).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const groupedExams: Record<string, ExamSession[]> = {};
    filteredExams.forEach(exam => {
        if (!groupedExams[exam.date]) groupedExams[exam.date] = [];
        groupedExams[exam.date].push(exam);
    });

    return (
        <div className="p-8">
            <div className="mb-8 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 no-print">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                        <FileText className="text-blue-600" />
                        جدول الامتحانات النهائية
                    </h2>
                    <p className="text-slate-500 mt-1">تنسيق المواعيد الرسمية وتوزيع اللجان والمراقبين</p>
                </div>
                <div className="flex gap-3 w-full md:w-auto">
                    <div className="relative flex-1 md:w-64">
                        <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input 
                            type="text" 
                            placeholder="بحث عن مقرر أو قاعة..."
                            className="w-full pr-10 pl-4 py-2 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                        />
                    </div>
                    <button 
                        onClick={() => window.print()}
                        className="bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-xl flex items-center gap-2 hover:bg-slate-50 transition-all shadow-sm"
                    >
                        <Printer size={18} />
                        <span>طباعة</span>
                    </button>
                    {canManageAcademics && (
                        <button 
                            onClick={() => { resetForm(); setShowModal(true); }}
                            className="bg-blue-600 text-white px-5 py-2 rounded-xl flex items-center gap-2 hover:bg-blue-700 transition-all shadow-lg shadow-blue-200"
                        >
                            <Plus size={20} />
                            <span>إضافة امتحان</span>
                        </button>
                    )}
                </div>
            </div>

            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden print-area">
