                                            </div>
                                            {canManageAcademics && (
                                                <div className="no-print flex gap-2">
                                                    <button 
                                                        onClick={() => { setCurrentExam(exam); setShowModal(true); }}
                                                        className="p-2.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all opacity-0 group-hover:opacity-100"
                                                    >
                                                        <FileText size={20} />
