                                    className="w-full border-2 border-slate-100 bg-slate-50 rounded-xl px-4 py-3 h-32 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all"
                                    multiple
                                    value={currentExam.invigilators}
                                    onChange={e => {
                                        const selected = Array.from(e.target.selectedOptions, (option: HTMLOptionElement) => option.value);
                                        setCurrentExam({...currentExam, invigilators: selected});
                                    }}
                                >
                                    {instructors.map(i => (
                                        <option key={i.id} value={i.id} className="p-1">{i.name} ({i.department})</option>
                                    ))}
                                </select>
                                <p className="text-[10px] text-slate-400 mt-2 flex items-center gap-1">
                                    <AlertCircle size={10} />
                                    اضغط مفتاح CTRL لتحديد أكثر من مراقب. سيتم التحقق من تضارب المواعيد تلقائياً.
                                </p>
                            </div>

                            <div className="pt-6 flex justify-end gap-4 border-t border-slate-100">
                                <button 
                                    type="button" 
                                    onClick={() => setShowModal(false)} 
                                    className="px-6 py-3 text-slate-500 hover:bg-slate-50 rounded-xl font-bold transition-all"
                                >
                                    إلغاء
                                </button>
                                <button 
                                    type="submit" 
                                    className="px-10 py-3 bg-blue-600 text-white rounded-xl font-black hover:bg-blue-700 shadow-xl shadow-blue-200 transition-all active:scale-95 flex items-center gap-2"
                                >
                                    <Save size={20} />
                                    حفظ وتعميم
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

const toMinutes = (time: string) => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
};

export default ExamSchedule;

import React, { useState, useEffect } from 'react';
// @fix: getInstructors is exported from facultyService, not storageService
import { getCourses, getRooms, getBuildings } from '../services/storageService';
