                    </div>
                </div>

                {days.map(day => {
                    const daySessions = schedule
                        .filter(s => s.day === day)
                        .sort((a, b) => a.startTime.localeCompare(b.startTime));

                    return (
                        <div key={day} className="grid grid-cols-7 border-b border-slate-100 min-h-[120px] hover:bg-slate-50 transition-colors">
                            <div className="p-4 font-bold text-slate-700 border-l bg-slate-50/50 flex items-center justify-center">
                                {getDayLabel(day)}
                            </div>
                            <div className="col-span-6 p-2 flex flex-wrap gap-3 items-center">
                                {daySessions.length > 0 ? daySessions.map(session => (
                                    <div key={session.id} className="bg-white border border-l-4 border-l-blue-500 border-slate-200 rounded-lg p-3 shadow-sm hover:shadow-md transition-shadow w-64 group relative">
