                        </div>

                        <form onSubmit={handleSave} className="p-6 space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">المقرر الدراسي</label>
                                <select 
                                    required
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2"
                                    value={currentSession.courseId}
                                    onChange={e => setCurrentSession({...currentSession, courseId: e.target.value})}
                                >
                                    <option value="">اختر المقرر...</option>
                                    {courses.map(c => (
                                        <option key={c.id} value={c.id}>{c.name} ({c.code})</option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">عضو هيئة التدريس</label>
                                <select 
                                    required
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2"
                                    value={currentSession.instructorId}
                                    onChange={e => setCurrentSession({...currentSession, instructorId: e.target.value})}
                                >
                                    <option value="">اختر المدرس...</option>
                                    {instructors.map(i => (
                                        <option key={i.id} value={i.id}>{i.name} - {i.department}</option>
                                    ))}
                                </select>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
