import { Student, Course, Building, Room } from '../types';
import { MOCK_STUDENTS, MOCK_COURSES } from '../constants';

const STORAGE_KEY_STUDENTS = 'manara_sis_students';
const STORAGE_KEY_COURSES = 'manara_sis_courses';
const STORAGE_KEY_SETTINGS = 'manara_sis_settings';
const STORAGE_KEY_BUILDINGS = 'manara_sis_buildings';
const STORAGE_KEY_ROOMS = 'manara_sis_rooms';

export interface SystemSettings {
  currentSemester: string;
  academicYear: string;
  institutionName: string;
  registrationDeadline: string;
  paymentDeadline: string;
}

const DEFAULT_SETTINGS: SystemSettings = {
  currentSemester: 'خريف 2024',
  academicYear: '2024-2025',
  institutionName: 'جامعة المنارة',
  registrationDeadline: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], // 7 days from now
  paymentDeadline: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], // 14 days from now
};

const MOCK_BUILDINGS: Building[] = [
  { id: 'BLD001', name: 'مبنى كلية الهندسة', code: 'ENG-01', floors: 3, description: 'المبنى الرئيسي لكلية الهندسة' },
