const Settings: React.FC = () => {
  const [settings, setSettings] = useState<SystemSettings>({
    currentSemester: '',
    academicYear: '',
    institutionName: '',
    registrationDeadline: '',
    paymentDeadline: ''
  });
  const [saved, setSaved] = useState(false);
