const DeadlineAlerts: React.FC = () => {
    const settings = getSystemSettings();
    const now = new Date();
    const regDeadline = new Date(settings.registrationDeadline);
    const payDeadline = new Date(settings.paymentDeadline);

    const diffDays = (date: Date) => Math.ceil((date.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));

    const regDiff = diffDays(regDeadline);
    const payDiff = diffDays(payDeadline);

    if (regDiff > 14 && payDiff > 14) return null;

    return (
        <div className="mb-8 grid grid-cols-1 md:grid-cols-2 gap-4">
            {regDiff <= 14 && (
                <div className={`p-4 rounded-xl border flex items-center gap-4 ${regDiff < 3 ? 'bg-red-50 border-red-200 text-red-800' : 'bg-amber-50 border-amber-200 text-amber-800'}`}>
                    <div className={`p-2 rounded-lg ${regDiff < 3 ? 'bg-red-100' : 'bg-amber-100'}`}>
                        <Bell size={20} className="animate-bounce" />
                    </div>
                    <div>
                        <p className="text-xs font-bold uppercase opacity-60">تنبيه المواعيد النهائية</p>
                        <h4 className="font-black">باقي {regDiff} أيام على انتهاء تنزيل المواد</h4>
                    </div>
                </div>
            )}
            {payDiff <= 14 && (
                <div className={`p-4 rounded-xl border flex items-center gap-4 ${payDiff < 3 ? 'bg-red-50 border-red-200 text-red-800' : 'bg-blue-50 border-blue-200 text-blue-800'}`}>
                    <div className={`p-2 rounded-lg ${payDiff < 3 ? 'bg-red-100' : 'bg-blue-100'}`}>
                        <DollarSign size={20} />
                    </div>
                    <div>
                        <p className="text-xs font-bold uppercase opacity-60">تنبيه مالي</p>
                        <h4 className="font-black">باقي {payDiff} أيام على موعد سداد الرسوم</h4>
                    </div>
                </div>
            )}
        </div>
    );
};

