                    {recentActivity.length > 0 ? (
                        recentActivity.map((log) => (
                            <div key={log.id} className="flex gap-3 items-start pb-3 border-b border-slate-50 last:border-0 last:pb-0">
                                <div className={`mt-1 w-2 h-2 rounded-full shrink-0 ${
                                    log.type === 'danger' ? 'bg-red-500' : 
                                    log.type === 'warning' ? 'bg-yellow-500' : 'bg-blue-500'
                                }`}></div>
                                <div>
                                    <p className="text-sm font-medium text-slate-800">{log.action}</p>
                                    <p className="text-xs text-slate-500 line-clamp-1">{log.details}</p>
                                    <div className="flex items-center gap-1 mt-1 text-[10px] text-slate-400">
                                        <Clock size={10} />
                                        <span>{new Date(log.timestamp).toLocaleTimeString('ar-LY')}</span>
                                    </div>
                                </div>
                            </div>
                        ))
                    ) : (
                        <p className="text-sm text-slate-400 text-center py-4">لا يوجد نشاط مسجل</p>
                    )}
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

