import React, { useState, useEffect } from 'react';
import { getStudents, getCourses, getSystemSettings, saveStudent, getRooms } from '../services/storageService';
import { getSchedule } from '../services/scheduleService';
import { Student, Course, StudentEnrollment, Room, ClassSession } from '../types';
import { Search, Plus, Trash2, ClipboardCheck, BookOpen, AlertCircle, Save, Calendar, Info } from 'lucide-react';
import { notifySuccess, notifyError, notifyWarning } from '../services/notificationService';
import { logAction } from '../services/auditService';
import { getCurrentUser } from '../services/authService';

const Registration: React.FC = () => {
    const [students, setStudents] = useState<Student[]>([]);
    const [courses, setCourses] = useState<Course[]>([]);
    const [rooms, setRooms] = useState<Room[]>([]);
    const [schedule, setSchedule] = useState<ClassSession[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
    const settings = getSystemSettings();
    const currentUser = getCurrentUser();

    const isPastDeadline = new Date() > new Date(settings.registrationDeadline);

    useEffect(() => {
        setStudents(getStudents());
        setCourses(getCourses());
        setRooms(getRooms());
        setSchedule(getSchedule());
    }, []);

    const getCourseEnrolledCount = (courseId: string) => {
        return students.filter(s => s.enrollments?.some(e => e.courseId === courseId && e.semester === settings.currentSemester)).length;
    };

    const getCourseRoomInfo = (courseId: string) => {
        const session = schedule.find(s => s.courseId === courseId);
        if (!session) return null;
        const room = rooms.find(r => r.name === session.room);
        return { room, session };
    };

    const handleRegisterCourse = (courseId: string) => {
        if (!selectedStudent) return;

        if (isPastDeadline) {
            notifyError('لا يمكن التسجيل، انتهى الموعد النهائي المحدد لتنزيل المواد');
            return;
        }

        const alreadyRegistered = selectedStudent.enrollments?.some(e => e.courseId === courseId && e.semester === settings.currentSemester);
        if (alreadyRegistered) {
            notifyError('الطالب مسجل بالفعل في هذا المقرر لهذا الفصل');
            return;
        }

        // Capacity Check
        const enrolledCount = getCourseEnrolledCount(courseId);
        const roomInfo = getCourseRoomInfo(courseId);
        if (roomInfo && roomInfo.room && enrolledCount >= roomInfo.room.capacity) {
            notifyError(`القاعة المحجوزة للمقرر (${roomInfo.room.name}) وصلت لسعتها القصوى (${roomInfo.room.capacity})`);
            return;
        }

        const newEnrollment: StudentEnrollment = {
            courseId,
            semester: settings.currentSemester,
            status: 'REGISTERED'
        };

        const updatedStudent = {
            ...selectedStudent,
            enrollments: [...(selectedStudent.enrollments || []), newEnrollment]
        };

        saveStudent(updatedStudent);
        setSelectedStudent(updatedStudent);
        setStudents(getStudents());
        notifySuccess('تم تسجيل المقرر بنجاح');
        logAction('تسجيل مقرر', `تم تسجيل ${courseId} للطالب ${selectedStudent.name}`, 'info', currentUser?.name);
    };

    const handleRemoveEnrollment = (courseId: string) => {
        if (!selectedStudent) return;
        if (isPastDeadline) {
            notifyError('فترة حذف وإضافة المواد قد انتهت');
            return;
        }

        const updatedEnrollments = selectedStudent.enrollments?.filter(e => !(e.courseId === courseId && e.semester === settings.currentSemester));

        const updatedStudent = {
            ...selectedStudent,
            enrollments: updatedEnrollments
        };

        saveStudent(updatedStudent);
        setSelectedStudent(updatedStudent);
        setStudents(getStudents());
        notifySuccess('تم حذف التسجيل');
    };

    const filteredStudents = students.filter(s => 
        s.name.includes(searchTerm) || s.id.includes(searchTerm)
    );

    return (
        <div className="p-8 h-screen flex flex-col">
            <div className="mb-8 flex justify-between items-start">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                        <ClipboardCheck className="text-blue-600" />
                        تنزيل المواد (التسجيل الفصلي)
                    </h2>
                    <p className="text-slate-500 mt-1">إدارة تسجيل الطلاب في المقررات للفصل الحالي: {settings.currentSemester}</p>
                </div>
                <div className={`p-4 rounded-xl border flex items-center gap-3 ${isPastDeadline ? 'bg-red-50 border-red-100 text-red-700' : 'bg-green-50 border-green-100 text-green-700'}`}>
                    <Calendar size={20} />
                    <div>
                        <p className="text-[10px] font-bold uppercase opacity-60">الموعد النهائي</p>
                        <p className="font-bold">{settings.registrationDeadline}</p>
                    </div>
                    {isPastDeadline && <span className="bg-red-600 text-white px-2 py-0.5 rounded text-[10px] font-black">مغلق</span>}
                </div>
            </div>

            <div className="flex gap-6 flex-1 overflow-hidden">
                <div className="w-1/3 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col">
                    <div className="p-4 border-b border-slate-200">
                        <div className="relative">
                            <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                            <input 
                                type="text" 
                                placeholder="بحث عن طالب..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full pr-10 pl-4 py-2 rounded-lg border border-slate-300 focus:ring-2 focus:ring-blue-500 outline-none"
                            />
                        </div>
                    </div>
                    <div className="flex-1 overflow-auto">
                        {filteredStudents.map(s => (
                            <div 
                                key={s.id}
                                onClick={() => setSelectedStudent(s)}
                                className={`p-4 border-b cursor-pointer transition-colors ${selectedStudent?.id === s.id ? 'bg-blue-50' : 'hover:bg-slate-50'}`}
                            >
                                <p className="font-bold text-slate-800">{s.name}</p>
                                <p className="text-xs text-slate-500 font-mono">{s.id} | {s.department}</p>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="w-2/3 flex flex-col gap-6 overflow-hidden">
                    {selectedStudent ? (
                        <>
                            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                                <div className="flex justify-between items-center mb-4">
                                    <h3 className="font-bold text-lg text-slate-800">المقررات المسجلة حالياً</h3>
                                    <span className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs font-bold">
                                        {selectedStudent.enrollments?.filter(e => e.semester === settings.currentSemester).length || 0} مواد
                                    </span>
                                </div>
                                <div className="space-y-2">
                                    {selectedStudent.enrollments?.filter(e => e.semester === settings.currentSemester).map(e => {
                                        const course = courses.find(c => c.id === e.courseId);
                                        return (
                                            <div key={e.courseId} className="flex justify-between items-center p-3 bg-slate-50 rounded-lg border border-slate-100">
                                                <div className="flex items-center gap-3">
                                                    <div className="bg-white p-2 rounded border"><BookOpen size={16} className="text-blue-500"/></div>
                                                    <div>
                                                        <p className="text-sm font-bold">{course?.name || e.courseId}</p>
                                                        <p className="text-[10px] text-slate-400 font-mono">{e.courseId}</p>
                                                    </div>
                                                </div>
                                                <button 
                                                    onClick={() => handleRemoveEnrollment(e.courseId)}
                                                    disabled={isPastDeadline}
                                                    className={`p-1.5 rounded-md transition-colors ${isPastDeadline ? 'text-slate-300 cursor-not-allowed' : 'text-red-400 hover:text-red-600 hover:bg-red-50'}`}
                                                >
                                                    <Trash2 size={16} />
                                                </button>
                                            </div>
                                        );
                                    })}
                                    {(!selectedStudent.enrollments || selectedStudent.enrollments.filter(e => e.semester === settings.currentSemester).length === 0) && (
                                        <p className="text-center py-4 text-slate-400 text-sm italic">لا يوجد مواد مسجلة لهذا الفصل</p>
                                    )}
                                </div>
                            </div>

                            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex-1 flex flex-col overflow-hidden">
                                <h3 className="font-bold text-lg text-slate-800 mb-4">المقررات المتاحة للتسجيل</h3>
                                <div className="flex-1 overflow-auto space-y-2">
                                    {courses.map(course => {
                                        const enrolledCount = getCourseEnrolledCount(course.id);
                                        const roomInfo = getCourseRoomInfo(course.id);
                                        const isFull = roomInfo && roomInfo.room && enrolledCount >= roomInfo.room.capacity;

                                        return (
                                            <div key={course.id} className="flex justify-between items-center p-3 border border-slate-100 rounded-lg hover:border-blue-200 transition-colors group">
                                                <div className="flex-1">
                                                    <div className="flex items-center gap-2">
                                                        <p className="text-sm font-bold text-slate-700">{course.name}</p>
                                                        {isFull && <span className="bg-red-100 text-red-600 text-[10px] px-1.5 py-0.5 rounded font-bold">مكتمل</span>}
                                                    </div>
                                                    <div className="flex items-center gap-4 mt-1">
                                                        <span className="text-xs text-slate-400 font-mono">{course.code}</span>
                                                        <span className="text-xs text-slate-400 border-r pr-4">{course.credits} وحدات</span>
                                                        {roomInfo && (
                                                            <span className={`text-[10px] flex items-center gap-1 font-bold ${isFull ? 'text-red-500' : 'text-slate-400'}`}>
                                                                <Users size={12} /> {enrolledCount} / {roomInfo.room?.capacity || '∞'}
                                                            </span>
                                                        )}
                                                    </div>
                                                </div>
                                                <button 
                                                    onClick={() => handleRegisterCourse(course.id)}
                                                    disabled={isPastDeadline || isFull}
                                                    className={`px-4 py-2 rounded-lg text-xs font-bold flex items-center gap-1 transition-all ${isPastDeadline || isFull ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-sm shadow-blue-200'}`}
                                                >
                                                    <Plus size={14} /> تسجيل
                                                </button>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        </>
                    ) : (
                        <div className="flex-1 bg-white rounded-xl border border-slate-200 border-dashed flex flex-col items-center justify-center text-slate-400">
                            <ClipboardCheck size={64} className="mb-4 opacity-20" />
                            <p>اختر طالباً من القائمة للبدء في عملية التسجيل</p>
                            <div className="mt-4 bg-slate-50 p-4 rounded-xl text-xs flex items-start gap-2 max-w-sm text-slate-500">
                                <Info size={16} className="shrink-0 text-blue-500" />
                                <p>يتم التحقق تلقائياً من توفر السعة الاستيعابية في القاعات المخصصة للمقررات قبل السماح بالتسجيل.</p>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

