export const getSystemSettings = (): SystemSettings => {
  const data = localStorage.getItem(STORAGE_KEY_SETTINGS);
  if (!data) {
    localStorage.setItem(STORAGE_KEY_SETTINGS, JSON.stringify(DEFAULT_SETTINGS));
    return DEFAULT_SETTINGS;
  }
  const parsed = JSON.parse(data);
  if (!parsed.registrationDeadline) {
      return { ...DEFAULT_SETTINGS, ...parsed };
  }
  return parsed;
};

export const saveSystemSettings = (settings: SystemSettings): void => {
  localStorage.setItem(STORAGE_KEY_SETTINGS, JSON.stringify(settings));
};

export const exportSystemData = (): string => {
  const data = {
    students: getStudents(),
    courses: getCourses(),
    settings: getSystemSettings(),
    buildings: getBuildings(),
    rooms: getRooms(),
    branches: getBranches(),
    colleges: getColleges(),
    departments: getDepartments(),
    programs: getAcademicPrograms(),
    sections: getSections(),
    timestamp: new Date().toISOString(),
    version: '3.1'
  };
  return JSON.stringify(data, null, 2);
};

export const importSystemData = (jsonString: string): boolean => {
  try {
    const data = JSON.parse(jsonString);
    if (!data.students || !data.courses || !data.settings) throw new Error("Invalid data");
    localStorage.setItem(STORAGE_KEY_STUDENTS, JSON.stringify(data.students));
    localStorage.setItem(STORAGE_KEY_COURSES, JSON.stringify(data.courses));
    localStorage.setItem(STORAGE_KEY_SETTINGS, JSON.stringify(data.settings));
    if (data.buildings) localStorage.setItem(STORAGE_KEY_BUILDINGS, JSON.stringify(data.buildings));
    if (data.rooms) localStorage.setItem(STORAGE_KEY_ROOMS, JSON.stringify(data.rooms));
    if (data.branches) localStorage.setItem(STORAGE_KEY_BRANCHES, JSON.stringify(data.branches));
    if (data.colleges) localStorage.setItem(STORAGE_KEY_COLLEGES, JSON.stringify(data.colleges));
    if (data.departments) localStorage.setItem(STORAGE_KEY_DEPTS, JSON.stringify(data.departments));
    if (data.programs) localStorage.setItem(STORAGE_KEY_PROGRAMS, JSON.stringify(data.programs));
    if (data.sections) localStorage.setItem(STORAGE_KEY_SECTIONS, JSON.stringify(data.sections));
    return true;
  } catch (error) {
    console.error(error);
    return false;
  }
};

import React, { useState, useEffect } from 'react';
import { 
  getBranches, saveBranch, 
  getColleges, saveCollege, 
  getDepartments, saveDepartment, 
  getAcademicPrograms, saveAcademicProgram, 
  getSections, saveSection 
} from '../services/storageService';
import { Branch, College, Department, AcademicProgram, Section, ProgramType } from '../types';
import { 
  Network, Landmark, Building2, BookOpen, Layers, 
  Plus, Edit2, Save, X, ChevronRight, MapPin, User, Search
} from 'lucide-react';
import { notifySuccess } from '../services/notificationService';

type Tab = 'branches' | 'colleges' | 'depts' | 'programs' | 'sections';

const UniversityManagement: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('branches');
  const [branches, setBranches] = useState<Branch[]>([]);
  const [colleges, setColleges] = useState<College[]>([]);
  const [depts, setDepts] = useState<Department[]>([]);
  const [programs, setPrograms] = useState<AcademicProgram[]>([]);
  const [sections, setSections] = useState<Section[]>([]);

  const [showModal, setShowModal] = useState(false);
  const [editItem, setEditItem] = useState<any>(null);

  useEffect(() => {
    setBranches(getBranches());
    setColleges(getColleges());
    setDepts(getDepartments());
    setPrograms(getAcademicPrograms());
    setSections(getSections());
  }, []);

  const refresh = () => {
    setBranches(getBranches());
    setColleges(getColleges());
    setDepts(getDepartments());
    setPrograms(getAcademicPrograms());
    setSections(getSections());
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);

    if (activeTab === 'branches') {
      saveBranch({ 
        id: editItem?.id || `BR-${Date.now()}`, 
        name: formData.get('name') as string,
        location: formData.get('location') as string 
      });
    } else if (activeTab === 'colleges') {
      saveCollege({
        id: editItem?.id || `COL-${Date.now()}`,
        branchId: formData.get('branchId') as string,
        name: formData.get('name') as string,
        deanName: formData.get('deanName') as string
      });
    } else if (activeTab === 'depts') {
      saveDepartment({
        id: editItem?.id || `DEPT-${Date.now()}`,
        collegeId: formData.get('collegeId') as string,
        name: formData.get('name') as string,
        headName: formData.get('headName') as string
      });
    } else if (activeTab === 'programs') {
      saveAcademicProgram({
        id: editItem?.id || `PRG-${Date.now()}`,
        deptId: formData.get('deptId') as string,
        name: formData.get('name') as string,
        type: formData.get('type') as ProgramType,
        durationSemesters: parseInt(formData.get('duration') as string)
      });
    } else if (activeTab === 'sections') {
      saveSection({
        id: editItem?.id || `SEC-${Date.now()}`,
        programId: formData.get('programId') as string,
        name: formData.get('name') as string
      });
    }

    notifySuccess('تم حفظ البيانات بنجاح');
    setShowModal(false);
    refresh();
  };

  return (
    <div className="p-8">
      <div className="mb-8">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <Network className="text-blue-600" />
          إدارة الهيكل الأكاديمي
        </h2>
        <p className="text-slate-500 mt-1">تنظيم الفروع، الكليات، الأقسام العلمية، والشعب</p>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col min-h-[600px]">
        {/* Tabs */}
        <div className="flex border-b border-slate-200 bg-slate-50 px-6 pt-4 gap-4 overflow-x-auto no-scrollbar">
          <button onClick={() => setActiveTab('branches')} className={`pb-4 px-4 text-sm font-bold border-b-2 flex items-center gap-2 ${activeTab === 'branches' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500'}`}>
            <MapPin size={18} /> الفروع
          </button>
          <button onClick={() => setActiveTab('colleges')} className={`pb-4 px-4 text-sm font-bold border-b-2 flex items-center gap-2 ${activeTab === 'colleges' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500'}`}>
            <Landmark size={18} /> الكليات
          </button>
          <button onClick={() => setActiveTab('depts')} className={`pb-4 px-4 text-sm font-bold border-b-2 flex items-center gap-2 ${activeTab === 'depts' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500'}`}>
            <Building2 size={18} /> الأقسام
          </button>
          <button onClick={() => setActiveTab('programs')} className={`pb-4 px-4 text-sm font-bold border-b-2 flex items-center gap-2 ${activeTab === 'programs' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500'}`}>
            <BookOpen size={18} /> البرامج العلمية
          </button>
          <button onClick={() => setActiveTab('sections')} className={`pb-4 px-4 text-sm font-bold border-b-2 flex items-center gap-2 ${activeTab === 'sections' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500'}`}>
            <Layers size={18} /> الشُعب
          </button>
        </div>

        <div className="p-6 flex-1">
          <div className="flex justify-between items-center mb-6">
            <h3 className="font-bold text-slate-700">سجل الإدخالات ({
              activeTab === 'branches' ? branches.length : 
              activeTab === 'colleges' ? colleges.length : 
              activeTab === 'depts' ? depts.length : 
              activeTab === 'programs' ? programs.length : sections.length
            })</h3>
            <button onClick={() => { setEditItem(null); setShowModal(true); }} className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700 shadow-sm transition-all">
              <Plus size={18} /> إضـافة
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in slide-in-from-bottom-2">
            {activeTab === 'branches' && branches.map(item => (
              <Card key={item.id} title={item.name} sub={item.location} icon={MapPin} onEdit={() => { setEditItem(item); setShowModal(true); }} />
            ))}
            {activeTab === 'colleges' && colleges.map(item => (
              <Card key={item.id} title={item.name} sub={`العميد: ${item.deanName || '---'}`} icon={Landmark} onEdit={() => { setEditItem(item); setShowModal(true); }} />
            ))}
            {activeTab === 'depts' && depts.map(item => (
              <Card key={item.id} title={item.name} sub={`رئيس القسم: ${item.headName || '---'}`} icon={Building2} onEdit={() => { setEditItem(item); setShowModal(true); }} />
            ))}
            {activeTab === 'programs' && programs.map(item => (
              <Card key={item.id} title={item.name} sub={`النوع: ${item.type} | الفصول: ${item.durationSemesters}`} icon={BookOpen} onEdit={() => { setEditItem(item); setShowModal(true); }} />
            ))}
            {activeTab === 'sections' && sections.map(item => (
              <Card key={item.id} title={item.name} sub="تخصص دقيق" icon={Layers} onEdit={() => { setEditItem(item); setShowModal(true); }} />
            ))}
          </div>
        </div>
      </div>

      {/* Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden">
            <div className="bg-slate-900 text-white p-5 flex justify-between items-center">
              <h3 className="font-bold">إضافة / تعديل بيانات</h3>
              <button onClick={() => setShowModal(false)}><X /></button>
            </div>
            <form onSubmit={handleSave} className="p-6 space-y-4">
              {activeTab === 'branches' && (
                <>
                  <Input label="اسم الفرع" name="name" defaultValue={editItem?.name} />
                  <Input label="الموقع" name="location" defaultValue={editItem?.location} />
                </>
              )}
              {activeTab === 'colleges' && (
                <>
                  <Select label="الفرع" name="branchId" defaultValue={editItem?.branchId}>
                    {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
                  </Select>
                  <Input label="اسم الكلية" name="name" defaultValue={editItem?.name} />
                  <Input label="اسم العميد" name="deanName" defaultValue={editItem?.deanName} />
                </>
              )}
              {activeTab === 'depts' && (
                <>
                  <Select label="الكلية" name="collegeId" defaultValue={editItem?.collegeId}>
                    {colleges.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </Select>
                  <Input label="اسم القسم" name="name" defaultValue={editItem?.name} />
                  <Input label="رئيس القسم" name="headName" defaultValue={editItem?.headName} />
                </>
              )}
              {activeTab === 'programs' && (
                <>
                  <Select label="القسم التابع له" name="deptId" defaultValue={editItem?.deptId}>
                    {depts.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                  </Select>
                  <Input label="اسم البرنامج" name="name" defaultValue={editItem?.name} />
                  <Select label="نوع البرنامج" name="type" defaultValue={editItem?.type}>
                    <option value={ProgramType.UNDERGRADUATE}>جامعي</option>
                    <option value={ProgramType.POSTGRADUATE}>دراسات عليا</option>
                  </Select>
                  <Input label="عدد الفصول الدراسية" name="duration" type="number" defaultValue={editItem?.durationSemesters} />
                </>
              )}
              {activeTab === 'sections' && (
                <>
                  <Select label="البرنامج العلمي" name="programId" defaultValue={editItem?.programId}>
                    {programs.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                  </Select>
                  <Input label="اسم الشعبة" name="name" defaultValue={editItem?.name} />
                </>
              )}
              <div className="pt-4 flex justify-end gap-2">
                <button type="button" onClick={() => setShowModal(false)} className="px-4 py-2 text-slate-500">إلغاء</button>
                <button type="submit" className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold">حفظ</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const Card = ({ title, sub, icon: Icon, onEdit }: any) => (
