import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import StudentsList from './components/StudentsList';
import UniversityManagement from './components/UniversityManagement';
import Registration from './components/Registration';
import Academics from './components/Academics';
import Facilities from './components/Facilities';
import Graduates from './components/Graduates';
import Reports from './components/Reports';
import Settings from './components/Settings';
import Financials from './components/Financials';
import ServiceRequests from './components/ServiceRequests';
import Communications from './components/Communications';
import Faculty from './components/Faculty';
import Attendance from './components/Attendance';
import Schedule from './components/Schedule';
import ExamSchedule from './components/ExamSchedule';
import RolesManagement from './components/RolesManagement';
import Login from './components/Login';
import ToastContainer from './components/ToastContainer';
import { Book, FileText, Download, Lock } from 'lucide-react';
import { LIBYAN_REGULATION_501_SUMMARY } from './constants';
import { AuthUser, Permission } from './types';
import { getCurrentUser, logout, getAccessibleTabs, hasPermission } from './services/authService';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<AuthUser | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');

  useEffect(() => {
    const user = getCurrentUser();
    if (user) {
        setCurrentUser(user);
    }
  }, []);

  const handleLogin = (user: AuthUser) => {
      setCurrentUser(user);
      setActiveTab('dashboard');
  };

  const handleLogout = () => {
      logout();
      setCurrentUser(null);
  };

  const renderContent = () => {
    if (currentUser) {
        const allowedTabs = getAccessibleTabs(currentUser);
        const canCommunicate = hasPermission(currentUser, Permission.COMMUNICATIONS_MANAGE);
        const canManageFacilities = hasPermission(currentUser, Permission.FACILITIES_MANAGE);
        const canManageOrg = hasPermission(currentUser, Permission.ORGANIZATION_MANAGE);

        if (!allowedTabs.includes(activeTab) && 
            activeTab !== 'registration' && 
            !(activeTab === 'communications' && canCommunicate) &&
            !(activeTab === 'facilities' && canManageFacilities) &&
            !(activeTab === 'organization' && canManageOrg)) {
            return (
                <div className="flex flex-col items-center justify-center h-[80vh] text-slate-400">
                    <div className="bg-red-50 p-6 rounded-full mb-4">
                        <Lock size={48} className="text-red-500" />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-800 mb-2">الدخول غير مصرح به</h2>
                    <p>ليس لديك الصلاحيات الكافية للوصول إلى هذه الصفحة.</p>
                </div>
            );
        }
    }

    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'students': return <StudentsList />;
      case 'organization': return <UniversityManagement />;
      case 'registration': return <Registration />;
      case 'academics': return <Academics />;
      case 'facilities': return <Facilities />;
      case 'schedule': return <Schedule />;
      case 'exams': return <ExamSchedule />;
      case 'faculty': return <Faculty />;
      case 'attendance': return <Attendance />;
      case 'financials': return <Financials />;
      case 'requests': return <ServiceRequests />;
      case 'communications': return <Communications />;
      case 'reports': return <Reports />;
      case 'graduates': return <Graduates />;
      case 'roles': return <RolesManagement />;
      case 'settings': return <Settings />;
      case 'regulations':
        return (
          <div className="p-8 max-w-4xl mx-auto">
            <div className="mb-8">
              <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                <FileText className="text-blue-600" />
                لائحة التعليم العالي 501
              </h2>
            </div>
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
              <div className="bg-slate-50 p-4 border-b flex justify-between items-center">
                <span className="font-bold text-slate-700">نصوص اللائحة</span>
                <button className="text-blue-600 text-sm hover:underline flex items-center gap-1">
                  <Download size={16} /> تحميل PDF
                </button>
              </div>
              <div className="p-8">
                <div className="prose prose-slate max-w-none font-sans whitespace-pre-line leading-loose text-slate-700">
                  {LIBYAN_REGULATION_501_SUMMARY}
                </div>
              </div>
            </div>
          </div>
        );
      default:
        return <div className="p-8 text-center text-slate-400">قيد التطوير</div>;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="flex flex-row min-h-screen bg-slate-50 font-sans" dir="rtl">
        <ToastContainer />
        <div className="flex flex-col w-64 bg-slate-900 text-white shadow-xl print:hidden h-screen sticky top-0">
             <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} currentUser={currentUser} />
             <div className="p-4 border-t border-slate-700 mt-auto">
                <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 text-slate-300 hover:text-red-400 hover:bg-slate-800 rounded-lg transition-colors">
                    <span className="font-medium">تسجيل الخروج</span>
                </button>
             </div>
