export const exportSystemData = (): string => {
  const data = {
    students: getStudents(),
    courses: getCourses(),
    settings: getSystemSettings(),
    buildings: getBuildings(),
    rooms: getRooms(),
    branches: getBranches(),
    colleges: getColleges(),
    departments: getDepartments(),
    programs: getAcademicPrograms(),
    sections: getSections(),
    staff: getStaff(),
    timestamp: new Date().toISOString(),
    version: '3.2'
  };
  return JSON.stringify(data, null, 2);
};

export const importSystemData = (jsonString: string): boolean => {
  try {
    const data = JSON.parse(jsonString);
    if (!data.students || !data.courses || !data.settings) throw new Error("Invalid data");
    localStorage.setItem(STORAGE_KEY_STUDENTS, JSON.stringify(data.students));
    localStorage.setItem(STORAGE_KEY_COURSES, JSON.stringify(data.courses));
    localStorage.setItem(STORAGE_KEY_SETTINGS, JSON.stringify(data.settings));
    if (data.buildings) localStorage.setItem(STORAGE_KEY_BUILDINGS, JSON.stringify(data.buildings));
    if (data.rooms) localStorage.setItem(STORAGE_KEY_ROOMS, JSON.stringify(data.rooms));
    if (data.branches) localStorage.setItem(STORAGE_KEY_BRANCHES, JSON.stringify(data.branches));
    if (data.colleges) localStorage.setItem(STORAGE_KEY_COLLEGES, JSON.stringify(data.colleges));
    if (data.departments) localStorage.setItem(STORAGE_KEY_DEPTS, JSON.stringify(data.departments));
    if (data.programs) localStorage.setItem(STORAGE_KEY_PROGRAMS, JSON.stringify(data.programs));
    if (data.sections) localStorage.setItem(STORAGE_KEY_SECTIONS, JSON.stringify(data.sections));
    if (data.staff) localStorage.setItem(STORAGE_KEY_STAFF, JSON.stringify(data.staff));
    return true;
  } catch (error) {
    console.error(error);
    return false;
  }
};

import React, { useState, useEffect } from 'react';
import { 
  getStaff, saveStaffMember, deleteStaffMember,
  getBranches, getColleges, getDepartments 
} from '../services/storageService';
import { StaffMember, StaffType, Branch, College, Department, Permission } from '../types';
import { 
  Users, Plus, Edit2, Trash2, Mail, Phone, MapPin, 
  Briefcase, Search, X, Save, Shield, UserCircle, 
  GraduationCap, Building2, UserCheck, Filter
} from 'lucide-react';
import { notifySuccess, notifyInfo, notifyError } from '../services/notificationService';
import { getCurrentUser, hasPermission } from '../services/authService';

const StaffManagement: React.FC = () => {
  const [staff, setStaff] = useState<StaffMember[]>([]);
  const [branches, setBranches] = useState<Branch[]>([]);
  const [colleges, setColleges] = useState<College[]>([]);
  const [depts, setDepts] = useState<Department[]>([]);

  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<string>('all');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);

  const [currentStaff, setCurrentStaff] = useState<Partial<StaffMember>>({
    type: 'ACADEMIC',
    status: 'ACTIVE',
    joinDate: new Date().toISOString().split('T')[0]
  });

  const currentUser = getCurrentUser();
  const canManage = hasPermission(currentUser, Permission.STAFF_MANAGE);

  useEffect(() => {
    refresh();
  }, []);

  const refresh = () => {
    setStaff(getStaff());
    setBranches(getBranches());
    setColleges(getColleges());
    setDepts(getDepartments());
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentStaff.name || !currentStaff.nationalId || !currentStaff.branchId) {
      notifyError('يرجى ملء كافة الحقول الإجبارية');
      return;
    }

    const member: StaffMember = {
      id: currentStaff.id || `STF-${Date.now()}`,
      name: currentStaff.name!,
      nationalId: currentStaff.nationalId!,
      type: currentStaff.type as StaffType,
      degree: currentStaff.degree as any,
      email: currentStaff.email || '',
      phone: currentStaff.phone || '',
      branchId: currentStaff.branchId!,
      collegeId: currentStaff.collegeId,
      deptId: currentStaff.deptId,
      position: currentStaff.position!,
      status: currentStaff.status as any || 'ACTIVE',
      joinDate: currentStaff.joinDate || new Date().toISOString().split('T')[0],
      specialization: currentStaff.specialization
    };

    saveStaffMember(member);
    refresh();
    notifySuccess(isEditMode ? 'تم تحديث بيانات الموظف' : 'تم إضافة الموظف بنجاح');
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => {
    if (!canManage) return;
    if (confirm('هل أنت متأكد من حذف هذا الموظف؟')) {
      deleteStaffMember(id);
      refresh();
      notifyInfo('تم حذف الموظف');
    }
  };

  const filteredStaff = staff.filter(s => {
    const matchesSearch = s.name.includes(searchTerm) || s.position.includes(searchTerm);
    const matchesType = filterType === 'all' || s.type === filterType;
    return matchesSearch && matchesType;
  });

  return (
    <div className="p-8">
      <div className="mb-8 flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <Users className="text-blue-600" />
            إدارة الموارد البشرية والكوادر
          </h2>
          <p className="text-slate-500 mt-1">إدارة أعضاء هيئة التدريس والموظفين الإداريين والفنيين</p>
        </div>
        {canManage && (
          <button 
            onClick={() => {
              setIsEditMode(false);
              setCurrentStaff({ type: 'ACADEMIC', status: 'ACTIVE', joinDate: new Date().toISOString().split('T')[0] });
              setIsModalOpen(true);
            }}
            className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700 shadow-sm transition-all"
          >
            <Plus size={20} />
            إضافة موظف/محاضر
          </button>
        )}
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden min-h-[600px] flex flex-col">
        <div className="p-4 border-b border-slate-200 bg-slate-50 flex flex-col md:flex-row gap-4 items-center justify-between">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="بحث بالاسم أو المسمى الوظيفي..."
              className="w-full pr-10 pl-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex gap-2">
            <button onClick={() => setFilterType('all')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${filterType === 'all' ? 'bg-blue-600 text-white' : 'bg-white border text-slate-500'}`}>الكل</button>
            <button onClick={() => setFilterType('ACADEMIC')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${filterType === 'ACADEMIC' ? 'bg-indigo-600 text-white' : 'bg-white border text-slate-500'}`}>هيئة التدريس</button>
            <button onClick={() => setFilterType('ADMINISTRATIVE')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${filterType === 'ADMINISTRATIVE' ? 'bg-teal-600 text-white' : 'bg-white border text-slate-500'}`}>الموظفون</button>
          </div>
        </div>

        <div className="p-6 grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 animate-in fade-in slide-in-from-bottom-2">
          {filteredStaff.map(member => (
            <div key={member.id} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-lg transition-all group">
              <div className={`h-2 ${member.type === 'ACADEMIC' ? 'bg-indigo-500' : 'bg-teal-500'}`}></div>
              <div className="p-6">
                <div className="flex justify-between items-start mb-4">
                  <div className={`p-3 rounded-2xl ${member.type === 'ACADEMIC' ? 'bg-indigo-50 text-indigo-600' : 'bg-teal-50 text-teal-600'}`}>
                    {member.type === 'ACADEMIC' ? <GraduationCap size={24} /> : <Briefcase size={24} />}
                  </div>
                  {canManage && (
                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => { setCurrentStaff(member); setIsEditMode(true); setIsModalOpen(true); }} className="p-1.5 hover:bg-slate-100 rounded text-blue-600"><Edit2 size={16}/></button>
                      <button onClick={() => handleDelete(member.id)} className="p-1.5 hover:bg-slate-100 rounded text-red-600"><Trash2 size={16}/></button>
                    </div>
                  )}
                </div>

                <h3 className="font-bold text-lg text-slate-800 mb-1">{member.name}</h3>
                <p className="text-sm font-bold text-blue-600 mb-4">{member.position}</p>

                <div className="space-y-2 text-sm text-slate-500">
                  <div className="flex items-center gap-2"><MapPin size={14} className="text-slate-300"/> <span>{branches.find(b => b.id === member.branchId)?.name}</span></div>
                  <div className="flex items-center gap-2"><Mail size={14} className="text-slate-300"/> <span className="font-mono text-xs">{member.email}</span></div>
                  <div className="flex items-center gap-2"><Phone size={14} className="text-slate-300"/> <span className="font-mono text-xs">{member.phone}</span></div>
                </div>

                <div className="mt-6 flex justify-between items-center pt-4 border-t border-slate-50">
                  <span className={`text-[10px] font-black px-2 py-0.5 rounded-full ${member.status === 'ACTIVE' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                    {member.status === 'ACTIVE' ? 'على رأس العمل' : 'إجازة / غياب'}
                  </span>
                  <span className="text-[10px] text-slate-300 font-mono">{member.id}</span>
                </div>
              </div>
            </div>
          ))}
          {filteredStaff.length === 0 && (
            <div className="col-span-full py-20 text-center text-slate-400">
              <Users size={48} className="mx-auto mb-4 opacity-20" />
              <p>لا يوجد سجلات لموظفين أو أعضاء هيئة تدريس حالياً</p>
            </div>
          )}
        </div>
      </div>

      {/* Staff Modal */}
