import { AuthUser, UserRole, Permission } from '../types';
import { getRoleById } from './rbacService';

const STORAGE_KEY_SESSION = 'manara_session_user';

// Mock Users for Simulation
const MOCK_USERS: AuthUser[] = [
    { id: '1', username: 'admin', name: 'المسؤول العام', role: UserRole.ADMIN },
    { id: '2', username: 'registrar', name: 'موظف التسجيل', role: UserRole.REGISTRAR },
    { id: '3', username: 'finance', name: 'الموظف المالي', role: UserRole.FINANCE },
    { id: '4', username: 'faculty', name: 'عضو هيئة تدريس', role: UserRole.FACULTY },
];

export const login = async (username: string, password: string): Promise<AuthUser> => {
    // Simulate API delay
    await new Promise(resolve => setTimeout(resolve, 600));

    if (password === username) {
        const user = MOCK_USERS.find(u => u.username === username);
        if (user) {
            localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(user));
            return user;
        }
    }
    throw new Error('بيانات الدخول غير صحيحة');
};

export const logout = () => {
    localStorage.removeItem(STORAGE_KEY_SESSION);
};

export const getCurrentUser = (): AuthUser | null => {
    const data = localStorage.getItem(STORAGE_KEY_SESSION);
    if (data) {
        try {
            return JSON.parse(data);
        } catch (e) {
            return null;
        }
    }
    return null;
};

export const hasPermission = (user: AuthUser | null, required: Permission | Permission[]): boolean => {
    if (!user) return false;

    const roleDef = getRoleById(user.role);
    if (!roleDef) return false;

    if (user.role === UserRole.ADMIN) return true;

    const permissions = Array.isArray(required) ? required : [required];
    return permissions.every(p => roleDef.permissions.includes(p));
};

export const getAccessibleTabs = (user: AuthUser | null): string[] => {
    if (!user) return ['dashboard', 'regulations'];

    const tabs: { id: string, perms: Permission[] }[] = [
        { id: 'dashboard', perms: [] },
        { id: 'students', perms: [Permission.STUDENTS_VIEW] },
        { id: 'organization', perms: [Permission.ORGANIZATION_MANAGE] },
        { id: 'academics', perms: [Permission.ACADEMICS_MANAGE] },
        { id: 'facilities', perms: [Permission.FACILITIES_MANAGE] },
        { id: 'schedule', perms: [Permission.ACADEMICS_MANAGE] },
        { id: 'exams', perms: [Permission.ACADEMICS_MANAGE] },
        { id: 'staff', perms: [Permission.STAFF_MANAGE, Permission.FACULTY_MANAGE] },
        { id: 'attendance', perms: [Permission.ATTENDANCE_MANAGE] },
        { id: 'financials', perms: [Permission.FINANCE_VIEW] },
        { id: 'requests', perms: [Permission.REQUESTS_MANAGE] },
        { id: 'reports', perms: [Permission.REPORTS_VIEW] },
        { id: 'graduates', perms: [Permission.STUDENTS_VIEW] },
        { id: 'roles', perms: [Permission.ROLES_MANAGE] },
        { id: 'regulations', perms: [] },
        { id: 'settings', perms: [Permission.SETTINGS_MANAGE] },
    ];

    return tabs
        .filter(tab => tab.perms.length === 0 || hasPermission(user, tab.perms))
        .map(tab => tab.id);
};

import React, { useState, useEffect } from 'react';
import { 
  getBranches, saveBranch, 
  getColleges, saveCollege, 
  getDepartments, saveDepartment, 
  getAcademicPrograms, saveAcademicProgram, 
  getSections, saveSection,
  getStaff
} from '../services/storageService';
import { Branch, College, Department, AcademicProgram, Section, ProgramType, Permission, StaffMember } from '../types';
import { 
  Network, Landmark, Building2, BookOpen, Layers, 
  Plus, Edit2, Save, X, ChevronRight, ChevronDown, MapPin, User, Search, Trash2, FolderPlus,
  Users
} from 'lucide-react';
import { notifySuccess, notifyError, notifyInfo } from '../services/notificationService';
import { getCurrentUser, hasPermission } from '../services/authService';

type OrgLevel = 'branch' | 'college' | 'dept' | 'program' | 'section';

const UniversityManagement: React.FC = () => {
  const [viewMode, setViewMode] = useState<'tree' | 'cards'>('tree');
  const [activeTab, setActiveTab] = useState<OrgLevel>('branch');

  const [branches, setBranches] = useState<Branch[]>([]);
  const [colleges, setColleges] = useState<College[]>([]);
  const [depts, setDepts] = useState<Department[]>([]);
  const [programs, setPrograms] = useState<AcademicProgram[]>([]);
  const [sections, setSections] = useState<Section[]>([]);
  const [staff, setStaff] = useState<StaffMember[]>([]);

  const [showModal, setShowModal] = useState(false);
  const [editItem, setEditItem] = useState<any>(null);
  const [modalLevel, setModalLevel] = useState<OrgLevel>('branch');
  const [parentId, setParentId] = useState<string | null>(null);

  const currentUser = getCurrentUser();
  const canManage = hasPermission(currentUser, Permission.ORGANIZATION_MANAGE);

  useEffect(() => {
    refresh();
  }, []);

  const refresh = () => {
    setBranches(getBranches());
    setColleges(getColleges());
    setDepts(getDepartments());
    setPrograms(getAcademicPrograms());
    setSections(getSections());
    setStaff(getStaff());
  };

  const handleOpenAdd = (level: OrgLevel, pId: string | null = null) => {
    if (!canManage) return;
    setEditItem(null);
    setModalLevel(level);
    setParentId(pId);
    setShowModal(true);
  };

  const handleOpenEdit = (level: OrgLevel, item: any) => {
    if (!canManage) return;
    setEditItem(item);
    setModalLevel(level);
    setShowModal(true);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);

    if (modalLevel === 'branch') {
      saveBranch({ 
        id: editItem?.id || `BR-${Date.now()}`, 
        name: formData.get('name') as string,
        location: formData.get('location') as string 
      });
    } else if (modalLevel === 'college') {
      saveCollege({
        id: editItem?.id || `COL-${Date.now()}`,
        branchId: (formData.get('branchId') as string) || parentId || '',
        name: formData.get('name') as string,
        deanName: formData.get('deanName') as string
      });
    } else if (modalLevel === 'dept') {
      saveDepartment({
        id: editItem?.id || `DEPT-${Date.now()}`,
        collegeId: (formData.get('collegeId') as string) || parentId || '',
        name: formData.get('name') as string,
        headName: formData.get('headName') as string
      });
    } else if (modalLevel === 'program') {
      saveAcademicProgram({
        id: editItem?.id || `PRG-${Date.now()}`,
        deptId: (formData.get('deptId') as string) || parentId || '',
        name: formData.get('name') as string,
        type: formData.get('type') as ProgramType,
        durationSemesters: parseInt(formData.get('duration') as string)
      });
    } else if (modalLevel === 'section') {
      saveSection({
        id: editItem?.id || `SEC-${Date.now()}`,
        programId: (formData.get('programId') as string) || parentId || '',
        name: formData.get('name') as string
      });
    }

    notifySuccess('تم حفظ البيانات بنجاح');
    setShowModal(false);
    refresh();
  };

  return (
    <div className="p-8">
      <div className="mb-8 flex justify-between items-start">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <Network className="text-blue-600" />
            الهيكل التنظيمي الأكاديمي
          </h2>
          <p className="text-slate-500 mt-1">إدارة فروع الجامعة، الكليات، الأقسام، والشعب العلمية</p>
        </div>
        <div className="flex gap-2 bg-white p-1 rounded-xl border shadow-sm">
            <button 
                onClick={() => setViewMode('tree')}
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'tree' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
                العرض الشجري
            </button>
            <button 
                onClick={() => setViewMode('cards')}
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'cards' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
                عرض القوائم
            </button>
        </div>
      </div>

      {viewMode === 'tree' ? (
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 min-h-[600px] animate-in fade-in zoom-in duration-300">
            <div className="max-w-4xl mx-auto">
                <div className="flex items-center justify-between mb-8 pb-4 border-b border-slate-100">
                    <h3 className="font-bold text-slate-700 flex items-center gap-2">
                        <Layers size={20} className="text-blue-500" />
                        مستعرض التسلسل الهرمي والمنتسبين
                    </h3>
                    {canManage && (
                        <button onClick={() => handleOpenAdd('branch')} className="text-blue-600 hover:bg-blue-50 px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-2 transition-colors">
                            <Plus size={16} /> إضافة فرع جديد
                        </button>
                    )}
                </div>

                <div className="space-y-4">
                    {branches.length > 0 ? branches.map(branch => (
                        <TreeNode 
                            key={branch.id} 
                            item={branch} 
                            level="branch" 
                            canManage={canManage}
                            onAddChild={(l, p) => handleOpenAdd(l, p)}
                            onEdit={(l, i) => handleOpenEdit(l, i)}
                            childrenData={{colleges, depts, programs, sections, staff}}
                        />
                    )) : (
                        <div className="text-center py-20 text-slate-400">
                            <Network size={48} className="mx-auto mb-4 opacity-20" />
                            <p>لم يتم تعريف فروع للجامعة بعد</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
      ) : (
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col min-h-[600px] animate-in slide-in-from-bottom-4 duration-300">
          <div className="flex border-b border-slate-200 bg-slate-50 px-6 pt-4 gap-4 overflow-x-auto no-scrollbar">
            {(['branch', 'college', 'dept', 'program', 'section'] as OrgLevel[]).map(lvl => (
                <button 
                  key={lvl}
                  onClick={() => setActiveTab(lvl)} 
                  className={`pb-4 px-4 text-sm font-bold border-b-2 flex items-center gap-2 transition-all ${activeTab === lvl ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500'}`}
                >
                  {lvl === 'branch' && <MapPin size={18} />}
                  {lvl === 'college' && <Landmark size={18} />}
                  {lvl === 'dept' && <Building2 size={18} />}
                  {lvl === 'program' && <BookOpen size={18} />}
                  {lvl === 'section' && <Layers size={18} />}
                  {lvl === 'branch' ? 'الفروع' : lvl === 'college' ? 'الكليات' : lvl === 'dept' ? 'الأقسام' : lvl === 'program' ? 'البرامج' : 'الشُعب'}
                </button>
            ))}
          </div>

          <div className="p-6 flex-1">
            <div className="flex justify-between items-center mb-6">
              <h3 className="font-bold text-slate-700">سجل الإدخالات المباشرة</h3>
              {canManage && (
                <button onClick={() => handleOpenAdd(activeTab)} className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700 shadow-sm transition-all">
                  <Plus size={18} /> إضـافة
                </button>
              )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {activeTab === 'branch' && branches.map(item => (
                <DirectCard key={item.id} title={item.name} sub={item.location} icon={MapPin} onEdit={() => handleOpenEdit('branch', item)} canManage={canManage} />
              ))}
              {activeTab === 'college' && colleges.map(item => (
                <DirectCard key={item.id} title={item.name} sub={`العميد: ${item.deanName || '---'}`} icon={Landmark} onEdit={() => handleOpenEdit('college', item)} canManage={canManage} />
              ))}
              {activeTab === 'dept' && depts.map(item => (
                <DirectCard key={item.id} title={item.name} sub={`رئيس القسم: ${item.headName || '---'}`} icon={Building2} onEdit={() => handleOpenEdit('dept', item)} canManage={canManage} />
              ))}
              {activeTab === 'program' && programs.map(item => (
                <DirectCard key={item.id} title={item.name} sub={`النوع: ${item.type} | الفصول: ${item.durationSemesters}`} icon={BookOpen} onEdit={() => handleOpenEdit('program', item)} canManage={canManage} />
              ))}
              {activeTab === 'section' && sections.map(item => (
                <DirectCard key={item.id} title={item.name} sub="تخصص دقيق" icon={Layers} onEdit={() => handleOpenEdit('section', item)} canManage={canManage} />
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="bg-slate-900 text-white p-5 flex justify-between items-center">
              <h3 className="font-bold flex items-center gap-2">
                  <Edit2 size={18} />
                  {editItem ? 'تعديل البيانات' : 'إضافة مدخل جديد'}
              </h3>
              <button onClick={() => setShowModal(false)} className="hover:rotate-90 transition-transform"><X /></button>
            </div>
            <form onSubmit={handleSave} className="p-6 space-y-4">
              {modalLevel === 'branch' && (
                <>
                  <FormInput label="اسم الفرع" name="name" defaultValue={editItem?.name} />
                  <FormInput label="الموقع الجغرافي" name="location" defaultValue={editItem?.location} />
                </>
              )}
              {modalLevel === 'college' && (
                <>
                  {!parentId && (
                    <FormSelect label="الفرع التابع له" name="branchId" defaultValue={editItem?.branchId}>
                        {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
                    </FormSelect>
                  )}
                  <FormInput label="اسم الكلية" name="name" defaultValue={editItem?.name} />
                  <FormInput label="اسم العميد" name="deanName" defaultValue={editItem?.deanName} />
                </>
              )}
              {modalLevel === 'dept' && (
                <>
                  {!parentId && (
                    <FormSelect label="الكلية" name="collegeId" defaultValue={editItem?.collegeId}>
                        {colleges.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </FormSelect>
                  )}
                  <FormInput label="اسم القسم" name="name" defaultValue={editItem?.name} />
                  <FormInput label="رئيس القسم" name="headName" defaultValue={editItem?.headName} />
                </>
              )}
              {modalLevel === 'program' && (
                <>
                  {!parentId && (
                    <FormSelect label="القسم العلمي" name="deptId" defaultValue={editItem?.deptId}>
                        {depts.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                    </FormSelect>
                  )}
                  <FormInput label="اسم البرنامج" name="name" defaultValue={editItem?.name} />
                  <FormSelect label="نوع الدرجة" name="type" defaultValue={editItem?.type}>
                    <option value={ProgramType.UNDERGRADUATE}>بكالوريوس (جامعي)</option>
                    <option value={ProgramType.POSTGRADUATE}>ماجستير/دكتوراه (دراسات عليا)</option>
                  </FormSelect>
                  <FormInput label="عدد الفصول المقررة" name="duration" type="number" defaultValue={editItem?.durationSemesters} />
                </>
              )}
              {modalLevel === 'section' && (
                <>
                  {!parentId && (
                    <FormSelect label="البرنامج العلمي" name="programId" defaultValue={editItem?.programId}>
                        {programs.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                    </FormSelect>
                  )}
                  <FormInput label="اسم الشعبة / التخصص" name="name" defaultValue={editItem?.name} />
                </>
              )}
              <div className="pt-4 flex justify-end gap-3 border-t">
                <button type="button" onClick={() => setShowModal(false)} className="px-5 py-2 text-slate-500 font-bold">إلغاء</button>
                <button type="submit" className="bg-blue-600 text-white px-8 py-2 rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 transition-all">حفظ</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const TreeNode = ({ item, level, canManage, onAddChild, onEdit, childrenData }: any) => {
    const [isOpen, setIsOpen] = useState(level === 'branch');
    const [showStaff, setShowStaff] = useState(false);

    let children: any[] = [];
    let childLevel: OrgLevel | null = null;
    let Icon = MapPin;
    let label = "";

    // Filter staff belonging to this specific node
    const staffHere = childrenData.staff.filter((s: StaffMember) => {
      if (level === 'branch') return s.branchId === item.id && !s.collegeId;
      if (level === 'college') return s.collegeId === item.id && !s.deptId;
      if (level === 'dept') return s.deptId === item.id;
      return false;
    });

    if (level === 'branch') {
        children = childrenData.colleges.filter((c: any) => c.branchId === item.id);
        childLevel = 'college';
        Icon = MapPin;
        label = "فرع";
    } else if (level === 'college') {
        children = childrenData.depts.filter((d: any) => d.collegeId === item.id);
        childLevel = 'dept';
        Icon = Landmark;
        label = "كلية";
    } else if (level === 'dept') {
        children = childrenData.programs.filter((p: any) => p.deptId === item.id);
        childLevel = 'program';
        Icon = Building2;
        label = "قسم";
    } else if (level === 'program') {
        children = childrenData.sections.filter((s: any) => s.programId === item.id);
        childLevel = 'section';
        Icon = BookOpen;
        label = "برنامج";
    } else {
        Icon = Layers;
        label = "شعبة";
    }

    const hasChildren = children.length > 0 || staffHere.length > 0;

    return (
        <div className="border-r-2 border-slate-100 pr-4 mr-2 mb-2 select-none">
            <div className={`flex items-center justify-between p-3 rounded-xl transition-all group ${isOpen && hasChildren ? 'bg-slate-50' : 'hover:bg-slate-50'}`}>
                <div className="flex items-center gap-3">
                    <div onClick={() => setIsOpen(!isOpen)} className="cursor-pointer">
                        {hasChildren ? (
                            isOpen ? <ChevronDown size={18} className="text-slate-400" /> : <ChevronRight size={18} className="text-slate-400" />
                        ) : (
                            <div className="w-[18px]"></div>
                        )}
                    </div>
                    <div className={`p-2 rounded-lg ${
                        level === 'branch' ? 'bg-blue-100 text-blue-600' :
                        level === 'college' ? 'bg-indigo-100 text-indigo-600' :
                        level === 'dept' ? 'bg-teal-100 text-teal-600' :
                        level === 'program' ? 'bg-purple-100 text-purple-600' :
                        'bg-slate-100 text-slate-600'
                    }`}>
                        <Icon size={16} />
                    </div>
                    <div>
                        <span className="text-[10px] font-bold text-slate-400 block uppercase tracking-tighter leading-none mb-1">{label}</span>
                        <span className="font-bold text-slate-800 text-sm">{item.name}</span>
                        {staffHere.length > 0 && (
                          <span className="ms-2 px-1.5 py-0.5 bg-blue-50 text-blue-600 rounded text-[10px] font-black">
                            {staffHere.length} موظف/محاضر
                          </span>
                        )}
                    </div>
                </div>

                <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    {staffHere.length > 0 && (
                      <button onClick={() => setShowStaff(!showStaff)} className={`p-1.5 rounded-lg transition-colors ${showStaff ? 'bg-blue-600 text-white' : 'text-blue-600 hover:bg-blue-100'}`} title="عرض المنتسبين">
                        <Users size={16} />
                      </button>
                    )}
                    {canManage && childLevel && (
                        <button 
                            onClick={() => onAddChild(childLevel, item.id)}
                            className="p-1.5 text-blue-600 hover:bg-blue-100 rounded-lg tooltip"
                            title={`إضافة ${childLevel === 'college' ? 'كلية' : childLevel === 'dept' ? 'قسم' : childLevel === 'program' ? 'برنامج' : 'شعبة'}`}
                        >
                            <FolderPlus size={16} />
                        </button>
                    )}
                    {canManage && (
                        <button 
                            onClick={() => onEdit(level, item)}
                            className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg"
                        >
                            <Edit2 size={16} />
                        </button>
                    )}
                </div>
            </div>

            {isOpen && (
                <div className="mt-2 animate-in slide-in-from-top-1 duration-200">
                    {showStaff && staffHere.map((s: StaffMember) => (
                      <div key={s.id} className="flex items-center gap-3 p-2 ms-8 border-r border-dashed border-blue-200 mb-1 bg-blue-50/30 rounded-lg">
                        <div className="w-8 h-8 rounded-full bg-white border border-blue-100 flex items-center justify-center text-blue-600">
                          {s.type === 'ACADEMIC' ? <GraduationCap size={14}/> : <User size={14}/>}
                        </div>
                        <div>
                          <p className="text-xs font-bold text-slate-700">{s.name}</p>
                          <p className="text-[10px] text-slate-400">{s.position}</p>
                        </div>
                      </div>
                    ))}
                    {children.map(child => (
                        <TreeNode 
                            key={child.id} 
                            item={child} 
                            level={childLevel} 
                            canManage={canManage}
                            onAddChild={onAddChild}
                            onEdit={onEdit}
                            childrenData={childrenData}
                        />
                    ))}
                </div>
            )}
        </div>
    );
};

const DirectCard = ({ title, sub, icon: Icon, onEdit, canManage }: any) => (
  <div className="bg-white border border-slate-200 p-5 rounded-xl hover:shadow-md transition-all group flex items-center justify-between">
    <div className="flex items-center gap-4">
      <div className="bg-blue-50 text-blue-600 p-3 rounded-xl group-hover:bg-blue-600 group-hover:text-white transition-colors">
        <Icon size={20} />
      </div>
      <div>
        <h4 className="font-bold text-slate-800">{title}</h4>
        <p className="text-xs text-slate-400">{sub}</p>
      </div>
    </div>
    {canManage && (
        <button onClick={onEdit} className="p-2 text-slate-400 hover:text-blue-600 transition-colors opacity-0 group-hover:opacity-100">
            <Edit2 size={16} />
        </button>
    )}
  </div>
);

const FormInput = ({ label, name, defaultValue, type = "text" }: any) => (
  <div>
    <label className="block text-sm font-bold text-slate-700 mb-1">{label}</label>
    <input name={name} defaultValue={defaultValue} type={type} required className="w-full border-2 border-slate-100 bg-slate-50 rounded-xl px-4 py-2 focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none transition-all" />
  </div>
);

const FormSelect = ({ label, name, children, defaultValue }: any) => (
  <div>
    <label className="block text-sm font-bold text-slate-700 mb-1">{label}</label>
    <select name={name} defaultValue={defaultValue} className="w-full border-2 border-slate-100 bg-slate-50 rounded-xl px-4 py-2 focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none transition-all">
      {children}
    </select>
  </div>
);

export default UniversityManagement;

import React, { useState, useEffect } from 'react';
import { 
  getBranches, saveBranch, 
  getColleges, saveCollege, 
  getDepartments, saveDepartment, 
  getAcademicPrograms, saveAcademicProgram, 
  getSections, saveSection,
  getStaff
} from '../services/storageService';
import { Branch, College, Department, AcademicProgram, Section, ProgramType, Permission, StaffMember } from '../types';
import { 
  Network, Landmark, Building2, BookOpen, Layers, 
  Plus, Edit2, Save, X, ChevronRight, ChevronDown, MapPin, User, Search, Trash2, FolderPlus,
  Users, GraduationCap
} from 'lucide-react';
import { notifySuccess, notifyError, notifyInfo } from '../services/notificationService';
import { getCurrentUser, hasPermission } from '../services/authService';

type OrgLevel = 'branch' | 'college' | 'dept' | 'program' | 'section';

const UniversityManagement: React.FC = () => {
  const [viewMode, setViewMode] = useState<'tree' | 'cards'>('tree');
  const [activeTab, setActiveTab] = useState<OrgLevel>('branch');

  const [branches, setBranches] = useState<Branch[]>([]);
  const [colleges, setColleges] = useState<College[]>([]);
  const [depts, setDepts] = useState<Department[]>([]);
  const [programs, setPrograms] = useState<AcademicProgram[]>([]);
  const [sections, setSections] = useState<Section[]>([]);
  const [staff, setStaff] = useState<StaffMember[]>([]);

  const [showModal, setShowModal] = useState(false);
  const [editItem, setEditItem] = useState<any>(null);
  const [modalLevel, setModalLevel] = useState<OrgLevel>('branch');
  const [parentId, setParentId] = useState<string | null>(null);

  const currentUser = getCurrentUser();
  const canManage = hasPermission(currentUser, Permission.ORGANIZATION_MANAGE);

  useEffect(() => {
    refresh();
  }, []);

  const refresh = () => {
    setBranches(getBranches());
    setColleges(getColleges());
    setDepts(getDepartments());
    setPrograms(getAcademicPrograms());
    setSections(getSections());
    setStaff(getStaff());
  };

  const handleOpenAdd = (level: OrgLevel, pId: string | null = null) => {
    if (!canManage) return;
    setEditItem(null);
    setModalLevel(level);
    setParentId(pId);
    setShowModal(true);
  };

  const handleOpenEdit = (level: OrgLevel, item: any) => {
    if (!canManage) return;
    setEditItem(item);
    setModalLevel(level);
    setShowModal(true);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);

    if (modalLevel === 'branch') {
      saveBranch({ 
        id: editItem?.id || `BR-${Date.now()}`, 
        name: formData.get('name') as string,
        location: formData.get('location') as string 
      });
    } else if (modalLevel === 'college') {
      saveCollege({
        id: editItem?.id || `COL-${Date.now()}`,
        branchId: (formData.get('branchId') as string) || parentId || '',
        name: formData.get('name') as string,
        deanName: formData.get('deanName') as string
      });
    } else if (modalLevel === 'dept') {
      saveDepartment({
        id: editItem?.id || `DEPT-${Date.now()}`,
        collegeId: (formData.get('collegeId') as string) || parentId || '',
        name: formData.get('name') as string,
        headName: formData.get('headName') as string
      });
    } else if (modalLevel === 'program') {
      saveAcademicProgram({
        id: editItem?.id || `PRG-${Date.now()}`,
        deptId: (formData.get('deptId') as string) || parentId || '',
        name: formData.get('name') as string,
        type: formData.get('type') as ProgramType,
        durationSemesters: parseInt(formData.get('duration') as string)
      });
    } else if (modalLevel === 'section') {
      saveSection({
        id: editItem?.id || `SEC-${Date.now()}`,
        programId: (formData.get('programId') as string) || parentId || '',
        name: formData.get('name') as string
      });
    }

    notifySuccess('تم حفظ البيانات بنجاح');
    setShowModal(false);
    refresh();
  };

  return (
    <div className="p-8">
      <div className="mb-8 flex justify-between items-start">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <Network className="text-blue-600" />
            الهيكل التنظيمي الأكاديمي
          </h2>
          <p className="text-slate-500 mt-1">إدارة فروع الجامعة، الكليات، الأقسام، والشعب العلمية</p>
        </div>
        <div className="flex gap-2 bg-white p-1 rounded-xl border shadow-sm">
            <button 
                onClick={() => setViewMode('tree')}
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'tree' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
                العرض الشجري
            </button>
            <button 
                onClick={() => setViewMode('cards')}
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'cards' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
                عرض القوائم
            </button>
        </div>
      </div>

      {viewMode === 'tree' ? (
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 min-h-[600px] animate-in fade-in zoom-in duration-300">
            <div className="max-w-4xl mx-auto">
                <div className="flex items-center justify-between mb-8 pb-4 border-b border-slate-100">
                    <h3 className="font-bold text-slate-700 flex items-center gap-2">
                        <Layers size={20} className="text-blue-500" />
                        مستعرض التسلسل الهرمي والمنتسبين
                    </h3>
                    {canManage && (
                        <button onClick={() => handleOpenAdd('branch')} className="text-blue-600 hover:bg-blue-50 px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-2 transition-colors">
                            <Plus size={16} /> إضافة فرع جديد
                        </button>
                    )}
                </div>

                <div className="space-y-4">
                    {branches.length > 0 ? branches.map(branch => (
                        <TreeNode 
                            key={branch.id} 
                            item={branch} 
                            level="branch" 
                            canManage={canManage}
                            onAddChild={(l, p) => handleOpenAdd(l, p)}
                            onEdit={(l, i) => handleOpenEdit(l, i)}
                            childrenData={{colleges, depts, programs, sections, staff}}
                        />
                    )) : (
                        <div className="text-center py-20 text-slate-400">
                            <Network size={48} className="mx-auto mb-4 opacity-20" />
                            <p>لم يتم تعريف فروع للجامعة بعد</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
      ) : (
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col min-h-[600px] animate-in slide-in-from-bottom-4 duration-300">
          <div className="flex border-b border-slate-200 bg-slate-50 px-6 pt-4 gap-4 overflow-x-auto no-scrollbar">
            {(['branch', 'college', 'dept', 'program', 'section'] as OrgLevel[]).map(lvl => (
                <button 
                  key={lvl}
                  onClick={() => setActiveTab(lvl)} 
                  className={`pb-4 px-4 text-sm font-bold border-b-2 flex items-center gap-2 transition-all ${activeTab === lvl ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500'}`}
                >
                  {lvl === 'branch' && <MapPin size={18} />}
                  {lvl === 'college' && <Landmark size={18} />}
                  {lvl === 'dept' && <Building2 size={18} />}
                  {lvl === 'program' && <BookOpen size={18} />}
                  {lvl === 'section' && <Layers size={18} />}
                  {lvl === 'branch' ? 'الفروع' : lvl === 'college' ? 'الكليات' : lvl === 'dept' ? 'الأقسام' : lvl === 'program' ? 'البرامج' : 'الشُعب'}
                </button>
            ))}
          </div>

          <div className="p-6 flex-1">
            <div className="flex justify-between items-center mb-6">
              <h3 className="font-bold text-slate-700">سجل الإدخالات المباشرة</h3>
              {canManage && (
                <button onClick={() => handleOpenAdd(activeTab)} className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700 shadow-sm transition-all">
                  <Plus size={18} /> إضـافة
                </button>
              )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {activeTab === 'branch' && branches.map(item => (
                <DirectCard key={item.id} title={item.name} sub={item.location} icon={MapPin} onEdit={() => handleOpenEdit('branch', item)} canManage={canManage} />
              ))}
              {activeTab === 'college' && colleges.map(item => (
                <DirectCard key={item.id} title={item.name} sub={`العميد: ${item.deanName || '---'}`} icon={Landmark} onEdit={() => handleOpenEdit('college', item)} canManage={canManage} />
              ))}
              {activeTab === 'dept' && depts.map(item => (
                <DirectCard key={item.id} title={item.name} sub={`رئيس القسم: ${item.headName || '---'}`} icon={Building2} onEdit={() => handleOpenEdit('dept', item)} canManage={canManage} />
              ))}
              {activeTab === 'program' && programs.map(item => (
                <DirectCard key={item.id} title={item.name} sub={`النوع: ${item.type} | الفصول: ${item.durationSemesters}`} icon={BookOpen} onEdit={() => handleOpenEdit('program', item)} canManage={canManage} />
              ))}
              {activeTab === 'section' && sections.map(item => (
                <DirectCard key={item.id} title={item.name} sub="تخصص دقيق" icon={Layers} onEdit={() => handleOpenEdit('section', item)} canManage={canManage} />
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="bg-slate-900 text-white p-5 flex justify-between items-center">
              <h3 className="font-bold flex items-center gap-2">
                  <Edit2 size={18} />
                  {editItem ? 'تعديل البيانات' : 'إضافة مدخل جديد'}
              </h3>
              <button onClick={() => setShowModal(false)} className="hover:rotate-90 transition-transform"><X /></button>
            </div>
            <form onSubmit={handleSave} className="p-6 space-y-4">
              {modalLevel === 'branch' && (
                <>
                  <FormInput label="اسم الفرع" name="name" defaultValue={editItem?.name} />
                  <FormInput label="الموقع الجغرافي" name="location" defaultValue={editItem?.location} />
                </>
              )}
              {modalLevel === 'college' && (
                <>
                  {!parentId && (
                    <FormSelect label="الفرع التابع له" name="branchId" defaultValue={editItem?.branchId}>
                        {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
                    </FormSelect>
                  )}
                  <FormInput label="اسم الكلية" name="name" defaultValue={editItem?.name} />
                  <FormInput label="اسم العميد" name="deanName" defaultValue={editItem?.deanName} />
                </>
              )}
              {modalLevel === 'dept' && (
                <>
                  {!parentId && (
                    <FormSelect label="الكلية" name="collegeId" defaultValue={editItem?.collegeId}>
                        {colleges.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </FormSelect>
                  )}
                  <FormInput label="اسم القسم" name="name" defaultValue={editItem?.name} />
                  <FormInput label="رئيس القسم" name="headName" defaultValue={editItem?.headName} />
                </>
              )}
              {modalLevel === 'program' && (
                <>
                  {!parentId && (
                    <FormSelect label="القسم العلمي" name="deptId" defaultValue={editItem?.deptId}>
                        {depts.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                    </FormSelect>
                  )}
                  <FormInput label="اسم البرنامج" name="name" defaultValue={editItem?.name} />
                  <FormSelect label="نوع الدرجة" name="type" defaultValue={editItem?.type}>
                    <option value={ProgramType.UNDERGRADUATE}>بكالوريوس (جامعي)</option>
                    <option value={ProgramType.POSTGRADUATE}>ماجستير/دكتوراه (دراسات عليا)</option>
                  </FormSelect>
                  <FormInput label="عدد الفصول المقررة" name="duration" type="number" defaultValue={editItem?.durationSemesters} />
                </>
              )}
              {modalLevel === 'section' && (
                <>
                  {!parentId && (
                    <FormSelect label="البرنامج العلمي" name="programId" defaultValue={editItem?.programId}>
                        {programs.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                    </FormSelect>
                  )}
                  <FormInput label="اسم الشعبة / التخصص" name="name" defaultValue={editItem?.name} />
                </>
              )}
              <div className="pt-4 flex justify-end gap-3 border-t">
                <button type="button" onClick={() => setShowModal(false)} className="px-5 py-2 text-slate-500 font-bold">إلغاء</button>
                <button type="submit" className="bg-blue-600 text-white px-8 py-2 rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 transition-all">حفظ</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

// @fix: Added missing GraduationCap import from lucide-react to avoid "Cannot find name 'GraduationCap'" error on line 409
const TreeNode = ({ item, level, canManage, onAddChild, onEdit, childrenData }: any) => {
    const [isOpen, setIsOpen] = useState(level === 'branch');
    const [showStaff, setShowStaff] = useState(false);

    let children: any[] = [];
    let childLevel: OrgLevel | null = null;
    let Icon = MapPin;
    let label = "";

    // Filter staff belonging to this specific node
    const staffHere = childrenData.staff.filter((s: StaffMember) => {
      if (level === 'branch') return s.branchId === item.id && !s.collegeId;
      if (level === 'college') return s.collegeId === item.id && !s.deptId;
      if (level === 'dept') return s.deptId === item.id;
      return false;
    });

    if (level === 'branch') {
        children = childrenData.colleges.filter((c: any) => c.branchId === item.id);
        childLevel = 'college';
        Icon = MapPin;
        label = "فرع";
    } else if (level === 'college') {
        children = childrenData.depts.filter((d: any) => d.collegeId === item.id);
        childLevel = 'dept';
        Icon = Landmark;
        label = "كلية";
    } else if (level === 'dept') {
        children = childrenData.programs.filter((p: any) => p.deptId === item.id);
        childLevel = 'program';
        Icon = Building2;
        label = "قسم";
    } else if (level === 'program') {
        children = childrenData.sections.filter((s: any) => s.programId === item.id);
        childLevel = 'section';
        Icon = BookOpen;
        label = "برنامج";
    } else {
        Icon = Layers;
        label = "شعبة";
    }

    const hasChildren = children.length > 0 || staffHere.length > 0;

    return (
        <div className="border-r-2 border-slate-100 pr-4 mr-2 mb-2 select-none">
            <div className={`flex items-center justify-between p-3 rounded-xl transition-all group ${isOpen && hasChildren ? 'bg-slate-50' : 'hover:bg-slate-50'}`}>
                <div className="flex items-center gap-3">
                    <div onClick={() => setIsOpen(!isOpen)} className="cursor-pointer">
                        {hasChildren ? (
                            isOpen ? <ChevronDown size={18} className="text-slate-400" /> : <ChevronRight size={18} className="text-slate-400" />
                        ) : (
                            <div className="w-[18px]"></div>
                        )}
                    </div>
                    <div className={`p-2 rounded-lg ${
                        level === 'branch' ? 'bg-blue-100 text-blue-600' :
                        level === 'college' ? 'bg-indigo-100 text-indigo-600' :
                        level === 'dept' ? 'bg-teal-100 text-teal-600' :
                        level === 'program' ? 'bg-purple-100 text-purple-600' :
                        'bg-slate-100 text-slate-600'
                    }`}>
                        <Icon size={16} />
                    </div>
                    <div>
                        <span className="text-[10px] font-bold text-slate-400 block uppercase tracking-tighter leading-none mb-1">{label}</span>
                        <span className="font-bold text-slate-800 text-sm">{item.name}</span>
                        {staffHere.length > 0 && (
                          <span className="ms-2 px-1.5 py-0.5 bg-blue-50 text-blue-600 rounded text-[10px] font-black">
                            {staffHere.length} موظف/محاضر
                          </span>
                        )}
                    </div>
                </div>

                <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    {staffHere.length > 0 && (
                      <button onClick={() => setShowStaff(!showStaff)} className={`p-1.5 rounded-lg transition-colors ${showStaff ? 'bg-blue-600 text-white' : 'text-blue-600 hover:bg-blue-100'}`} title="عرض المنتسبين">
                        <Users size={16} />
                      </button>
                    )}
                    {canManage && childLevel && (
                        <button 
                            onClick={() => onAddChild(childLevel, item.id)}
                            className="p-1.5 text-blue-600 hover:bg-blue-100 rounded-lg tooltip"
                            title={`إضافة ${childLevel === 'college' ? 'كلية' : childLevel === 'dept' ? 'قسم' : childLevel === 'program' ? 'برنامج' : 'شعبة'}`}
                        >
                            <FolderPlus size={16} />
                        </button>
                    )}
                    {canManage && (
                        <button 
                            onClick={() => onEdit(level, item)}
                            className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg"
                        >
                            <Edit2 size={16} />
                        </button>
                    )}
                </div>
            </div>

            {isOpen && (
                <div className="mt-2 animate-in slide-in-from-top-1 duration-200">
                    {showStaff && staffHere.map((s: StaffMember) => (
                      <div key={s.id} className="flex items-center gap-3 p-2 ms-8 border-r border-dashed border-blue-200 mb-1 bg-blue-50/30 rounded-lg">
                        <div className="w-8 h-8 rounded-full bg-white border border-blue-100 flex items-center justify-center text-blue-600">
                          {s.type === 'ACADEMIC' ? <GraduationCap size={14}/> : <User size={14}/>}
                        </div>
                        <div>
                          <p className="text-xs font-bold text-slate-700">{s.name}</p>
                          <p className="text-[10px] text-slate-400">{s.position}</p>
                        </div>
                      </div>
                    ))}
                    {children.map(child => (
                        <TreeNode 
                            key={child.id} 
                            item={child} 
                            level={childLevel} 
                            canManage={canManage}
                            onAddChild={onAddChild}
                            onEdit={onEdit}
                            childrenData={childrenData}
                        />
                    ))}
                </div>
            )}
        </div>
    );
};

const DirectCard = ({ title, sub, icon: Icon, onEdit, canManage }: any) => (
  <div className="bg-white border border-slate-200 p-5 rounded-xl hover:shadow-md transition-all group flex items-center justify-between">
    <div className="flex items-center gap-4">
      <div className="bg-blue-50 text-blue-600 p-3 rounded-xl group-hover:bg-blue-600 group-hover:text-white transition-colors">
        <Icon size={20} />
      </div>
      <div>
        <h4 className="font-bold text-slate-800">{title}</h4>
        <p className="text-xs text-slate-400">{sub}</p>
      </div>
    </div>
    {canManage && (
        <button onClick={onEdit} className="p-2 text-slate-400 hover:text-blue-600 transition-colors opacity-0 group-hover:opacity-100">
            <Edit2 size={16} />
        </button>
    )}
  </div>
);

const FormInput = ({ label, name, defaultValue, type = "text" }: any) => (
  <div>
    <label className="block text-sm font-bold text-slate-700 mb-1">{label}</label>
    <input name={name} defaultValue={defaultValue} type={type} required className="w-full border-2 border-slate-100 bg-slate-50 rounded-xl px-4 py-2 focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none transition-all" />
  </div>
);

const FormSelect = ({ label, name, children, defaultValue }: any) => (
  <div>
    <label className="block text-sm font-bold text-slate-700 mb-1">{label}</label>
    <select name={name} defaultValue={defaultValue} className="w-full border-2 border-slate-100 bg-slate-50 rounded-xl px-4 py-2 focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none transition-all">
      {children}
    </select>
  </div>
);

export default UniversityManagement;

import { GoogleGenAI } from "@google/genai";
import { LIBYAN_REGULATION_501_SUMMARY } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const askAcademicAdvisor = async (studentData: any, question: string) => {
  try {
    const prompt = `
      Context: You are the Smart Academic Advisor for Manara SIS. 
      You strictly follow the Libyan Higher Education Regulation #501.

      Regulation Summary: ${LIBYAN_REGULATION_501_SUMMARY}

      Current Student File: ${JSON.stringify(studentData)}

      User Question: ${question}

      Instruction: Provide a professional, concise answer in Arabic. 
      If the question is about eligibility or warnings, cite the specific rules from the regulation provided.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "عذراً، واجه المستشار الذكي مشكلة في الاتصال. يرجى المحاولة لاحقاً.";
  }
};

import React, { useState } from 'react';
import { Sparkles, Send, Bot, User, X, Loader2 } from 'lucide-react';
import { askAcademicAdvisor } from '../services/geminiService';
import { Student } from '../types';

interface SmartAdvisorProps {
  student: Student;
}

const SmartAdvisor: React.FC<SmartAdvisorProps> = ({ student }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [chat, setChat] = useState<{role: 'ai' | 'user', text: string}[]>([]);
  const [loading, setLoading] = useState(false);

  const handleAsk = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!query.trim()) return;

    const userMsg = query;
    setChat(prev => [...prev, { role: 'user', text: userMsg }]);
    setQuery('');
    setLoading(true);

    const aiResponse = await askAcademicAdvisor(student, userMsg);
    setChat(prev => [...prev, { role: 'ai', text: aiResponse || '' }]);
    setLoading(false);
  };

  return (
    <div className="fixed bottom-6 left-6 z-[100]">
      {isOpen ? (
        <div className="bg-white w-96 h-[500px] rounded-2xl shadow-2xl border border-blue-100 flex flex-col overflow-hidden animate-in slide-in-from-bottom-4">
          <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-4 text-white flex justify-between items-center">
            <div className="flex items-center gap-2">
              <Sparkles size={20} className="text-yellow-300 fill-yellow-300" />
              <span className="font-bold">المستشار الذكي (لائحة 501)</span>
            </div>
            <button onClick={() => setIsOpen(false)}><X size={20} /></button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50">
            <div className="bg-blue-50 border border-blue-100 p-3 rounded-xl text-xs text-blue-800">
                مرحباً! أنا مساعدك الذكي. يمكنني تحليل وضع الطالب <strong>{student.name}</strong> القانوني والأكاديمي.
            </div>
            {chat.map((msg, i) => (
              <div key={i} className={`flex ${msg.role === 'user' ? 'justify-start' : 'justify-end'}`}>
                <div className={`max-w-[80%] p-3 rounded-2xl text-sm ${msg.role === 'user' ? 'bg-white border text-slate-700' : 'bg-blue-600 text-white shadow-md'}`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {loading && (
              <div className="flex justify-end">
                <div className="bg-blue-100 p-3 rounded-2xl">
                  <Loader2 size={18} className="animate-spin text-blue-600" />
                </div>
              </div>
            )}
          </div>

          <form onSubmit={handleAsk} className="p-4 bg-white border-t">
            <div className="relative">
              <input 
                type="text" 
                value={query}
                onChange={e => setQuery(e.target.value)}
                placeholder="اسأل عن الأهلية، الإنذارات..."
                className="w-full pl-10 pr-4 py-2 bg-slate-100 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
              <button type="submit" className="absolute left-2 top-1/2 -translate-y-1/2 text-blue-600 hover:scale-110 transition-transform">
                <Send size={18} />
              </button>
            </div>
          </form>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
