);

const AuditSection = ({ title, total, done }: any) => (
    <div className="space-y-4">
        <div className="flex justify-between items-center">
            <h4 className="font-black text-slate-700">{title}</h4>
            <span className="text-xs font-black bg-slate-100 px-3 py-1 rounded-full">{done} / {total} تم إنجازها</span>
        </div>
        <div className="flex gap-2">
            {Array.from({length: total}).map((_, i) => (
                <div key={i} className={`h-3 flex-1 rounded-full transition-all duration-500 ${i < done ? 'bg-green-500 shadow-sm shadow-green-500/20' : 'bg-slate-200'}`}></div>
            ))}
        </div>
    </div>
);

