import { getStudents, getAcademicPrograms } from '../services/storageService';
import { Student, StudentStatus, ProgramType } from '../types';
import { ShieldCheck, AlertTriangle, Info, CheckCircle, Search, Filter, ArrowUpRight, Scale, Clock, GraduationCap } from 'lucide-react';
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell, PieChart, Pie } from 'recharts';

const ComplianceMonitor: React.FC = () => {
    const [students, setStudents] = useState<Student[]>([]);
    const [violations, setViolations] = useState<{
        lowGpa: Student[],
        timeExceeded: Student[],
        warningLimit: Student[],
        incorrectPassStatus: Student[]
    }>({
        lowGpa: [],
        timeExceeded: [],
        warningLimit: [],
        incorrectPassStatus: []
    });

    useEffect(() => {
        const allStudents = getStudents();
        setStudents(allStudents);

        // Audit Logic based on Regulation 501
        const audit = {
            lowGpa: allStudents.filter(s => {
                const limit = s.program === ProgramType.POSTGRADUATE ? 65 : 50;
                return s.gpa < limit && s.status === StudentStatus.ACTIVE;
            }),
            timeExceeded: allStudents.filter(s => {
                const yearsIn = new Date().getFullYear() - s.enrollmentYear;
                const maxYears = s.program === ProgramType.POSTGRADUATE ? 4 : 8; // Example logic
                return yearsIn > maxYears;
            }),
            warningLimit: allStudents.filter(s => s.warningsCount >= 2),
            incorrectPassStatus: allStudents.filter(s => {
                // Postgrad needs 65 but status is active despite GPA < 65
                return s.program === ProgramType.POSTGRADUATE && s.gpa < 65 && s.status === StudentStatus.ACTIVE;
            })
        };
        setViolations(audit);
    }, []);

    const complianceScore = Math.round(100 - ((violations.lowGpa.length + violations.warningLimit.length) / students.length) * 100);

    return (
        <div className="p-8 space-y-8 animate-in fade-in duration-500">
            <div className="flex justify-between items-start">
                <div>
                    <h2 className="text-3xl font-black text-slate-800 flex items-center gap-3">
                        <Scale className="text-indigo-600" size={32} />
                        مركز الامتثال والرقابة القانونية
                    </h2>
                    <p className="text-slate-500 mt-2 font-medium">تدقيق آلي للامتثال لبنود اللائحة 501 للتعليم العالي</p>
                </div>
                <div className="bg-white p-4 rounded-3xl shadow-sm border border-slate-200 flex items-center gap-4">
                    <div className="text-left">
                        <p className="text-[10px] font-black text-slate-400 uppercase">مؤشر الامتثال العام</p>
                        <p className="text-2xl font-black text-indigo-600">%{complianceScore}</p>
                    </div>
                    <div className="w-12 h-12 rounded-full border-4 border-indigo-100 border-t-indigo-600 flex items-center justify-center font-bold text-xs text-indigo-600">
                        {complianceScore}
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                <ViolationCard 
                    title="معدلات حرجة" 
                    count={violations.lowGpa.length} 
                    icon={AlertTriangle} 
                    color="red" 
                    desc="أقل من الحد الأدنى للنجاح"
                />
                <ViolationCard 
                    title="تجاوز المدة" 
                    count={violations.timeExceeded.length} 
                    icon={Clock} 
                    color="amber" 
                    desc="تجاوز ضعف مدة الدراسة"
                />
                <ViolationCard 
                    title="حد الإنذارات" 
                    count={violations.warningLimit.length} 
                    icon={ShieldCheck} 
                    color="purple" 
                    desc="طلاب على وشك الفصل"
                />
                <ViolationCard 
                    title="مطابقة الحالة" 
                    count={violations.incorrectPassStatus.length} 
                    icon={GraduationCap} 
                    color="blue" 
                    desc="عدم تطابق الحالة مع المعدل"
                />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2 bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                    <div className="p-6 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
                        <h3 className="font-black text-slate-700">قائمة المخالفات المرصودة</h3>
                        <button className="text-xs font-bold text-indigo-600 hover:underline">تصدير تقرير للمسجل العام</button>
                    </div>
                    <div className="flex-1 overflow-auto max-h-[500px]">
                        <table className="w-full text-right border-collapse">
                            <thead className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase sticky top-0 z-10">
                                <tr>
                                    <th className="px-6 py-4">الطالب</th>
                                    <th className="px-6 py-4">نوع المخالفة</th>
                                    <th className="px-6 py-4">البند القانوني</th>
                                    <th className="px-6 py-4 text-center">الإجراء</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {violations.lowGpa.map(s => (
                                    <ViolationRow key={s.id} student={s} type="تدني معدل" law="المادة 32" status="critical" />
                                ))}
                                {violations.timeExceeded.map(s => (
                                    <ViolationRow key={s.id} student={s} type="تجاوز زمن" law="المادة 18" status="warning" />
                                ))}
                                {violations.warningLimit.map(s => (
                                    <ViolationRow key={s.id} student={s} type="إنذارات نهائية" law="المادة 46" status="critical" />
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>

                <div className="space-y-8">
                    <div className="bg-slate-900 rounded-[32px] p-8 text-white relative overflow-hidden group shadow-2xl">
                        <div className="absolute -top-10 -right-10 w-40 h-40 bg-indigo-500/20 rounded-full blur-3xl transition-all group-hover:scale-150"></div>
                        <h4 className="text-xl font-black mb-4 flex items-center gap-2">
                            <Info className="text-indigo-400" />
                            رأي المنظومة الذكي
                        </h4>
                        <p className="text-slate-400 text-sm leading-relaxed mb-6">
                            نظام التدقيق رصد ارتفاعاً بنسبة <span className="text-white font-bold">12%</span> في مخالفات البند 46 هذا الفصل. يوصى بعقد جلسة إرشاد أكاديمي طارئة للأقسام العلمية المتأثرة.
                        </p>
                        <button className="w-full py-3 bg-indigo-600 rounded-2xl font-bold text-sm hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                            تحليل مسببات التعثر <ArrowUpRight size={18} />
                        </button>
                    </div>

                    <div className="bg-white rounded-[32px] border border-slate-200 p-8 shadow-sm">
                        <h4 className="font-black text-slate-800 mb-6">توزيع المخالفات حسب القسم</h4>
                        <div className="h-64">
                            <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                    <Pie
                                        data={[
                                            { name: 'معدلات', value: violations.lowGpa.length },
                                            { name: 'زمن', value: violations.timeExceeded.length },
                                            { name: 'إنذارات', value: violations.warningLimit.length }
                                        ]}
                                        innerRadius={60}
                                        outerRadius={80}
                                        paddingAngle={10}
                                        dataKey="value"
                                    >
                                        <Cell fill="#ef4444" />
                                        <Cell fill="#f59e0b" />
                                        <Cell fill="#8b5cf6" />
                                    </Pie>
                                    <Tooltip />
                                </PieChart>
                            </ResponsiveContainer>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

const ViolationCard = ({ title, count, icon: Icon, color, desc }: any) => (
    <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm hover:shadow-md transition-shadow">
        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mb-4 ${
            color === 'red' ? 'bg-red-50 text-red-600' :
            color === 'amber' ? 'bg-amber-50 text-amber-600' :
            color === 'purple' ? 'bg-purple-50 text-purple-600' :
            'bg-blue-50 text-blue-600'
        }`}>
            <Icon size={24} />
        </div>
        <p className="text-3xl font-black text-slate-800">{count}</p>
        <p className="text-sm font-bold text-slate-700 mt-1">{title}</p>
        <p className="text-[10px] font-medium text-slate-400 mt-1">{desc}</p>
    </div>
);

const ViolationRow = ({ student, type, law, status }: any) => (
    <tr className="hover:bg-slate-50 transition-colors">
        <td className="px-6 py-4">
            <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-[10px] font-black">{student.name.charAt(0)}</div>
                <div>
                    <p className="text-sm font-bold text-slate-800">{student.name}</p>
                    <p className="text-[10px] text-slate-400 font-mono">{student.id}</p>
                </div>
            </div>
        </td>
        <td className="px-6 py-4 text-xs font-bold text-slate-600">{type}</td>
        <td className="px-6 py-4">
            <span className="bg-slate-100 px-2 py-1 rounded text-[10px] font-black text-slate-500 border border-slate-200">{law}</span>
        </td>
        <td className="px-6 py-4 text-center">
            <button className={`px-4 py-1.5 rounded-xl text-[10px] font-black transition-all ${
                status === 'critical' ? 'bg-red-600 text-white hover:bg-red-700 shadow-lg shadow-red-200' : 'bg-slate-800 text-white hover:bg-slate-900 shadow-lg shadow-slate-200'
            }`}>
                {status === 'critical' ? 'تجميد فوري' : 'توجيه إنذار'}
            </button>
        </td>
    </tr>
);

export default ComplianceMonitor;

import React, { useEffect, useState } from 'react';
import { 
  LayoutDashboard, Users, BookOpen, GraduationCap, Settings, 
  FileText, TrendingUp, Wallet, FileQuestion, Briefcase, 
  UserCheck, Calendar, Clock, Shield, ClipboardCheck, 
  Bell, School, Network, Contact, Scale
} from 'lucide-react';
import { getStudents } from '../services/storageService';
import { StudentStatus, AuthUser, UserRole, Permission } from '../types';
import { getAccessibleTabs, hasPermission } from '../services/authService';

interface SidebarProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  currentUser: AuthUser;
}

const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, currentUser }) => {
  const [warningCount, setWarningCount] = useState(0);

  useEffect(() => {
    if (hasPermission(currentUser, Permission.STUDENTS_VIEW)) {
        const fetchCounts = () => {
            const students = getStudents();
            const count = students.filter(s => s.warningsCount > 0 || s.status === StudentStatus.WARNING).length;
            setWarningCount(count);
        };

        fetchCounts();
        const interval = setInterval(fetchCounts, 5000);
        return () => clearInterval(interval);
    } else {
        setWarningCount(0);
    }
  }, [currentUser]);

  const allMenuItems = [
    { id: 'dashboard', label: 'لوحة المعلومات', icon: LayoutDashboard },
    { id: 'compliance', label: 'الامتثال القانوني', icon: Scale },
    { id: 'students', label: 'شؤون الطلاب', icon: Users, badge: warningCount },
    { id: 'organization', label: 'الهيكل الأكاديمي', icon: Network },
    { id: 'registration', label: 'تنزيل المواد', icon: ClipboardCheck },
    { id: 'academics', label: 'السجل الأكاديمي', icon: BookOpen },
    { id: 'facilities', label: 'المنشآت والقاعات', icon: School },
    { id: 'schedule', label: 'الجدول الدراسي', icon: Calendar },
    { id: 'exams', label: 'جدول الامتحانات', icon: Clock },
    { id: 'staff', label: 'الموظفين وأعضاء التدريس', icon: Contact },
    { id: 'attendance', label: 'الحضور والغياب', icon: UserCheck },
    { id: 'financials', label: 'الإدارة المالية', icon: Wallet },
    { id: 'requests', label: 'الخدمات والطلبات', icon: FileQuestion },
    { id: 'communications', label: 'المراسلات والتنبيهات', icon: Bell },
    { id: 'reports', label: 'التقارير والإحصاء', icon: TrendingUp },
    { id: 'graduates', label: 'الخريجين', icon: GraduationCap },
    { id: 'roles', label: 'إدارة الصلاحيات', icon: Shield },
    { id: 'regulations', label: 'دليل اللوائح', icon: FileText },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  const allowedTabs = getAccessibleTabs(currentUser);
  const canRegister = hasPermission(currentUser, [Permission.ACADEMICS_MANAGE]);
  const canCommunicate = hasPermission(currentUser, [Permission.COMMUNICATIONS_MANAGE]);
  const canManageFacilities = hasPermission(currentUser, [Permission.FACILITIES_MANAGE]);
  const canManageOrg = hasPermission(currentUser, [Permission.ORGANIZATION_MANAGE]);
  const canManageStaff = hasPermission(currentUser, [Permission.STAFF_MANAGE, Permission.FACULTY_MANAGE]);
  const isAdmin = currentUser.role === UserRole.ADMIN;

  const menuItems = allMenuItems.filter(item => {
      if (item.id === 'compliance' && !isAdmin) return false;
      if (item.id === 'registration' && !canRegister) return false;
      if (item.id === 'communications' && !canCommunicate) return false;
      if (item.id === 'facilities' && !canManageFacilities) return false;
      if (item.id === 'organization' && !canManageOrg) return false;
      if (item.id === 'staff' && !canManageStaff) return false;
      return allowedTabs.includes(item.id);
  });

  return (
    <div className="w-64 bg-slate-900 text-white min-h-screen flex flex-col shadow-xl print:hidden">
      <div className="p-6 border-b border-slate-700 flex items-center gap-3">
        <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-xl shadow-lg shadow-blue-900/50">
          م
        </div>
        <div>
          <h1 className="font-bold text-lg">نظام المنارة</h1>
          <p className="text-xs text-slate-400">الإصدار 3.2</p>
        </div>
      </div>

      <nav className="flex-1 p-4 space-y-2 overflow-y-auto custom-scrollbar">
        {menuItems.map((item) => {
            const Icon = item.icon;
            return (
                <button
                key={item.id}
                onClick={() => setActiveTab(item.id)}
                className={`w-full flex items-center justify-between px-4 py-3 rounded-lg transition-all duration-200 group ${
                    activeTab === item.id 
                    ? 'bg-blue-600 text-white shadow-md shadow-blue-900/20' 
                    : 'text-slate-300 hover:bg-slate-800 hover:text-white'
                }`}
                >
                <div className="flex items-center gap-3">
                    <Icon size={20} className={activeTab === item.id ? 'animate-pulse' : ''} />
                    <span className="font-medium">{item.label}</span>
                </div>
                {item.badge !== undefined && item.badge > 0 && (
                    <span className="bg-red-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full shadow-sm">
                        {item.badge}
                    </span>
                )}
                </button>
            )
        })}
      </nav>

      <div className="p-4 border-t border-slate-700">
        <div className="bg-slate-800 rounded-lg p-3 mb-4 border border-slate-700">
            <div className="flex items-center gap-3 mb-2">
                <div className="w-8 h-8 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center shadow-lg">
                    <span className="text-xs font-bold text-white">{currentUser.name.charAt(0)}</span>
                </div>
                <div className="overflow-hidden">
                    <p className="text-sm font-bold truncate">{currentUser.name}</p>
                    <p className="text-[10px] text-blue-300 truncate">{currentUser.role}</p>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import StudentsList from './components/StudentsList';
import UniversityManagement from './components/UniversityManagement';
import Registration from './components/Registration';
import Academics from './components/Academics';
import Facilities from './components/Facilities';
import Graduates from './components/Graduates';
import Reports from './components/Reports';
import Settings from './components/Settings';
import Financials from './components/Financials';
import ServiceRequests from './components/ServiceRequests';
import Communications from './components/Communications';
import StaffManagement from './components/StaffManagement';
import ComplianceMonitor from './components/ComplianceMonitor';
import Attendance from './components/Attendance';
import Schedule from './components/Schedule';
import ExamSchedule from './components/ExamSchedule';
import RolesManagement from './components/RolesManagement';
import Login from './components/Login';
import ToastContainer from './components/ToastContainer';
import { Book, FileText, Download, Lock } from 'lucide-react';
import { LIBYAN_REGULATION_501_SUMMARY } from './constants';
import { AuthUser, Permission, UserRole } from './types';
import { getCurrentUser, logout, getAccessibleTabs, hasPermission } from './services/authService';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<AuthUser | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');

  useEffect(() => {
    const user = getCurrentUser();
    if (user) {
        setCurrentUser(user);
    }
  }, []);

  const handleLogin = (user: AuthUser) => {
      setCurrentUser(user);
      setActiveTab('dashboard');
  };

  const handleLogout = () => {
      logout();
      setCurrentUser(null);
  };

  const renderContent = () => {
    if (currentUser) {
        const allowedTabs = getAccessibleTabs(currentUser);
        const canCommunicate = hasPermission(currentUser, Permission.COMMUNICATIONS_MANAGE);
        const canManageFacilities = hasPermission(currentUser, Permission.FACILITIES_MANAGE);
        const canManageOrg = hasPermission(currentUser, Permission.ORGANIZATION_MANAGE);
        const canManageStaff = hasPermission(currentUser, [Permission.STAFF_MANAGE, Permission.FACULTY_MANAGE]);
        const isAdmin = currentUser.role === UserRole.ADMIN;

        if (!allowedTabs.includes(activeTab) && 
            activeTab !== 'registration' && 
            !(activeTab === 'communications' && canCommunicate) &&
            !(activeTab === 'facilities' && canManageFacilities) &&
            !(activeTab === 'organization' && canManageOrg) &&
            !(activeTab === 'compliance' && isAdmin) &&
            !(activeTab === 'staff' && canManageStaff)) {
            return (
                <div className="flex flex-col items-center justify-center h-[80vh] text-slate-400">
                    <div className="bg-red-50 p-6 rounded-full mb-4">
                        <Lock size={48} className="text-red-500" />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-800 mb-2">الدخول غير مصرح به</h2>
                    <p>ليس لديك الصلاحيات الكافية للوصول إلى هذه الصفحة.</p>
                </div>
            );
        }
    }

    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'compliance': return <ComplianceMonitor />;
      case 'students': return <StudentsList />;
      case 'organization': return <UniversityManagement />;
      case 'registration': return <Registration />;
      case 'academics': return <Academics />;
      case 'facilities': return <Facilities />;
      case 'schedule': return <Schedule />;
      case 'exams': return <ExamSchedule />;
      case 'staff': return <StaffManagement />;
      case 'attendance': return <Attendance />;
      case 'financials': return <Financials />;
      case 'requests': return <ServiceRequests />;
      case 'communications': return <Communications />;
      case 'reports': return <Reports />;
      case 'graduates': return <Graduates />;
      case 'roles': return <RolesManagement />;
      case 'settings': return <Settings />;
      case 'regulations':
        return (
          <div className="p-8 max-w-4xl mx-auto">
            <div className="mb-8">
              <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                <FileText className="text-blue-600" />
                لائحة التعليم العالي 501
              </h2>
            </div>
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
              <div className="bg-slate-50 p-4 border-b flex justify-between items-center">
                <span className="font-bold text-slate-700">نصوص اللائحة</span>
                <button className="text-blue-600 text-sm hover:underline flex items-center gap-1">
                  <Download size={16} /> تحميل PDF
                </button>
              </div>
              <div className="p-8">
                <div className="prose prose-slate max-w-none font-sans whitespace-pre-line leading-loose text-slate-700">
                  {LIBYAN_REGULATION_501_SUMMARY}
                </div>
              </div>
            </div>
          </div>
        );
      default:
        return <div className="p-8 text-center text-slate-400">قيد التطوير</div>;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="flex flex-row min-h-screen bg-slate-50 font-sans" dir="rtl">
        <ToastContainer />
        <div className="flex flex-col w-64 bg-slate-900 text-white shadow-xl print:hidden h-screen sticky top-0">
             <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} currentUser={currentUser} />
             <div className="p-4 border-t border-slate-700 mt-auto">
                <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 text-slate-300 hover:text-red-400 hover:bg-slate-800 rounded-lg transition-colors">
                    <span className="font-medium">تسجيل الخروج</span>
                </button>
             </div>
        </div>
        <main className="flex-1 overflow-x-hidden overflow-y-auto h-screen print:overflow-visible print:h-auto">
            {renderContent()}
        </main>
    </div>
  );
};

export default App;

import React, { useEffect, useState } from 'react';
import StatCard from './StatCard';
import { Users, AlertTriangle, GraduationCap, TrendingUp, BookOpen, School, AlertCircle, ArrowRight, Activity, Clock, Wallet, DollarSign, CreditCard, Calendar, UserCheck, Briefcase, Bell, Scale, ShieldAlert } from 'lucide-react';
import { getStudents, getSystemSettings } from '../services/storageService';
import { getAuditLogs } from '../services/auditService';
import { getFinancialStats, getTransactions } from '../services/financeService';
import { getInstructorSchedule, getDayLabel } from '../services/scheduleService';
import { getCurrentUser } from '../services/authService';
import { StudentStatus, ProgramType, AuditLog, UserRole, DayOfWeek } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid, AreaChart, Area } from 'recharts';

const Dashboard: React.FC = () => {
  const currentUser = getCurrentUser();

  if (!currentUser) return null;

  if (currentUser.role === UserRole.FINANCE) {
      return <FinanceDashboard />;
  } else if (currentUser.role === UserRole.FACULTY) {
      return <FacultyDashboard />;
  } else {
      return <AcademicDashboard />; 
  }
};

const DeadlineAlerts: React.FC = () => {
    const settings = getSystemSettings();
    const now = new Date();
    const regDeadline = new Date(settings.registrationDeadline);
    const payDeadline = new Date(settings.paymentDeadline);

    const diffDays = (date: Date) => Math.ceil((date.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));

    const regDiff = diffDays(regDeadline);
    const payDiff = diffDays(payDeadline);

    if (regDiff > 14 && payDiff > 14) return null;

    return (
        <div className="mb-8 grid grid-cols-1 md:grid-cols-2 gap-4">
            {regDiff <= 14 && (
                <div className={`p-4 rounded-3xl border flex items-center gap-4 ${regDiff < 3 ? 'bg-red-50 border-red-200 text-red-800' : 'bg-amber-50 border-amber-200 text-amber-800'}`}>
