            courseId: currentExam.courseId,
            courseName: course?.name || '',
            date: currentExam.date,
            startTime: currentExam.startTime || '09:00',
            durationMinutes: Number(currentExam.durationMinutes) || 120,
            room: currentExam.room,
            invigilators: currentExam.invigilators || [],
            seatingPlan: seating || (currentExam as any).seatingPlan
        };

        const conflict = checkExamConflict(newExam, currentExam.id);
        if (conflict.hasConflict) {
            notifyError(conflict.message || 'يوجد تعارض في الجدول');
            return;
        }

        saveExam(newExam);
        logAction('جدول الامتحانات', `تم ${currentExam.id ? 'تعديل' : 'جدولة'} امتحان مقرر "${newExam.courseName}"`, 'info', currentUser?.name);
        notifySuccess('تم حفظ موعد الامتحان بنجاح وتوزيع المقاعد آلياً');
        setShowModal(false);
        refreshData();
        resetForm();
    };

    const resetForm = () => {
        setCurrentExam({ 
            date: new Date().toISOString().split('T')[0], 
            startTime: '09:00', 
            durationMinutes: 120, 
            room: '', 
            invigilators: [] 
        });
    };

    const handleDelete = (id: string) => {
        if (!canManageAcademics) return;
        if (confirm('هل أنت متأكد من حذف هذا الامتحان؟')) {
            const exam = exams.find(e => e.id === id);
            deleteExam(id);
            logAction('حذف امتحان', `تم حذف امتحان مقرر "${exam?.courseName}"`, 'danger', currentUser?.name);
            refreshData();
            notifySuccess('تم حذف الموعد');
        }
    };

    const filteredExams = exams.filter(e => 
        e.courseName.includes(searchTerm) || 
        e.courseId.includes(searchTerm) || 
        e.room.includes(searchTerm)
    ).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const groupedExams: Record<string, ExamSession[]> = {};
    filteredExams.forEach(exam => {
        if (!groupedExams[exam.date]) groupedExams[exam.date] = [];
        groupedExams[exam.date].push(exam);
    });

    return (
        <div className="p-8">
            <div className="mb-8 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 no-print">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                        <FileText className="text-blue-600" />
                        إدارة لجان الامتحانات
                    </h2>
                    <p className="text-slate-500 mt-1">توزيع المقاعد الذكي ومتابعة المراقبين (لائحة 501)</p>
                </div>
                <div className="flex gap-3 w-full md:w-auto">
                    <div className="relative flex-1 md:w-64">
                        <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input 
                            type="text" 
                            placeholder="بحث عن مقرر أو قاعة..."
                            className="w-full pr-10 pl-4 py-2 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                        />
                    </div>
                    {canManageAcademics && (
                        <button 
                            onClick={() => { resetForm(); setShowModal(true); }}
                            className="bg-blue-600 text-white px-5 py-2 rounded-xl flex items-center gap-2 hover:bg-blue-700 transition-all shadow-lg shadow-blue-200"
                        >
                            <Plus size={20} />
                            <span>إضافة امتحان</span>
                        </button>
                    )}
                </div>
            </div>

            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden print-area">
                <div className="hidden print:block text-center border-b-4 border-double border-slate-800 pb-6 mb-8 pt-8 px-8">
                    <h1 className="text-3xl font-extrabold mb-2 underline underline-offset-8">الجدول الزمني المعتمد للامتحانات</h1>
                    <p className="text-lg font-bold">للفصل الدراسي الحالي م</p>
                </div>

                {Object.keys(groupedExams).length > 0 ? (
                    Object.entries(groupedExams).map(([date, dateExams]) => (
                        <div key={date} className="border-b border-slate-100 last:border-0">
                            <div className="bg-slate-50 px-8 py-4 font-extrabold text-slate-800 flex items-center gap-3 border-b border-slate-100 sticky top-0 z-10 print:bg-white print:border-b-2 print:border-slate-800">
                                <Calendar size={20} className="text-blue-600 print:text-black"/>
                                <span className="text-lg">
                                    {new Date(date).toLocaleDateString('ar-LY', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
                                </span>
                            </div>
                            <div className="divide-y divide-slate-50 px-4">
                                {dateExams.sort((a,b) => a.startTime.localeCompare(b.startTime)).map(exam => (
                                    <div key={exam.id} className="p-6 hover:bg-slate-50/80 transition-colors flex flex-col md:flex-row md:items-center justify-between gap-6 group">
                                        <div className="flex-1 flex gap-6">
                                            <div className="w-24 shrink-0 flex flex-col items-center justify-center border-l border-slate-200 ps-4 print:border-slate-800">
                                                <span className="text-xl font-black text-slate-900 font-mono">{exam.startTime}</span>
                                                <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">البدء</span>
                                            </div>
                                            <div className="flex-1">
                                                <div className="flex items-center gap-3 mb-2">
                                                    <h3 className="font-black text-slate-800 text-xl">{exam.courseName}</h3>
                                                    <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded-full text-slate-500 font-mono border font-bold">{exam.courseId}</span>
                                                </div>
                                                <div className="flex flex-wrap gap-x-6 gap-y-2 mt-3 text-sm text-slate-600 font-medium">
                                                    <div className="flex items-center gap-2 bg-blue-50/50 text-blue-700 px-3 py-1 rounded-lg border border-blue-100 print:bg-white print:border-0 print:text-black">
                                                        <Clock size={16}/>
                                                        <span>المدة: {exam.durationMinutes} دقيقة</span>
                                                    </div>
                                                    <div className="flex items-center gap-2 bg-red-50/50 text-red-700 px-3 py-1 rounded-lg border border-red-100 print:bg-white print:border-0 print:text-black">
                                                        <MapPin size={16}/>
                                                        <span>اللجنة: {exam.room}</span>
                                                    </div>
                                                    <div className="flex items-center gap-2 bg-purple-50/50 text-purple-700 px-3 py-1 rounded-lg border border-purple-100 print:bg-white print:border-0 print:text-black">
                                                        <UserCheck size={16}/>
                                                        <span>{exam.invigilators.length} مراقبين</span>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="no-print flex gap-2">
                                            <button 
                                                onClick={() => { setSelectedExam(exam); setShowSeatingModal(true); }}
                                                className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all flex items-center gap-1 font-bold text-xs"
                                            >
                                                <LayoutGrid size={18} /> مخطط المقاعد
                                            </button>
                                            <button 
                                                onClick={() => { setSelectedExam(exam); setShowTicketModal(true); }}
                                                className="p-2 text-green-600 hover:bg-green-50 rounded-xl transition-all flex items-center gap-1 font-bold text-xs"
                                            >
                                                <Printer size={18} /> بطاقات المراقبة
                                            </button>
                                            {canManageAcademics && (
                                                <button 
                                                    onClick={() => handleDelete(exam.id)}
                                                    className="p-2.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all"
                                                >
                                                    <Trash2 size={20} />
                                                </button>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))
                ) : (
                    <div className="p-24 text-center text-slate-400 flex flex-col items-center">
                        <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                            <AlertCircle size={40} className="opacity-20"/>
                        </div>
                        <p className="text-lg font-bold text-slate-500">لا توجد امتحانات مجدولة حالياً</p>
                    </div>
                )}
            </div>

            {/* Seating Plan Modal */}
            {showSeatingModal && selectedExam && (
                <div className="fixed inset-0 bg-slate-900/60 z-[60] flex items-center justify-center p-4 backdrop-blur-sm no-print">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col border border-slate-200">
                        <div className="bg-slate-900 text-white p-5 flex justify-between items-center">
                            <div className="flex items-center gap-3">
                                <LayoutGrid className="text-indigo-400" />
                                <h3 className="text-xl font-black">مخطط جلوس الطلاب: {selectedExam.courseName}</h3>
                            </div>
                            <button onClick={() => setShowSeatingModal(false)}><X /></button>
                        </div>
                        <div className="p-8 flex-1 overflow-auto bg-slate-50">
                            <div className="bg-white rounded-xl shadow-sm border p-6 mb-6">
                                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6 pb-6 border-b">
                                    <div><p className="text-xs text-slate-400 font-bold uppercase">القاعة</p><p className="font-bold">{selectedExam.room}</p></div>
                                    <div><p className="text-xs text-slate-400 font-bold uppercase">التاريخ</p><p className="font-bold">{selectedExam.date}</p></div>
                                    <div><p className="text-xs text-slate-400 font-bold uppercase">الطلاب</p><p className="font-bold">{selectedExam.seatingPlan?.length || 0} طالب</p></div>
                                    <div><p className="text-xs text-slate-400 font-bold uppercase">الحالة</p><p className="text-green-600 font-bold">موزع آلياً</p></div>
                                </div>
                                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
                                    {selectedExam.seatingPlan?.map(seat => (
                                        <div key={seat.studentId} className="flex items-center gap-4 p-3 bg-slate-50 rounded-xl border border-slate-100 hover:border-indigo-300 transition-colors group">
                                            <div className="w-10 h-10 rounded-lg bg-indigo-600 text-white flex items-center justify-center font-black shadow-md group-hover:scale-110 transition-transform">
                                                {seat.seatNumber}
                                            </div>
                                            <div className="overflow-hidden">
                                                <p className="text-sm font-bold text-slate-800 truncate">{seat.studentName}</p>
                                                <p className="text-[10px] text-slate-400 font-mono">{seat.studentId}</p>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                        <div className="p-4 bg-white border-t flex justify-end gap-2">
                             <button onClick={() => window.print()} className="px-6 py-2 bg-slate-800 text-white rounded-xl font-bold flex items-center gap-2"><Printer size={18}/> طباعة الكشوفات</button>
                             <button onClick={() => setShowSeatingModal(false)} className="px-6 py-2 bg-slate-100 text-slate-600 rounded-xl font-bold">إغلاق</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Invigilator Ticket Modal */}
            {showTicketModal && selectedExam && (
                <div className="fixed inset-0 bg-slate-900/60 z-[60] flex items-center justify-center p-4 backdrop-blur-sm no-print">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col border border-slate-200">
                        <div className="bg-green-600 text-white p-5 flex justify-between items-center">
                            <div className="flex items-center gap-3">
                                <Award className="text-white" />
                                <h3 className="text-xl font-black">بطاقات تكليف المراقبين</h3>
                            </div>
                            <button onClick={() => setShowTicketModal(false)}><X /></button>
                        </div>
                        <div className="p-8 flex-1 overflow-auto bg-slate-100">
                            <div id="tickets-area" className="space-y-8">
                                {selectedExam.invigilators.map(id => {
                                    const inst = instructors.find(i => i.id === id);
                                    return (
                                        <div key={id} className="bg-white border-4 border-slate-800 p-6 rounded-none relative overflow-hidden">
                                            <div className="absolute top-0 right-0 p-4 opacity-5"><Printer size={100}/></div>
                                            <div className="text-center border-b-2 border-slate-800 pb-4 mb-4">
                                                <h4 className="text-lg font-black underline uppercase tracking-widest">تذكرة تكليف بمراقبة امتحان</h4>
                                            </div>
                                            <div className="grid grid-cols-2 gap-y-4 text-sm">
                                                <div><span className="text-slate-400 font-bold ml-2">المراقب:</span> <span className="font-black text-slate-800">{inst?.name}</span></div>
                                                <div><span className="text-slate-400 font-bold ml-2">المقرر:</span> <span className="font-black text-slate-800">{selectedExam.courseName}</span></div>
                                                <div><span className="text-slate-400 font-bold ml-2">التاريخ:</span> <span className="font-bold">{selectedExam.date}</span></div>
                                                <div><span className="text-slate-400 font-bold ml-2">الوقت:</span> <span className="font-bold">{selectedExam.startTime}</span></div>
                                                <div><span className="text-slate-400 font-bold ml-2">القاعة:</span> <span className="font-black text-red-600">{selectedExam.room}</span></div>
                                                <div><span className="text-slate-400 font-bold ml-2">عدد الطلاب:</span> <span className="font-bold">{selectedExam.seatingPlan?.length || 0}</span></div>
                                            </div>
                                            <div className="mt-8 pt-4 border-t border-dashed flex justify-between items-end">
                                                <div className="text-[10px] text-slate-400 font-mono">Ref: {selectedExam.id}/{id}</div>
                                                <div className="text-center">
                                                    <p className="text-[10px] font-bold mb-6">توقيع المسجل العام</p>
                                                    <div className="w-24 border-t border-slate-300 mx-auto"></div>
                                                </div>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                        <div className="p-4 bg-white border-t flex justify-end gap-2">
                             <button onClick={() => window.print()} className="px-6 py-2 bg-green-600 text-white rounded-xl font-bold flex items-center gap-2"><Printer size={18}/> طباعة التذاكر</button>
                             <button onClick={() => setShowTicketModal(false)} className="px-6 py-2 bg-slate-100 text-slate-600 rounded-xl font-bold">إغلاق</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Existing Add Exam Modal with conflict awareness */}
            {showModal && (
                <div className="fixed inset-0 bg-slate-900/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm no-print">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-xl overflow-hidden animate-in fade-in zoom-in duration-200 border border-slate-200">
                        <div className="bg-slate-900 text-white p-5 flex justify-between items-center">
                            <h3 className="text-xl font-black flex items-center gap-3">
                                <Calendar size={24} className="text-blue-400" />
                                {currentExam.id ? 'تعديل موعد امتحان' : 'جدولة امتحان جديد'}
                            </h3>
                            <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-white p-2 rounded-lg hover:bg-slate-800 transition-colors">
                                <X size={24} />
                            </button>
                        </div>

                        <form onSubmit={handleSave} className="p-8 space-y-6">
                            <div>
                                <label className="block text-sm font-black text-slate-700 mb-2">المقرر الدراسي</label>
                                <select 
                                    required
                                    className="w-full border-2 border-slate-100 bg-slate-50 rounded-xl px-4 py-3 focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none transition-all font-bold"
                                    value={currentExam.courseId}
                                    onChange={e => setCurrentExam({...currentExam, courseId: e.target.value})}
                                >
                                    <option value="">اختر المقرر...</option>
                                    {courses.map(c => (
                                        <option key={c.id} value={c.id}>{c.name} ({c.code})</option>
                                    ))}
                                </select>
                            </div>

                            <div className="grid grid-cols-2 gap-6">
                                <div>
                                    <label className="block text-sm font-black text-slate-700 mb-2">تاريخ الانعقاد</label>
                                    <input 
                                        required
                                        type="date"
                                        className="w-full border-2 border-slate-100 bg-slate-50 rounded-xl px-4 py-3 focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none transition-all font-mono font-bold"
                                        value={currentExam.date}
                                        onChange={e => setCurrentExam({...currentExam, date: e.target.value})}
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-black text-slate-700 mb-2">وقت البدء</label>
                                    <input 
                                        required
                                        type="time"
                                        className="w-full border-2 border-slate-100 bg-slate-50 rounded-xl px-4 py-3 focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none transition-all font-mono font-bold"
                                        value={currentExam.startTime}
                                        onChange={e => setCurrentExam({...currentExam, startTime: e.target.value})}
                                    />
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-6">
                                <div>
                                    <label className="block text-sm font-black text-slate-700 mb-2">المدة (دقيقة)</label>
                                    <input 
                                        required
                                        type="number"
                                        className="w-full border-2 border-slate-100 bg-slate-50 rounded-xl px-4 py-3 focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none transition-all font-bold"
                                        value={currentExam.durationMinutes}
                                        onChange={e => setCurrentExam({...currentExam, durationMinutes: parseInt(e.target.value)})}
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-black text-slate-700 mb-2">مكان الامتحان</label>
                                    <select 
                                        required
                                        className="w-full border-2 border-slate-100 bg-slate-50 rounded-xl px-4 py-3 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all font-bold"
                                        value={currentExam.room}
                                        onChange={e => setCurrentExam({...currentExam, room: e.target.value})}
                                    >
                                        <option value="">اختر القاعة...</option>
                                        {rooms.map(r => (
                                            <option key={r.id} value={r.name} disabled={!r.isAvailable}>
                                                {r.name} ({r.isAvailable ? `سعة ${r.capacity}` : 'صيانة'})
                                            </option>
                                        ))}
                                    </select>
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-black text-slate-700 mb-2">تعيين المراقبين</label>
                                <select 
                                    className="w-full border-2 border-slate-100 bg-slate-50 rounded-xl px-4 py-3 h-32 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all"
                                    multiple
                                    value={currentExam.invigilators}
                                    onChange={e => {
                                        const selected = Array.from(e.target.selectedOptions, (option: HTMLOptionElement) => option.value);
                                        setCurrentExam({...currentExam, invigilators: selected});
                                    }}
                                >
                                    {instructors.map(i => (
                                        <option key={i.id} value={i.id} className="p-1">{i.name} ({i.department})</option>
                                    ))}
                                </select>
                                <p className="text-[10px] text-slate-400 mt-2 flex items-center gap-1">
                                    <AlertCircle size={10} />
                                    اضغط CTRL لتحديد أكثر من مراقب. سيقوم النظام بمنع تضارب المواعيد تلقائياً.
                                </p>
                            </div>

                            <div className="pt-6 flex justify-end gap-4 border-t border-slate-100">
                                <button 
                                    type="button" 
                                    onClick={() => setShowModal(false)} 
                                    className="px-6 py-3 text-slate-500 hover:bg-slate-50 rounded-xl font-bold transition-all"
                                >
                                    إلغاء
                                </button>
                                <button 
                                    type="submit" 
                                    className="px-10 py-3 bg-blue-600 text-white rounded-xl font-black hover:bg-blue-700 shadow-xl shadow-blue-200 flex items-center gap-2"
                                >
                                    <Save size={20} />
                                    حفظ وتوزيع المقاعد
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

const toMinutes = (time: string) => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
};

export default ExamSchedule;

