                        <Bell size={20} className="animate-bounce" />
                    </div>
                    <div>
                        <p className="text-[10px] font-black uppercase opacity-60">تنبيه المواعيد النهائية</p>
                        <h4 className="font-black">باقي {regDiff} أيام على انتهاء تنزيل المواد</h4>
                    </div>
                </div>
            )}
            {payDiff <= 14 && (
                <div className={`p-4 rounded-3xl border flex items-center gap-4 ${payDiff < 3 ? 'bg-red-50 border-red-200 text-red-800' : 'bg-blue-50 border-blue-200 text-blue-800'}`}>
                    <div className={`p-3 rounded-2xl ${payDiff < 3 ? 'bg-red-100' : 'bg-blue-100'}`}>
                        <DollarSign size={20} />
