                    <button className="bg-white/10 hover:bg-white/20 px-6 py-3 rounded-2xl text-xs font-bold transition-all border border-white/10">اتخاذ إجراء إداري</button>
                </div>

                <div className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm">
                    <h4 className="font-black text-lg mb-6 text-slate-800">الحالة القانونية</h4>
                    <div className="h-40">
                         <ResponsiveContainer width="100%" height="100%">
