                                <Pie data={statusData} innerRadius={50} outerRadius={70} paddingAngle={5} dataKey="value">
                                    {statusData.map((entry, index) => <Cell key={index} fill={entry.color} />)}
                                </Pie>
                                <Tooltip />
                            </PieChart>
                         </ResponsiveContainer>
                    </div>
                </div>
            </div>
        </div>

        <div className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm flex flex-col h-full">
            <h3 className="font-black text-xl mb-8 text-slate-800 flex items-center gap-3">
                <History className="text-indigo-600" />
                سجل العمليات الأخير
            </h3>
            <div className="space-y-6 flex-1">
                {recentActivity.map((log) => (
                    <div key={log.id} className="flex gap-4 items-start group">
                        <div className={`mt-1.5 w-2 h-2 rounded-full shrink-0 group-hover:scale-150 transition-transform ${
                            log.type === 'danger' ? 'bg-red-500' : 'bg-indigo-500'
                        }`}></div>
                        <div>
                            <p className="text-sm font-black text-slate-800">{log.action}</p>
                            <p className="text-[10px] text-slate-400 font-medium mb-1">{new Date(log.timestamp).toLocaleTimeString('ar-LY')}</p>
                            <p className="text-xs text-slate-500 line-clamp-2 leading-relaxed">{log.details}</p>
                        </div>
                    </div>
                ))}
            </div>
            <button className="mt-8 w-full py-4 border-2 border-slate-50 rounded-3xl text-sm font-black text-slate-500 hover:bg-slate-50 transition-all">عرض كافة السجلات</button>
        </div>
      </div>
    </div>
  );
};

