export const importSystemData = (jsonString: string): boolean => {
  try {
    const data = JSON.parse(jsonString);
    if (!data.students || !data.courses || !data.settings) throw new Error("Invalid data");
    localStorage.setItem(STORAGE_KEY_STUDENTS, JSON.stringify(data.students));
    localStorage.setItem(STORAGE_KEY_COURSES, JSON.stringify(data.courses));
    localStorage.setItem(STORAGE_KEY_SETTINGS, JSON.stringify(data.settings));
    if (data.buildings) localStorage.setItem(STORAGE_KEY_BUILDINGS, JSON.stringify(data.buildings));
    if (data.rooms) localStorage.setItem(STORAGE_KEY_ROOMS, JSON.stringify(data.rooms));
    if (data.branches) localStorage.setItem(STORAGE_KEY_BRANCHES, JSON.stringify(data.branches));
    if (data.colleges) localStorage.setItem(STORAGE_KEY_COLLEGES, JSON.stringify(data.colleges));
    if (data.departments) localStorage.setItem(STORAGE_KEY_DEPTS, JSON.stringify(data.departments));
    if (data.programs) localStorage.setItem(STORAGE_KEY_PROGRAMS, JSON.stringify(data.programs));
    if (data.sections) localStorage.setItem(STORAGE_KEY_SECTIONS, JSON.stringify(data.sections));
    if (data.staff) localStorage.setItem(STORAGE_KEY_STAFF, JSON.stringify(data.staff));
    return true;
  } catch (error) {
    console.error(error);
    return false;
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  getBranches, saveBranch, moveBranch,
  getColleges, saveCollege, moveCollege,
  getDepartments, saveDepartment, moveDepartment,
  getAcademicPrograms, saveAcademicProgram, moveProgram,
  getSections, saveSection, moveSection,
  getStaff
} from '../services/storageService';
import { Branch, College, Department, AcademicProgram, Section, ProgramType, Permission, StaffMember } from '../types';
import { 
  Network, Landmark, Building2, BookOpen, Layers, 
  Plus, Edit2, Save, X, ChevronRight, ChevronDown, MapPin, User, Search, Trash2, FolderPlus,
  Users, GraduationCap, GripVertical, Filter
} from 'lucide-react';
import { notifySuccess, notifyError, notifyInfo } from '../services/notificationService';
import { getCurrentUser, hasPermission } from '../services/authService';

type OrgLevel = 'branch' | 'college' | 'dept' | 'program' | 'section';

const UniversityManagement: React.FC = () => {
  const [viewMode, setViewMode] = useState<'tree' | 'cards'>('tree');
  const [activeTab, setActiveTab] = useState<OrgLevel>('branch');
  const [treeSearchTerm, setTreeSearchTerm] = useState('');

  const [branches, setBranches] = useState<Branch[]>([]);
  const [colleges, setColleges] = useState<College[]>([]);
  const [depts, setDepts] = useState<Department[]>([]);
  const [programs, setPrograms] = useState<AcademicProgram[]>([]);
  const [sections, setSections] = useState<Section[]>([]);
  const [staff, setStaff] = useState<StaffMember[]>([]);

  const [showModal, setShowModal] = useState(false);
  const [editItem, setEditItem] = useState<any>(null);
  const [modalLevel, setModalLevel] = useState<OrgLevel>('branch');
  const [parentId, setParentId] = useState<string | null>(null);

  const currentUser = getCurrentUser();
  const canManage = hasPermission(currentUser, Permission.ORGANIZATION_MANAGE);

  useEffect(() => {
    refresh();
  }, []);

  const refresh = () => {
    setBranches(getBranches());
    setColleges(getColleges());
    setDepts(getDepartments());
    setPrograms(getAcademicPrograms());
    setSections(getSections());
    setStaff(getStaff());
  };

  const handleOpenAdd = (level: OrgLevel, pId: string | null = null) => {
    if (!canManage) return;
    setEditItem(null);
    setModalLevel(level);
    setParentId(pId);
    setShowModal(true);
  };

  const handleOpenEdit = (level: OrgLevel, item: any) => {
    if (!canManage) return;
    setEditItem(item);
    setModalLevel(level);
    setShowModal(true);
  };

  const handleDrop = (level: OrgLevel, sourceId: string, targetId: string) => {
      if (sourceId === targetId) return;

      if (level === 'branch') moveBranch(sourceId, targetId);
      else if (level === 'college') moveCollege(sourceId, targetId);
      else if (level === 'dept') moveDepartment(sourceId, targetId);
      else if (level === 'program') moveProgram(sourceId, targetId);
      else if (level === 'section') moveSection(sourceId, targetId);

      refresh();
      notifySuccess('تم تحديث الترتيب بنجاح');
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);

    if (modalLevel === 'branch') {
      saveBranch({ 
        id: editItem?.id || `BR-${Date.now()}`, 
        name: formData.get('name') as string,
        location: formData.get('location') as string 
      });
    } else if (modalLevel === 'college') {
      saveCollege({
        id: editItem?.id || `COL-${Date.now()}`,
        branchId: (formData.get('branchId') as string) || parentId || '',
        name: formData.get('name') as string,
        deanName: formData.get('deanName') as string
      });
    } else if (modalLevel === 'dept') {
      saveDepartment({
        id: editItem?.id || `DEPT-${Date.now()}`,
        collegeId: (formData.get('collegeId') as string) || parentId || '',
        name: formData.get('name') as string,
        headName: formData.get('headName') as string
      });
    } else if (modalLevel === 'program') {
      saveAcademicProgram({
        id: editItem?.id || `PRG-${Date.now()}`,
        deptId: (formData.get('deptId') as string) || parentId || '',
        name: formData.get('name') as string,
        type: formData.get('type') as ProgramType,
        durationSemesters: parseInt(formData.get('duration') as string)
      });
    } else if (modalLevel === 'section') {
      saveSection({
        id: editItem?.id || `SEC-${Date.now()}`,
        programId: (formData.get('programId') as string) || parentId || '',
        name: formData.get('name') as string
      });
    }

    notifySuccess('تم حفظ البيانات بنجاح');
    setShowModal(false);
    refresh();
  };

  return (
    <div className="p-8">
      <div className="mb-8 flex justify-between items-start">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <Network className="text-blue-600" />
            الهيكل التنظيمي الأكاديمي
          </h2>
          <p className="text-slate-500 mt-1 font-medium">تحكم شامل في البناء المؤسسي، الترتيب، والبحث الهرمي</p>
        </div>
        <div className="flex gap-2 bg-white p-1 rounded-xl border shadow-sm">
            <button 
                onClick={() => setViewMode('tree')}
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'tree' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
                العرض الشجري
            </button>
            <button 
                onClick={() => setViewMode('cards')}
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'cards' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
                عرض القوائم
            </button>
        </div>
      </div>

      {viewMode === 'tree' ? (
        <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden min-h-[700px] animate-in fade-in duration-500">
            <div className="p-6 bg-slate-50/50 border-b flex flex-col md:flex-row gap-4 items-center justify-between sticky top-0 z-20 backdrop-blur-md">
                <div className="relative w-full md:w-96">
                    <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input 
                        type="text" 
                        placeholder="ابحث في الهيكل..."
                        className="w-full pr-10 pl-4 py-2.5 rounded-2xl border-2 border-slate-100 focus:border-blue-500 focus:bg-white outline-none transition-all font-bold text-slate-700"
                        value={treeSearchTerm}
                        onChange={e => setTreeSearchTerm(e.target.value)}
                    />
                    {treeSearchTerm && (
                        <button onClick={() => setTreeSearchTerm('')} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500">
                            <X size={16} />
                        </button>
                    )}
                </div>
                <div className="flex gap-2 items-center text-xs font-bold text-slate-400">
                    <div className="w-3 h-3 rounded bg-blue-600"></div> فرع
                    <div className="w-3 h-3 rounded bg-indigo-500"></div> كلية
                    <div className="w-3 h-3 rounded bg-teal-500"></div> قسم
                    {canManage && (
                        <button onClick={() => handleOpenAdd('branch')} className="mr-4 bg-blue-600 text-white px-5 py-2.5 rounded-2xl text-xs font-black flex items-center gap-2 hover:bg-blue-700 transition-all shadow-lg shadow-blue-200">
                            <Plus size={18} /> إضافة فرع رئيسي
                        </button>
                    )}
                </div>
            </div>

            <div className="p-8 max-w-5xl mx-auto space-y-6">
                {branches.length > 0 ? branches.map(branch => (
                    <TreeNode 
                        key={branch.id} 
                        item={branch} 
                        level="branch" 
                        canManage={canManage}
                        onAddChild={(l, p) => handleOpenAdd(l, p)}
                        onEdit={(l, i) => handleOpenEdit(l, i)}
                        onDrop={(l, s, t) => handleDrop(l, s, t)}
                        searchTerm={treeSearchTerm}
                        childrenData={{colleges, depts, programs, sections, staff}}
                    />
                )) : (
                    <div className="text-center py-24 text-slate-300">
                        <Network size={64} className="mx-auto mb-4 opacity-10" />
                        <p className="font-bold text-lg">لم يتم بناء الهيكل التنظيمي بعد</p>
                    </div>
                )}
            </div>
        </div>
      ) : (
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col min-h-[600px] animate-in slide-in-from-bottom-4 duration-300">
          <div className="flex border-b border-slate-200 bg-slate-50 px-6 pt-4 gap-4 overflow-x-auto no-scrollbar">
            {(['branch', 'college', 'dept', 'program', 'section'] as OrgLevel[]).map(lvl => (
                <button 
                  key={lvl}
                  onClick={() => setActiveTab(lvl)} 
                  className={`pb-4 px-4 text-sm font-bold border-b-2 flex items-center gap-2 transition-all ${activeTab === lvl ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500'}`}
                >
                  {lvl === 'branch' && <MapPin size={18} />}
                  {lvl === 'college' && <Landmark size={18} />}
                  {lvl === 'dept' && <Building2 size={18} />}
                  {lvl === 'program' && <BookOpen size={18} />}
                  {lvl === 'section' && <Layers size={18} />}
                  {lvl === 'branch' ? 'الفروع' : lvl === 'college' ? 'الكليات' : lvl === 'dept' ? 'الأقسام' : lvl === 'program' ? 'البرامج' : 'الشُعب'}
                </button>
            ))}
          </div>

          <div className="p-6 flex-1">
            <div className="flex justify-between items-center mb-6">
              <h3 className="font-bold text-slate-700">سجل الإدخالات المباشرة</h3>
              {canManage && (
                <button onClick={() => handleOpenAdd(activeTab)} className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700 shadow-sm transition-all">
                  <Plus size={18} /> إضـافة
                </button>
              )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {activeTab === 'branch' && branches.map(item => (
                <DirectCard key={item.id} title={item.name} sub={item.location} icon={MapPin} onEdit={() => handleOpenEdit('branch', item)} canManage={canManage} />
              ))}
              {activeTab === 'college' && colleges.map(item => (
                <DirectCard key={item.id} title={item.name} sub={`العميد: ${item.deanName || '---'}`} icon={Landmark} onEdit={() => handleOpenEdit('college', item)} canManage={canManage} />
              ))}
              {activeTab === 'dept' && depts.map(item => (
                <DirectCard key={item.id} title={item.name} sub={`رئيس القسم: ${item.headName || '---'}`} icon={Building2} onEdit={() => handleOpenEdit('dept', item)} canManage={canManage} />
              ))}
              {activeTab === 'program' && programs.map(item => (
                <DirectCard key={item.id} title={item.name} sub={`النوع: ${item.type} | الفصول: ${item.durationSemesters}`} icon={BookOpen} onEdit={() => handleOpenEdit('program', item)} canManage={canManage} />
              ))}
              {activeTab === 'section' && sections.map(item => (
                <DirectCard key={item.id} title={item.name} sub="تخصص دقيق" icon={Layers} onEdit={() => handleOpenEdit('section', item)} canManage={canManage} />
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Modal remains same logic, updated appearance */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in duration-200 border border-slate-200">
            <div className="bg-slate-900 text-white p-6 flex justify-between items-center">
              <h3 className="text-xl font-black flex items-center gap-2">
                  <Plus className="text-blue-400" />
                  {editItem ? 'تعديل السجل' : 'إضافة مدخل جديد'}
              </h3>
              <button onClick={() => setShowModal(false)} className="bg-white/10 hover:bg-white/20 p-2 rounded-xl transition-all"><X size={20} /></button>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-5">
              {modalLevel === 'branch' && (
                <>
                  <FormInput label="اسم الفرع" name="name" defaultValue={editItem?.name} />
                  <FormInput label="الموقع الجغرافي" name="location" defaultValue={editItem?.location} />
                </>
              )}
              {modalLevel === 'college' && (
                <>
                  {!parentId && (
                    <FormSelect label="الفرع التابع له" name="branchId" defaultValue={editItem?.branchId}>
                        {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
                    </FormSelect>
                  )}
                  <FormInput label="اسم الكلية" name="name" defaultValue={editItem?.name} />
                  <FormInput label="اسم العميد" name="deanName" defaultValue={editItem?.deanName} />
                </>
              )}
              {modalLevel === 'dept' && (
                <>
                  {!parentId && (
                    <FormSelect label="الكلية" name="collegeId" defaultValue={editItem?.collegeId}>
                        {colleges.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </FormSelect>
                  )}
                  <FormInput label="اسم القسم" name="name" defaultValue={editItem?.name} />
                  <FormInput label="رئيس القسم" name="headName" defaultValue={editItem?.headName} />
                </>
              )}
              {modalLevel === 'program' && (
                <>
                  {!parentId && (
                    <FormSelect label="القسم العلمي" name="deptId" defaultValue={editItem?.deptId}>
                        {depts.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                    </FormSelect>
                  )}
                  <FormInput label="اسم البرنامج" name="name" defaultValue={editItem?.name} />
                  <FormSelect label="نوع الدرجة" name="type" defaultValue={editItem?.type}>
                    <option value={ProgramType.UNDERGRADUATE}>بكالوريوس (جامعي)</option>
                    <option value={ProgramType.POSTGRADUATE}>ماجستير/دكتوراه (دراسات عليا)</option>
                  </FormSelect>
                  <FormInput label="عدد الفصول المقررة" name="duration" type="number" defaultValue={editItem?.durationSemesters} />
                </>
              )}
              {modalLevel === 'section' && (
                <>
                  {!parentId && (
                    <FormSelect label="البرنامج العلمي" name="programId" defaultValue={editItem?.programId}>
                        {programs.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                    </FormSelect>
                  )}
                  <FormInput label="اسم الشعبة / التخصص" name="name" defaultValue={editItem?.name} />
                </>
              )}
              <div className="pt-6 flex justify-end gap-3 border-t">
                <button type="button" onClick={() => setShowModal(false)} className="px-6 py-2 text-slate-500 font-bold hover:bg-slate-50 rounded-xl transition-all">إلغاء</button>
                <button type="submit" className="bg-blue-600 text-white px-10 py-3 rounded-2xl font-black hover:bg-blue-700 shadow-xl shadow-blue-200 transition-all active:scale-95">حفظ التغييرات</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const TreeNode = ({ item, level, canManage, onAddChild, onEdit, onDrop, childrenData, searchTerm }: any) => {
    const [isInternalOpen, setIsInternalOpen] = useState(level === 'branch');
    const [showStaff, setShowStaff] = useState(false);
    const [isDraggingOver, setIsDraggingOver] = useState(false);

    // Auto open when searching
    useEffect(() => {
        if (searchTerm) setIsInternalOpen(true);
    }, [searchTerm]);

    let children: any[] = [];
    let childLevel: OrgLevel | null = null;
    let Icon = MapPin;
    let label = "";

    const staffHere = childrenData.staff.filter((s: StaffMember) => {
      if (level === 'branch') return s.branchId === item.id && !s.collegeId;
      if (level === 'college') return s.collegeId === item.id && !s.deptId;
      if (level === 'dept') return s.deptId === item.id;
      return false;
    });

    if (level === 'branch') {
        children = childrenData.colleges.filter((c: any) => c.branchId === item.id);
        childLevel = 'college';
        Icon = MapPin;
        label = "فرع رئيسي";
    } else if (level === 'college') {
        children = childrenData.depts.filter((d: any) => d.collegeId === item.id);
        childLevel = 'dept';
        Icon = Landmark;
        label = "كلية";
    } else if (level === 'dept') {
        children = childrenData.programs.filter((p: any) => p.deptId === item.id);
        childLevel = 'program';
        Icon = Building2;
        label = "قسم علمي";
    } else if (level === 'program') {
        children = childrenData.sections.filter((s: any) => s.programId === item.id);
        childLevel = 'section';
        Icon = BookOpen;
        label = "برنامج أكاديمي";
    } else {
        Icon = Layers;
        label = "شعبة دقيقة";
    }

    const isMatch = item.name.toLowerCase().includes(searchTerm.toLowerCase());

    const hasVisibleChild = useMemo(() => {
        if (!searchTerm) return true;
        const checkChildren = (items: any[], lvl: OrgLevel): boolean => {
            return items.some(it => {
                if (it.name.toLowerCase().includes(searchTerm.toLowerCase())) return true;
                if (lvl === 'college') return checkChildren(childrenData.depts.filter((d: any) => d.collegeId === it.id), 'dept');
                if (lvl === 'dept') return checkChildren(childrenData.programs.filter((p: any) => p.deptId === it.id), 'program');
                if (lvl === 'program') return checkChildren(childrenData.sections.filter((s: any) => s.programId === it.id), 'section');
                return false;
            });
        };
        return isMatch || checkChildren(children, childLevel!);
    }, [searchTerm, item.name, children, childLevel, childrenData]);

    if (!hasVisibleChild) return null;

    const hasAnyChildren = children.length > 0 || staffHere.length > 0;

    // --- Drag and Drop Handlers ---
    const onDragStart = (e: React.DragEvent) => {
        e.dataTransfer.setData('text/plain', item.id);
        e.dataTransfer.setData('level', level);
        e.dataTransfer.effectAllowed = 'move';
    };

    const onDragOver = (e: React.DragEvent) => {
        const sourceLevel = e.dataTransfer.types.includes('level') ? e.dataTransfer.getData('level') : level; 
        // Need to check level but e.dataTransfer.getData is empty during dragover in some browsers
        // So we assume the user is dragging same level items for simplicity in native DnD
        e.preventDefault();
        setIsDraggingOver(true);
    };

    const onDragLeave = () => {
        setIsDraggingOver(false);
    };

    const onDropHandler = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDraggingOver(false);
        const sourceId = e.dataTransfer.getData('text/plain');
        onDrop(level, sourceId, item.id);
    };

    return (
        <div 
            className={`mr-4 mb-2 select-none border-r-2 border-slate-100 pr-4 animate-in slide-in-from-right-1 duration-300 transition-all ${isDraggingOver ? 'pt-8' : ''}`}
            onDragOver={onDragOver}
            onDragLeave={onDragLeave}
            onDrop={onDropHandler}
        >
            <div 
                draggable={canManage}
                onDragStart={onDragStart}
                className={`flex items-center justify-between p-4 rounded-3xl transition-all group border-2 ${
                isMatch && searchTerm ? 'bg-indigo-50 border-indigo-200 shadow-lg shadow-indigo-100' : 'hover:bg-slate-50/80 border-transparent'
            } ${canManage ? 'cursor-grab active:cursor-grabbing' : ''}`}
            >
                <div className="flex items-center gap-4 flex-1">
                    <div onClick={() => setIsInternalOpen(!isInternalOpen)} className="cursor-pointer hover:bg-white p-1 rounded-lg transition-colors">
                        {hasAnyChildren ? (
                            isInternalOpen ? <ChevronDown size={20} className="text-slate-400" /> : <ChevronRight size={20} className="text-slate-400" />
                        ) : (
                            <div className="w-[20px]"></div>
                        )}
                    </div>
                    {canManage && (
                        <div className="text-slate-300 opacity-0 group-hover:opacity-100 transition-opacity">
                            <GripVertical size={16} />
                        </div>
                    )}
                    <div className={`p-3 rounded-2xl shadow-sm ${
                        level === 'branch' ? 'bg-blue-600 text-white' :
                        level === 'college' ? 'bg-indigo-500 text-white' :
                        level === 'dept' ? 'bg-teal-500 text-white' :
                        level === 'program' ? 'bg-purple-500 text-white' :
                        'bg-slate-800 text-white'
                    }`}>
                        <Icon size={20} />
                    </div>
                    <div className="flex-1 min-w-0">
                        <span className="text-[10px] font-black text-slate-400 block uppercase tracking-widest leading-none mb-1.5">{label}</span>
                        <h4 className={`font-black truncate ${isMatch && searchTerm ? 'text-indigo-900' : 'text-slate-800'}`}>
                            {item.name}
                        </h4>
                        {level === 'branch' && <p className="text-[10px] text-slate-400 mt-0.5">{item.location}</p>}
                    </div>

                    {staffHere.length > 0 && (
                        <span className="px-3 py-1 bg-white border border-blue-100 text-blue-600 rounded-full text-[10px] font-black shadow-sm flex items-center gap-1.5">
                            <Users size={12}/> {staffHere.length} منتسب
                        </span>
                    )}
                </div>

                <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    {staffHere.length > 0 && (
                      <button onClick={() => setShowStaff(!showStaff)} className={`p-2 rounded-xl transition-all ${showStaff ? 'bg-blue-600 text-white shadow-lg' : 'bg-white border text-blue-600 hover:bg-blue-50'}`} title="عرض الطاقم الإداري/الأكاديمي">
                        <Users size={18} />
                      </button>
                    )}
                    {canManage && childLevel && (
                        <button 
                            onClick={() => onAddChild(childLevel, item.id)}
                            className="p-2 bg-white border border-slate-100 text-emerald-600 hover:bg-emerald-50 rounded-xl shadow-sm tooltip"
                            title={`إضافة ${childLevel === 'college' ? 'كلية' : childLevel === 'dept' ? 'قسم' : childLevel === 'program' ? 'برنامج' : 'شعبة'}`}
                        >
                            <FolderPlus size={18} />
                        </button>
                    )}
                    {canManage && (
                        <button 
                            onClick={() => onEdit(level, item)}
                            className="p-2 bg-white border border-slate-100 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl shadow-sm"
                        >
                            <Edit2 size={18} />
                        </button>
                    )}
                </div>
            </div>

            {isInternalOpen && (
                <div className="mt-4 animate-in slide-in-from-top-1 duration-300">
                    {showStaff && staffHere.map((s: StaffMember) => (
                      <div key={s.id} className="flex items-center gap-4 p-3 ms-10 border-r-2 border-dashed border-indigo-200 mb-2 bg-white rounded-2xl shadow-sm hover:border-solid hover:border-indigo-400 transition-all group/staff">
                        <div className="w-10 h-10 rounded-xl bg-indigo-50 border border-indigo-100 flex items-center justify-center text-indigo-600 group-hover/staff:bg-indigo-600 group-hover/staff:text-white transition-colors">
                          {s.type === 'ACADEMIC' ? <GraduationCap size={20}/> : <User size={20}/>}
                        </div>
                        <div>
                          <p className="text-sm font-black text-slate-800">{s.name}</p>
                          <p className="text-[10px] font-bold text-slate-400 uppercase">{s.position}</p>
                        </div>
                      </div>
                    ))}
                    {children.map(child => (
                        <TreeNode 
                            key={child.id} 
                            item={child} 
                            level={childLevel} 
                            canManage={canManage}
                            onAddChild={onAddChild}
                            onEdit={onEdit}
                            onDrop={onDrop}
                            searchTerm={searchTerm}
                            childrenData={childrenData}
                        />
                    ))}
                </div>
            )}
        </div>
    );
};

const DirectCard = ({ title, sub, icon: Icon, onEdit, canManage }: any) => (
  <div className="bg-white border border-slate-200 p-6 rounded-3xl hover:shadow-xl transition-all group flex items-center justify-between hover:border-blue-200">
    <div className="flex items-center gap-4">
      <div className="bg-blue-50 text-blue-600 p-4 rounded-2xl group-hover:bg-blue-600 group-hover:text-white transition-colors shadow-sm">
        <Icon size={24} />
      </div>
      <div>
        <h4 className="font-black text-slate-800">{title}</h4>
        <p className="text-xs font-bold text-slate-400 mt-1">{sub}</p>
      </div>
    </div>
    {canManage && (
        <button onClick={onEdit} className="p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all opacity-0 group-hover:opacity-100">
            <Edit2 size={20} />
        </button>
    )}
  </div>
);

const FormInput = ({ label, name, defaultValue, type = "text" }: any) => (
  <div>
    <label className="block text-sm font-black text-slate-700 mb-2 uppercase tracking-tighter">{label}</label>
    <input name={name} defaultValue={defaultValue} type={type} required className="w-full border-2 border-slate-100 bg-slate-50 rounded-2xl px-5 py-3 focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 focus:bg-white outline-none transition-all font-bold text-slate-700" />
  </div>
);

const FormSelect = ({ label, name, children, defaultValue }: any) => (
  <div>
    <label className="block text-sm font-black text-slate-700 mb-2 uppercase tracking-tighter">{label}</label>
    <select name={name} defaultValue={defaultValue} className="w-full border-2 border-slate-100 bg-slate-50 rounded-2xl px-5 py-3 focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 focus:bg-white outline-none transition-all font-bold text-slate-700 appearance-none">
      {children}
    </select>
  </div>
);

export default UniversityManagement;
